const pagination=n=>`<div class="pagination"><span>${n?Math.min((pageNo-1)*rowsPerPage+1,n):0}–${Math.min(pageNo*rowsPerPage,n)} of ${n} records</span><div class="row"><label class="small muted">Rows <select aria-label="Rows per page" onchange="rowsPerPage=Number(this.value);pageNo=1;selected.clear();render()">${[10,20,50,100].map(n=>`<option ${rowsPerPage===n?'selected':''}>${n}</option>`).join('')}</select></label><button ${pageNo===1?'disabled':''} onclick="pageNo--;render()">Previous</button><span>Page ${pageNo} / ${Math.max(1,Math.ceil(n/rowsPerPage))}</span><button ${pageNo*rowsPerPage>=n?'disabled':''} onclick="pageNo++;render()">Next</button></div></div>`;
function customersView(){let cs=visibleCustomers().filter(matchesFollowupFilters).filter(c=>(page!=='permanent'||c.permanent)&&(!query||[c.name,c.phone,c.address].join(' ').toLowerCase().includes(query.toLowerCase()))&&(!tagFilter||c.tag===tagFilter)&&(!window.callFilter||c.call===window.callFilter)&&(!window.responseFilter||c.response===window.responseFilter)&&(!window.customerSource||c.source===window.customerSource)&&(!window.funnelFilter||(window.funnelFilter==='attempted'?!!c.call:window.funnelFilter==='notattempted'?!c.call:!!c.call&&!confirmedStatus(c.status)))&&(subtab==='All'||subtab==='pendingqueue'&&c.agent&&pendingStatus(c.status)||subtab==='completed'&&c.call&&!pendingStatus(c.status)||subtab==='Confirmed'&&confirmedStatus(c.status)||subtab==='Unassigned'&&!c.agent||subtab==='Assigned'&&c.agent||subtab==='Permanent'&&c.permanent||subtab==='Due Today'&&callbackDueToday(c)||c.status===subtab));return heading(page==='permanent'?'Relationships that last.':role==='Agent'?'Your next conversation.':'Every customer. One profile.', 'One phone number, one follow-up. All their orders stay together.',`${role!=='Agent'?'<button onclick="nav(\'import\')">'+ico('upload')+' Import</button>':''}<button class="dark" onclick="customerForm()">${ico('plus')} Add Customer</button>`)+`<section class="card"><div class="tabs">${['All','Unassigned','Assigned','Permanent','Due Today',...db.settings.statuses].map((s,i)=>`<button class="${subtab===s?'active':''}" onclick="setCustomerTab(${i})">${esc(s)}</button>`).join('')}</div><div class="toolbar"><input aria-label="Search customers" placeholder="Search name, phone or address" style="max-width:320px" value="${esc(query)}" onchange="query=this.value;pageNo=1;render()"><div class="row"><span id="selection-count" class="muted small">${selected.size} selected</span>${role!=='Agent'?'<button onclick="assignDialog()">Assign selected</button><button onclick="unassignDialog()">Unassign</button>':permitted('pull')?'<button class="primary" onclick="pullOrders()">Take More Orders</button>':''}</div></div>${window.callFilter||window.responseFilter||window.customerSource||window.funnelFilter||['pendingqueue','completed'].includes(subtab)?`<div class="notice">Dashboard filter: ${esc([window.callFilter,window.responseFilter,window.customerSource,window.funnelFilter,['pendingqueue','completed'].includes(subtab)?subtab:''].filter(Boolean).join(' · '))} <button onclick="nav('customers')">Clear filter</button></div>`:''}<details><summary class="small muted" style="cursor:pointer">Tags & return reasons ${tagFilter?'· '+esc(tagFilter):''}</summary><div class="tags"><button onclick="tagFilter='';render()" class="${!tagFilter?'active':''}">All tags</button>${db.settings.tags.map((t,i)=>`<button onclick="tagFilter=db.settings.tags[${i}];pageNo=1;render()" class="${tagFilter===t?'active':''}">${esc(t)} <span class="muted">${db.customers.filter(c=>c.tag===t).length}</span></button>`).join('')}</div></details>${cs.length?(role==='Agent'&&currentAgent().processingView==='Card'?agentCustomerCards(cs):`<div class="table-wrap"><table><thead><tr><th><input type="checkbox" aria-label="Select displayed customers" onchange="selectCustomerPage(this.checked)"></th><th>Customer</th><th>Address / Source</th><th>Follow-up</th><th>Assigned to</th><th>Latest note</th><th>Orders</th><th>Next call</th><th></th></tr></thead><tbody>${cs.slice((pageNo-1)*rowsPerPage,pageNo*rowsPerPage).map(c=>`<tr><td><input type="checkbox" aria-label="Select ${esc(c.name)}" ${selected.has(c.id)?'checked':''} onchange="toggleSelected('${c.id}',this.checked)"></td><td><button class="link" onclick="showCustomer('${c.id}')"><strong>${esc(c.name)}</strong><small>${esc(c.phone)} ${c.permanent?'· Permanent':''}</small></button></td><td>${esc(c.address.slice(0,32))}<small>${esc(c.source)}</small></td><td>${badge(c.status)}${c.tag?`<small>${esc(c.tag)}</small>`:''}</td><td>${esc(agentName(c.agent))}</td><td>${customerNoteCell(c)}</td><td>${db.orders.filter(o=>o.customer===c.id).length}</td><td>${c.callback?esc(c.callback.replace('T',' ')):'—'}</td><td><button class="icon" aria-label="Open customer ${esc(c.name)}" onclick="showCustomer('${c.id}')">${ico('arrow')}</button></td></tr>`).join('')}</tbody></table></div>`):empty('No customers match this view.')}${pagination(cs.length)}</section>`}
function selectCustomerPage(on){const rows=$$('#view tbody input');rows.forEach(x=>{x.checked=on;x.dispatchEvent(new Event('change'))})}
function customerForm(id){const c=customer(id)||{};modal(id?'Edit customer':'Add customer','A single customer profile for each phone number.',`<form onsubmit="saveCustomer(event,'${id||''}')"><div class="form-grid">${field('Full name','name',c.name,'text','required')}${field('Phone number','phone',c.phone,'tel','required')}${field('Address','address',c.address,'text','required')}${selectField('Source','source',['Website','Facebook','CSV Import','Phone','WhatsApp','Other'],c.source||'Phone')}</div>${modalFooter()}</form>`)}
function normalizePhone(v){let p=String(v||'').replace(/[০-৯]/g,n=>'০১২৩৪৫৬৭৮৯'.indexOf(n)).replace(/\D/g,'');if(p.startsWith('880'))p=p.slice(2);if(p.length===10&&p.startsWith('1'))p='0'+p;return p}
function saveCustomer(e,id){e.preventDefault();const f=new FormData(e.target),p=normalizePhone(f.get('phone'));if(!/^01[3-9]\d{8}$/.test(p))return toast('Enter a valid Bangladesh mobile number.');const duplicate=db.customers.find(c=>c.phone===p&&c.id!==id);if(duplicate)return toast('This phone already has a customer profile. Open it from Follow-ups.');const data={name:f.get('name').trim(),phone:p,address:f.get('address').trim(),source:f.get('source')};if(id)Object.assign(customer(id),data);else db.customers.unshift({...data,id:uid(),agent:role==='Agent'?agentId:'',status:'Pending',permanent:false,tag:'',notes:[],callback:''});log('Customer '+data.name+' saved');closeModal();render();toast('Customer saved.')}
function assignDialog(){if(role==='Agent')return;const ids=[...selected].filter(id=>customer(id));if(!ids.length)return toast('Select customers first.');modal('Assign customers',ids.length+' customers selected. Choose one agent or distribute evenly.',`<form onsubmit="doAssign(event)"><div class="field"><label>Assignment method</label><select name="mode"><option value="one">Assign to one agent</option><option value="equal">Distribute equally</option></select></div><label>Choose agents</label>${db.agents.filter(a=>a.active&&!a.archived).map(a=>`<label class="permission"><input type="checkbox" name="agents" value="${a.id}">${esc(a.name)}</label>`).join('')}<label class="permission"><input type="checkbox" name="permanent">Assign as Permanent Clients</label><p class="muted small">Equal distribution uses only the agents selected above. Remainders go one per agent.</p>${modalFooter('Assign customers')}</form>`)}
function doAssign(e){e.preventDefault();const f=new FormData(e.target),agents=f.getAll('agents'),ids=[...selected].filter(id=>customer(id));if(!agents.length)return toast('Choose at least one agent.');if(f.get('mode')==='one'&&agents.length!==1)return toast('Choose one agent, or switch to Distribute equally.');ids.forEach((id,i)=>{const c=customer(id);c.agent=agents[i%agents.length];c.permanent=f.has('permanent');});log(ids.length+' customers assigned');selected.clear();closeModal();render();toast('Customers assigned successfully.')}
function unassignDialog(){if(role==='Agent')return;const ids=[...selected].filter(id=>customer(id));if(!ids.length)return toast('Select customers first.');modal('Return to unassigned',ids.length+' customer profiles will be available for reassignment.',`<form onsubmit="doUnassign(event)">${selectField('Reason','reason',db.settings.tags,db.settings.tags[0])}${modalFooter('Unassign')}</form>`)}
function doUnassign(e){e.preventDefault();const f=new FormData(e.target);[...selected].forEach(id=>{const c=customer(id);if(c){c.agent='';c.permanent=false;c.tag=f.get('reason')}});log('Customers unassigned: '+f.get('reason'));selected.clear();closeModal();render();toast('Moved to Unassigned.')}
function showCustomer(id){const c=customer(id);if(!c||role==='Agent'&&c.agent!==agentId)return toast('Customer not available.');modal(c.name,'Customer profile · '+c.phone,`<div class="row between"><span>${badge(c.status)} ${c.permanent?badge('Permanent'):''}</span><button onclick="customerForm('${id}')">Edit</button></div><div class="detail-kv"><div><small>Phone</small><a href="tel:${esc(c.phone)}">${ico('phone')} ${esc(c.phone)}</a></div><div><small>Assigned agent</small><strong>${esc(agentName(c.agent))}</strong></div><div><small>Address</small><strong>${esc(c.address)}</strong></div><div><small>Source</small><strong>${esc(c.source)}</strong></div></div><div class="row"><button class="primary" onclick="startOrder('${id}')">${ico('plus')} New order</button><button onclick="followupForm('${id}')">${ico('phone')} Record follow-up</button></div><h3 class="section-gap">Order history</h3>${orderTable(db.orders.filter(o=>o.customer===id),true)}<h3 class="section-gap">Notes & activity</h3><div class="timeline">${c.notes.length?c.notes.map(n=>`<div class="timeline-item">${esc(n.text)}<small>${esc(n.by)} · ${date(n.at)}</small></div>`).join(''):empty('No follow-up notes yet.')}</div>`)}
function followupForm(id){const c=customer(id);modal('Record follow-up',c.name+' · '+c.phone,`<form onsubmit="saveFollowup(event,'${id}')"><div class="form-grid">${selectField('Result','status',workflowOptions(c),c.status)}${selectField('Call status','call',['Connected','Not Connected'],c.call||'Connected')}${selectField('Customer response','response',['Positive','Intermediate','Negative'],c.response||'Intermediate')}${field('Next call (optional)','callback',c.callback||'','datetime-local')}</div><div class="field"><label>Note *</label><textarea name="note" required placeholder="What happened on this call?"></textarea></div>${modalFooter('Save follow-up')}</form>`)}
function saveFollowup(e,id){e.preventDefault();const f=new FormData(e.target),c=customer(id);if(f.get('status')===(db.settings.scheduleStatus||'Call Back')&&!f.get('callback'))return toast('Choose a date and time for the callback.');Object.assign(c,{status:f.get('status'),call:f.get('call'),response:f.get('response'),callback:f.get('callback')});c.notes.unshift({text:f.get('note'),by:role==='Agent'?agentName(agentId):role,at:new Date().toISOString()});log('Follow-up recorded for '+c.name);closeModal();render();toast('Follow-up saved.');}
function showScheduled(){if(role==='Super Admin')return toast('Store follow-ups are private to store teams.');const cs=visibleCustomers().filter(c=>c.callback).sort((a,b)=>a.callback.localeCompare(b.callback));modal('Scheduled follow-ups','Your callbacks, ordered by scheduled time.',cs.length?cs.map(c=>`<div class="setting-tags"><div><strong>${esc(c.name)}</strong><small class="muted" style="display:block;margin-top:5px">${esc(c.callback.replace('T',' '))}</small></div><button onclick="showCustomer('${c.id}')">Open</button></div>`).join(''):empty('No follow-ups are scheduled.'))}
let orderCustomerPreset='';
function startOrder(id){orderCustomerPreset=id;cart=[];editingOrder=null;closeModal();nav('new')}
function newOrderView(){const c=customer(orderCustomerPreset)||{},old=db.orders.find(o=>o.id===editingOrder);return heading(editingOrder?'Update order':'A new order. A fresh start.','Customer details, products and delivery. All in one place.',`<button onclick="nav('orders')">Back to orders</button>`)+`<form id="order-form" onsubmit="submitOrder(event,false)"><div class="split"><div><section class="card"><div class="row between"><h2>Customer details</h2><span class="badge">01</span></div><div class="form-grid section-gap">${field('Mobile number *','order-phone',c.phone||'','tel','required onblur="lookupPhone()"')}${field('Customer name *','order-name',c.name||'','text','required')}<div class="field full"><label for="order-address">Delivery address *</label><textarea id="order-address" name="order-address" required>${esc(c.address||'')}</textarea></div>${selectField('District / delivery area','order-area',['Outside Dhaka','Inside Dhaka'],'Outside Dhaka')}${selectField('Order type','order-type',['New Order','Manual Exchange','Replacement'],'New Order')}${field('Original order ID (exchange / replacement)','original-order','')}${selectField('Order source','order-source',['Phone','Website','Facebook','WhatsApp','Repeat Customer'],c.source||'Phone')}</div><div id="customer-match"></div><div class="row between"><span class="small muted">Customer delivery history</span><button type="button" class="small" onclick="historyCheck()">Check courier history ${ico('arrow')}</button></div><div id="history-result" class="section-gap"></div></section><section class="card section-gap"><div class="row between"><h2>Choose products</h2><span class="badge">02</span></div><input class="section-gap" aria-label="Search product catalog" placeholder="Search by name, SKU or variant..." oninput="filterCatalog(this.value)"><div class="catalog" id="catalog">${catalogItems('')}</div></section></div><div><section class="card"><div class="row between"><h2>Order summary</h2><span class="badge green">New order</span></div><div id="cart-items"></div><div class="form-grid section-gap">${field('Discount','order-discount',old?.discount||0,'number','min="0" step="0.01" oninput="updateTotals()"')}${field('Advance payment','order-advance',old?.advance||0,'number','min="0" step="0.01" oninput="updateTotals()"')}${field('Delivery charge','order-delivery',old?.delivery??db.settings.defaultDelivery??db.settings.outside,'number','min="0" step="0.01" oninput="updateTotals()"')}${selectField('Payment method','order-method',['COD','bKash','Nagad','Bank Transfer','Cash'],old?.method||'COD')}<div class="full">${field('Transaction ID (for advance)','order-transaction',old?.transaction||'')}</div></div><label class="permission"><input type="checkbox" id="order-verified" ${old?.verified?'checked':''}>Advance payment verified</label><div id="totals"></div></section><section class="card section-gap"><h2>Delivery details</h2><div class="form-grid section-gap">${selectField('Courier','order-courier',['Steadfast','Pathao','Other'],old?.courier||'Steadfast')}${selectField('Pickup point','order-pickup',['Main Store'],'Main Store')}</div><div class="field"><label>Shipping note</label><textarea id="order-note" placeholder="Delivery instructions...">${esc(old?.note||'')}</textarea></div><div class="notice">Bookings here are simulations. No customer data is sent to a courier. Production API connections come later.</div><div class="row"><button type="submit" class="dark" style="flex:1">Save order</button><button type="button" class="primary" style="flex:1" onclick="submitOrder(event,true)">Confirm & Book</button></div></section></div></div></form>`}
function catalogItems(q){const ps=db.products.filter(p=>p.active&&!p.archived&&[p.name,p.sku,p.variant].join(' ').toLowerCase().includes(q.toLowerCase()));return ps.length?ps.map(p=>`<button type="button" class="product-pick" onclick="addCart('${p.id}')"><img src="${esc(p.image)}" alt="${esc(p.name)}" onerror="this.style.visibility='hidden'"><div><strong>${esc(p.name)}</strong><small>${esc(p.variant)} · ${esc(p.sku)}</small><small style="color:#54862d">${money(p.price)} &nbsp; + Add</small></div></button>`).join(''):empty('No matching products.')}
function filterCatalog(v){$('#catalog').innerHTML=catalogItems(v)}
function addCart(id){const p=product(id);if(!p?.active||p.archived)return toast('This product is not available for new orders.');const found=cart.find(x=>x.product===id);if(found)found.qty++;else cart.push({product:id,qty:1,price:p.price});renderCart()}
function renderCart(){if(!$('#cart-items'))return;$('#cart-items').innerHTML=cart.length?cart.map((x,i)=>{const p=product(x.product);return `<div class="selected-item"><img src="${esc(p?.image)}" alt="${esc(p?.name)}" onerror="this.style.visibility='hidden'"><div class="item-info"><strong>${esc(p?.name||x.name)}</strong><small>${esc(p?.variant||'')}</small><div class="row"><input aria-label="Quantity ${esc(p?.name)}" type="number" min="1" max="9999" value="${x.qty}" onchange="setCartQty(${i},this.value)"><input aria-label="Unit price ${esc(p?.name)}" type="number" min="0" step="0.01" value="${x.price}" ${permitted('price')?'':'readonly'} onchange="setCartPrice(${i},this.value)"><button type="button" class="icon danger" aria-label="Remove ${esc(p?.name)}" onclick="cart.splice(${i},1);renderCart()">${ico('close')}</button></div></div></div>`}).join(''):empty('Choose products to build this order.');updateTotals()}
function setCartQty(i,v){const n=Number(v);if(!Number.isFinite(n)||n<1||!Number.isInteger(n))return toast('Quantity must be a positive whole number.');cart[i].qty=n;renderCart()}
function setCartPrice(i,v){const n=Number(v);if(!Number.isFinite(n)||n<0)return toast('Price cannot be negative.');cart[i].price=n;renderCart()}
function readOrderAmounts(){return {discount:Number($('#order-discount')?.value||0),advance:Number($('#order-advance')?.value||0),delivery:Number($('#order-delivery')?.value||0)}}
function updateTotals(){const v=readOrderAmounts(),subtotal=cart.reduce((s,x)=>s+x.qty*x.price,0),total=subtotal-v.discount+v.delivery;if($('#totals'))$('#totals').innerHTML=`<div class="totals"><div class="row"><span class="muted">Subtotal</span><strong>${money(subtotal)}</strong></div><div class="row"><span class="muted">Discount</span><span>− ${money(v.discount)}</span></div><div class="row"><span class="muted">Delivery</span><span>${money(v.delivery)}</span></div><div class="row"><span class="muted">Advance</span><span>− ${money(v.advance)}</span></div><div class="row grand"><span>Collect on delivery</span><span>${money(Math.max(0,total-v.advance))}</span></div></div>`}
function lookupPhone(){const p=normalizePhone($('#order-phone').value);$('#order-phone').value=p;const c=db.customers.find(c=>c.phone===p&&(role!=='Agent'||c.agent===agentId));if(c){$('#order-name').value=c.name;$('#order-address').value=c.address;$('#customer-match').innerHTML=`<div class="notice">Existing customer matched. ${db.orders.filter(o=>o.customer===c.id).length} previous orders will remain on this profile.</div>`}else $('#customer-match').innerHTML=''}
function historyCheck(){const p=normalizePhone($('#order-phone').value);if(!/^01[3-9]\d{8}$/.test(p))return toast('Enter a valid phone number first.');$('#history-result').innerHTML=`<div class="notice warn"><strong>Courier history: Not connected</strong><br>No verified external history available. Connect your history-check API in production. No success rate has been invented.</div>`}
async function submitOrder(e,book){e.preventDefault();const form=$('#order-form');if(!form.reportValidity())return;const phone=normalizePhone($('#order-phone').value);if(!/^01[3-9]\d{8}$/.test(phone))return toast('Enter a valid Bangladesh mobile number.');if(!cart.length)return toast('Add at least one product.');if(cart.some(x=>!product(x.product)?.active||product(x.product)?.archived))return toast('Remove inactive products before saving.');if(cart.some(x=>!Number.isFinite(x.qty)||x.qty<1||!Number.isFinite(x.price)||x.price<0))return toast('Check product quantities and prices.');const vals=readOrderAmounts();if(role==='Agent'&&db.settings.limitAgentDiscounts&&vals.discount>Number(db.settings.maxAgentDiscount||0))return toast('Discount exceeds the shop limit.');const subtotal=cart.reduce((s,x)=>s+x.qty*x.price,0);if(Object.values(vals).some(n=>!Number.isFinite(n)||n<0)||vals.discount>subtotal||vals.advance>subtotal-vals.discount+vals.delivery)return toast('Check discount, advance and delivery amounts.');if(role==='Agent'&&currentAgent().discountLimit&&vals.discount>currentAgent().discountLimit)return toast('Discount exceeds your administrator’s limit.');if(role==='Agent'&&!permitted('discount')&&vals.discount)return toast('Discount permission is disabled.');if(vals.advance&&(!$('#order-transaction').value.trim()||$('#order-method').value==='COD'))return toast('Choose the advance payment method and enter a transaction ID.');if(book&&!permitted('booking'))return toast('Courier booking permission is not enabled.');let c=db.customers.find(c=>c.phone===phone);if(c&&role==='Agent'&&c.agent&&c.agent!==agentId)return toast('This customer belongs to another agent. Ask your administrator to reassign.');const duplicate=c&&db.orders.find(o=>o.customer===c.id&&o.id!==editingOrder&&new Date(o.created)>new Date(Date.now()-7*86400000)&&o.items.some(x=>cart.some(y=>y.product===x.product)));if(duplicate&&!(await askConfirm('Possible duplicate order','A recent order with the same product exists ('+duplicate.id+'). Create another order anyway?')))return;if(!c){c={id:uid(),phone,name:$('#order-name').value.trim(),address:$('#order-address').value.trim(),agent:role==='Agent'?agentId:'',source:$('#order-source').value,status:'Pending',tag:'',permanent:false,notes:[],callback:''};db.customers.unshift(c)}else Object.assign(c,{name:$('#order-name').value.trim(),address:$('#order-address').value.trim()});if(role==='Agent'&&!c.agent)c.agent=agentId;const existing=db.orders.find(o=>o.id===editingOrder);if(role==='Agent'&&existing&&existing.agent!==agentId)return toast('This order belongs to another Agent.');const o={id:existing?.id||'JF-'+Date.now().toString().slice(-9),externalId:existing?.externalId||'',enteredBy:existing?.enteredBy||sessionAccount?.id,entryAgent:existing?.entryAgent||(role==='Agent'?agentId:''),bookedBy:book?sessionAccount?.id:existing?.bookedBy,customer:c.id,items:cart.map(x=>({...x,cost:product(x.product)?.cost??null})),...vals,method:$('#order-method').value,transaction:$('#order-transaction').value.trim(),verified:$('#order-verified').checked,courier:$('#order-courier').value,shipment:book?'Booked':'Not Booked',tracking:book?'DEMO-'+Date.now().toString().slice(-8):'',packing:'Awaiting Packing',status:book?'Confirmed':'Pending',created:existing?.created||new Date().toISOString(),agent:c.agent,source:$('#order-source').value,note:$('#order-note').value,orderType:$('#order-type')?.value||'New Order',originalOrder:$('#original-order')?.value.trim()||'',isDemo:true,events:existing?.events||[]};if(book&&o.courier==='Other')return toast('Configure an Other courier adapter before booking.');o.events.unshift({text:book?'Confirmed and booked in demo mode':'Order saved',at:new Date().toISOString(),by:role});if(existing)Object.assign(existing,o);else db.orders.unshift(o);if(book)c.status='Confirmed';log('Order '+o.id+' saved');cart=[];orderCustomerPreset='';editingOrder=null;nav('orders');toast(book?'Demo order booked. No real courier booking was sent.':'Order saved in this browser.')}
function showOrder(id){const o=db.orders.find(o=>o.id===id);if(!o||role==='Agent'&&o.agent!==agentId)return;const c=customer(o.customer);modal(o.id,'Order detail · '+date(o.created),`<div class="row between">${badge(o.status)} ${badge(o.shipment)}<button onclick="printOrder('${id}')">Print</button></div><div class="detail-kv"><div><small>Customer</small><strong>${esc(c?.name)}</strong></div><div><small>Phone</small><strong>${esc(c?.phone)}</strong></div><div><small>Address</small><strong>${esc(c?.address)}</strong></div><div><small>Agent</small><strong>${esc(agentName(o.agent))}</strong></div></div>${o.items.map(x=>`<div class="setting-tags"><span>${esc(product(x.product)?.name||x.name)} × ${x.qty}</span><strong>${money(x.qty*x.price)}</strong></div>`).join('')}<div class="totals"><div class="row"><span>Total</span><strong>${money(orderTotal(o))}</strong></div><div class="row"><span>Advance · ${esc(o.method)}</span><span>${money(o.advance)}</span></div><div class="row"><span>Collect on delivery</span><strong>${money(due(o))}</strong></div>${o.transaction?`<div class="small muted">Transaction: ${esc(o.transaction)} · ${o.verified?'Verified':'Not verified'}</div>`:''}</div><div class="notice section-gap">${esc(o.orderType||'New Order')}${o.originalOrder?' · Original: '+esc(o.originalOrder):''}<br>Courier: ${esc(o.courier)} · ${esc(o.tracking||'Not booked')}<br>${esc(o.note||'No shipping note.')}</div><div class="row">${o.shipment==='Not Booked'?`<button class="primary" onclick="bookOrder('${id}')">Confirm & Book (Demo)</button>`:''}${role!=='Agent'&&permitted('booking')?`<button onclick="shipmentForm('${id}')">Update / Cancel</button>`:''}<button onclick="showCustomer('${o.customer}')">Customer profile</button></div><h3 class="section-gap">Order timeline</h3><div class="timeline">${o.events.map(n=>`<div class="timeline-item">${esc(n.text)}<small>${esc(n.by)} · ${date(n.at)}</small></div>`).join('')}</div>`)}
function bookOrder(id){const o=db.orders.find(o=>o.id===id);if(!o||role==='Agent'&&o.agent!==agentId)return toast('This order is not assigned to you.');if(!permitted('booking'))return toast('Booking permission is disabled.');if(o.shipment!=='Not Booked')return toast('This order already has a booking.');if(o.courier==='Other')return toast('Other courier is not configured.');o.status='Confirmed';o.shipment='Booked';o.bookedBy=sessionAccount?.id;o.tracking='DEMO-'+Date.now().toString().slice(-8);customer(o.customer).status='Confirmed';o.events.unshift({text:'Demo booking created — no live API request',by:role,at:new Date().toISOString()});log('Simulated courier booking '+id);closeModal();render();toast('Demo booking created. No parcel has been booked with a real courier.')}
function bulkBook(){const ids=[...selected].filter(id=>db.orders.some(o=>o.id===id&&confirmedStatus(o.status)&&o.shipment==='Not Booked'));if(!ids.length)return toast('Select confirmed orders that are Ready to Book.');ids.forEach(id=>bookOrder(id));selected.clear();render();toast(ids.length+' demo bookings created.')}
function shipmentForm(id){if(role==='Agent'||!permitted('booking'))return toast('Only authorized Admin / Manager can change a booking.');const o=db.orders.find(o=>o.id===id);modal('Update shipment','Demo simulation only. Production updates must come from the courier.',`<form onsubmit="saveShipment(event,'${id}')">${selectField('Shipment status','shipment',['Not Booked','Booked','In Transit','Delivered','Returned','Cancelled','Partial Delivery'],o.shipment)}${field('Note / reason','reason','')}${modalFooter('Save demo update')}</form>`)}
function saveShipment(e,id){e.preventDefault();const f=new FormData(e.target),o=db.orders.find(o=>o.id===id);o.shipment=f.get('shipment');if(o.shipment==='Cancelled')o.status='Cancelled';if(o.shipment==='Returned'&&db.settings.returnPolicy==='unassigned'){const c=customer(o.customer);c.agent='';c.tag='Reassign';c.permanent=false}o.events.unshift({text:'Shipment set to '+o.shipment+' (demo). '+f.get('reason'),by:role,at:new Date().toISOString()});log('Shipment updated '+id);closeModal();render();toast('Demo shipment updated.')}
function courierView(){return heading('Delivery, connected.','Manage bookings and follow each order to its destination.',`<button onclick="nav('new')" class="dark">${ico('plus')} New booking</button>`)+`<div class="notice warn">Live courier APIs are not connected. Tracking IDs and shipment updates in this demo are simulated.</div><div class="courier-cards">${['Steadfast','Pathao','Other'].map(n=>`<div class="card"><div class="row between"><h2>${n}</h2>${ico('courier')}</div><p class="muted small">${db.orders.filter(o=>o.courier===n&&o.tracking).length} demo shipments</p><span class="badge orange">Not connected</span><button class="section-gap" style="display:block" onclick="connectionInfo('${n}')">Connection details ${ico('arrow')}</button></div>`).join('')}</div><section class="card section-gap"><h2>Shipment register</h2>${orderTable(visibleOrders().filter(o=>o.tracking))}</section>`}
function connectionInfo(n){modal(n+' integration','Production connection will be added after deployment.',`<div class="notice">Keep merchant credentials on the server. Do not paste secrets into this browser-only demo.</div><p class="small muted">${n==='Other'?'A supported courier adapter and official API documentation are required.':'Required later: merchant API access, pickup details and webhook/status access where supported.'}</p><p class="small">Booking, tracking updates and retry protection will use server endpoints after Supabase and courier integration.</p><button onclick="closeModal()">Got it</button>`)}
function printOrder(id){const o=db.orders.find(o=>o.id===id),c=customer(o.customer);modal('Invoice · '+id,'Demo invoice',`<p><strong>${esc(db.settings.storeName)}</strong><br>${esc(c.name)} · ${esc(c.phone)}<br>${esc(c.address)}</p>${o.items.map(x=>`<div class="setting-tags"><span>${esc(product(x.product)?.name||x.name)} × ${x.qty}</span><strong>${money(x.price*x.qty)}</strong></div>`).join('')}<p>Total: ${money(orderTotal(o))}<br>Advance: ${money(o.advance)}<br><strong>COD: ${money(due(o))}</strong></p><button onclick="window.print()">Print invoice</button>`)}
function productForm(id){if(role==='Agent')return;const p=product(id)||{};modal(id?'Edit product':'Add product / variant','Each variant has its own SKU, price and optional image.',`<form onsubmit="saveProduct(event,'${id||''}')"><div class="form-grid">${field('Product name *','name',p.name,'text','required')}${field('Unique SKU *','sku',p.sku,'text','required')}${field('Variant / size *','variant',p.variant,'text','required')}${field('Category','category',p.category)}${field('Sale price *','price',p.price??0,'number','required min="0" step="0.01"')}${financialAccess()?field('Cost price (optional)','cost',p.cost??'','number','min="0" step="0.01"'):''}<div class="full">${field('Image path or HTTPS URL','image',p.image||'')}</div></div><div class="field"><label>Or upload a product image (max 2 MB)</label><input type="file" accept="image/png,image/jpeg,image/webp" id="product-upload"></div><label class="permission"><input type="checkbox" name="active" ${p.active!==false?'checked':''}>Active / available for orders</label><label class="permission"><input type="checkbox" name="featured" ${p.featured?'checked':''}>Featured product</label>${modalFooter()}</form>`)}
async function saveProduct(e,id){e.preventDefault();const f=new FormData(e.target),sku=f.get('sku').trim();if(db.products.some(p=>p.sku.toLowerCase()===sku.toLowerCase()&&p.id!==id))return toast('SKU must be unique.');let image=f.get('image').trim();if(image&&!image.startsWith('assets/')&&!/^https:\/\//.test(image)&&!image.startsWith('data:image/'))return toast('Use a local assets path or an HTTPS image URL.');const file=$('#product-upload').files[0];if(file){if(file.size>2*1024*1024)return toast('Choose an image smaller than 2 MB.');image=await new Promise((resolve,reject)=>{let r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file)})}const data={updated:new Date().toISOString(),name:f.get('name').trim(),sku,variant:f.get('variant').trim(),category:f.get('category'),price:Number(f.get('price')),cost:!financialAccess()?(product(id)?.cost??null):f.get('cost')===''?null:Number(f.get('cost')),image,active:f.has('active'),featured:f.has('featured')};if(id)Object.assign(product(id),data);else db.products.push({id:uid(),...data});log('Product '+data.name+' saved');closeModal();render();toast('Product saved.')}
function csvParse(text){const rows=[];let row=[],cell='',quote=false;for(let i=0;i<text.length;i++){let c=text[i];if(c==='"'){if(quote&&text[i+1]==='"'){cell+='"';i++}else quote=!quote}else if(c===','&&!quote){row.push(cell);cell=''}else if((c==='\n'||c==='\r')&&!quote){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(x=>x.trim()))rows.push(row);row=[];cell=''}else cell+=c}row.push(cell);if(row.some(x=>x.trim()))rows.push(row);if(quote)throw Error('CSV contains an unclosed quoted field.');return rows}
function importView(){return heading('Bring your customers along.','Upload a CSV, map the columns, review and import.')+`<div class="split"><section class="card"><h2>Import customer & order data</h2><p class="muted small">Phone numbers link to one customer profile. Existing Order IDs update the matching order; new IDs add to its history.</p><div class="notice warn">Browser demo import supports up to 2,000 rows / 5 MB per file. Your 300,000–500,000 record import requires the production database and background import jobs.</div><label class="upload">${ico('upload')}<strong>Choose a CSV file</strong><span class="small muted">UTF-8 CSV · Customer name and phone required</span><input type="file" accept=".csv,text/csv" onchange="loadCSV(this.files[0])"></label><p><a class="small" href="assets/order-import-template.csv" download>Download your sample template ${ico('download')}</a></p><div id="import-preview"></div>${importResult?`<div class="notice">${esc(importResult)}</div>`:''}</section><section class="card"><h2>A cleaner customer database</h2><div class="timeline"><div class="timeline-item">Normalize Bangladesh phone numbers<small>Handles +880, missing zero and Bangla digits.</small></div><div class="timeline-item">Match customers by phone<small>One follow-up profile, all past orders.</small></div><div class="timeline-item">Match orders by Order ID<small>Update matches, preserve other orders.</small></div><div class="timeline-item">Keep imported history separate<small>Imported delivery is not a new courier booking.</small></div></div><h3>Supported data</h3><p class="small muted">Order ID, Customer Name, Phone Number, Address, SKU, Product Items, Order Total, Imported Status, Order Source, Note and previous Employee reference.</p></section></div>`}
function loadCSV(file){if(!file)return;if(file.size>5*1024*1024)return toast('Demo maximum is 5 MB.');const r=new FileReader();r.onload=()=>{try{importRows=csvParse(String(r.result).replace(/^\uFEFF/,''));if(importRows.length<2)throw Error('No data rows found.');if(importRows.length>2001)throw Error('Demo maximum is 2,000 rows.');const headers=importRows[0];const map=['Customer Name','Phone Number','Address','Order ID','Product Items','Order Total','Status','Order Source','Note','Employee'];$('#import-preview').innerHTML=`<h3 class="section-gap">Map your columns</h3><form onsubmit="runImport(event)"><div class="form-grid">${map.map(n=>`<div class="field"><label>${n}${['Customer Name','Phone Number'].includes(n)?' *':''}</label><select name="${esc(n)}"><option value="">Skip</option>${headers.map((h,i)=>`<option value="${i}" ${h.trim().toLowerCase()===n.toLowerCase()?'selected':''}>${esc(h)}</option>`).join('')}</select></div>`).join('')}</div><div class="notice">${importRows.length-1} rows loaded. Phone and Order ID matches are updated. Assignment is preserved.</div><button class="primary" type="submit">Import ${importRows.length-1} rows</button></form>`}catch(err){toast(err.message)}};r.readAsText(file)}
function runImport(e){e.preventDefault();const f=new FormData(e.target),col=n=>f.get(n),get=(r,n)=>col(n)===''?'':String(r[Number(col(n))]||'').trim();if(col('Customer Name')===''||col('Phone Number')==='')return toast('Map Customer Name and Phone Number.');let added=0,updated=0,orders=0,skipped=0;for(const r of importRows.slice(1)){const phone=normalizePhone(get(r,'Phone Number')),name=get(r,'Customer Name');if(!/^01[3-9]\d{8}$/.test(phone)||!name){skipped++;continue}const externalId=get(r,'Order ID');let existing=externalId?db.orders.find(o=>o.externalId===externalId):null;let c=db.customers.find(c=>c.phone===phone);if(existing&&c&&existing.customer!==c.id){skipped++;continue}if(!c){c={id:uid(),phone,name,address:get(r,'Address'),source:get(r,'Order Source')||'CSV Import',agent:'',status:'Pending',tag:'',permanent:false,callback:'',notes:[]};db.customers.push(c);added++}else{c.name=name;if(get(r,'Address'))c.address=get(r,'Address');updated++}if(existing&&existing.customer!==c.id){skipped++;continue}if(externalId){let imported={externalId,customer:c.id,importedItems:get(r,'Product Items'),importedStatus:get(r,'Status'),previousEmployee:get(r,'Employee'),source:get(r,'Order Source')||'CSV Import',importedTotal:Number(get(r,'Order Total').replace(/,/g,''))||0};if(existing)Object.assign(existing,imported);else{db.orders.push({id:'IMP-'+uid().slice(0,8),...imported,items:[],discount:0,advance:0,delivery:0,status:'Imported',shipment:'Imported History',courier:'',tracking:'',packing:'Not applicable',agent:c.agent,created:new Date().toISOString(),note:get(r,'Note'),events:[{text:'Historical order imported',by:role,at:new Date().toISOString()}],isDemo:true});orders++}}}importResult=`${added} customer profiles added · ${updated} matched profiles updated · ${orders} historical orders added · ${skipped} invalid/conflicting rows skipped.`;log('CSV import completed: '+importResult);render();toast('Import complete. Historical rows are not treated as new sales.')}
function exportOrders(){const rows=[['Order ID','Customer Name','Phone','Products','Total','Advance','COD','Status','Shipment','Courier','Tracking','Agent'],...visibleOrders().map(o=>{const c=customer(o.customer);return[o.id,c?.name,c?.phone,o.items.map(x=>(product(x.product)?.name||x.name)+' x '+x.qty).join('; '),o.status==='Imported'?o.importedTotal:orderTotal(o),o.advance,due(o),o.status,o.shipment,o.courier,o.tracking,agentName(o.agent)]})];download('jioflow-orders.csv','\uFEFF'+rows.map(r=>r.map(x=>'"'+String(x??'').replace(/^[=+@-]/,"'$&").replace(/"/g,'""')+'"').join(',')).join('\r\n'),'text/csv')}
function download(name,data,type){const url=URL.createObjectURL(new Blob([data],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function reportsView(){if(role==='Agent'||role==='Manager'&&!permitted('profit'))return heading('Reports','Access to financial reports is restricted.');const os=visibleOrders().filter(inRange).filter(o=>o.status==='Confirmed'),revenue=os.reduce((s,o)=>s+orderTotal(o),0),discount=os.reduce((s,o)=>s+o.discount,0),missing=os.some(o=>o.items.some(x=>(x.cost??product(x.product)?.cost)==null)),cost=os.reduce((s,o)=>s+o.items.reduce((a,x)=>a+(x.cost??product(x.product)?.cost??0)*x.qty,0)+o.delivery,0);return heading('Numbers with meaning.','Understand your team, sales and delivery outcomes.',rangeSelect()+`<button onclick="exportOrders()">${ico('download')} Export orders</button>`)+`<div class="stats">${stat('Confirmed revenue',money(revenue),'reports','Order value, not settled cash','featured')}${stat('Discount given',money(discount),'orders','Included in order totals')}${stat('Estimated profit',missing?'Cost missing':money(revenue-cost),'reports',missing?'Enter all product costs first':'Revenue less product and delivery cost')}${stat('Delivery success',os.length?Math.round(os.filter(o=>o.shipment==='Delivered').length/os.length*100)+'%':'0%','courier','Delivered / confirmed orders')}</div><div class="notice">Profit is unavailable while any item cost is missing. Real COD fees, packaging, return costs and courier settlement require production financial integration.</div><section class="card"><h2>Agent performance</h2><p class="small muted">Calls and sales are separate from delivery outcomes.</p><div class="table-wrap"><table><thead><tr><th>Agent</th><th>Assigned</th><th>Attempted</th><th>Connected</th><th>Confirmed</th><th>Delivered</th><th>Returned</th><th>Revenue</th><th></th></tr></thead><tbody>${db.agents.map(a=>{const cs=db.customers.filter(c=>c.agent===a.id),as=os.filter(o=>o.agent===a.id);return `<tr><td><strong>${esc(a.name)}</strong></td><td>${cs.length}</td><td>${cs.filter(c=>c.call).length}</td><td>${cs.filter(c=>c.call==='Connected').length}</td><td>${as.length}</td><td>${as.filter(o=>o.shipment==='Delivered').length}</td><td>${as.filter(o=>o.shipment==='Returned').length}</td><td>${money(as.reduce((s,o)=>s+orderTotal(o),0))}</td><td><button class="icon" aria-label="Report for ${esc(a.name)}" onclick="agentReport('${a.id}')">${ico('arrow')}</button></td></tr>`}).join('')}</tbody></table></div></section><div class="settings-grid section-gap"><section class="card"><h2>Products sold</h2>${db.products.map(p=>{let qty=os.reduce((s,o)=>s+o.items.filter(x=>x.product===p.id).reduce((n,x)=>n+x.qty,0),0);return qty?`<div class="setting-tags"><span>${esc(p.name)}</span><strong>${qty} units</strong></div>`:''}).join('')||empty('No confirmed products.')}</section><section class="card"><h2>Source performance</h2>${[...new Set(os.map(o=>o.source))].map(source=>`<div class="setting-tags"><span>${esc(source)}</span><strong>${money(os.filter(o=>o.source===source).reduce((s,o)=>s+orderTotal(o),0))}</strong></div>`).join('')||empty('No sales in this period.')}</section></div>`}
function agentReport(id){const a=agent(id),cs=db.customers.filter(c=>c.agent===id),os=db.orders.filter(o=>o.agent===id&&inRange(o));modal(a.name+' · Performance','Selected reporting period',`<div class="report-metrics">${[['Assigned',cs.length],['Attempted',cs.filter(c=>c.call).length],['Confirmed',os.filter(o=>o.status==='Confirmed').length],['Due / overdue',cs.filter(c=>c.callback&&new Date(c.callback)<=new Date()).length],['Positive',cs.filter(c=>c.response==='Positive').length],['Delivered',os.filter(o=>o.shipment==='Delivered').length]].map(([k,v])=>`<div class="report-metric"><small>${k}</small><strong>${v}</strong></div>`).join('')}</div><h3 class="section-gap">Recent orders</h3>${orderTable(os.slice(0,5),true)}`)}
function toggleAgent(id){const a=agent(id);if(role==='Manager'&&a.role==='Manager')return toast('Only Admin can change Manager accounts.');a.active=!a.active;if(!a.active)(db.sessions||[]).filter(s=>s.user===a.id&&['Approved','Pending'].includes(s.status)).forEach(s=>s.status='Revoked');log('Agent '+a.name+' '+(a.active?'activated':'deactivated'));render();toast('Account state changed. Existing assignments are preserved for Admin reassignment.')}
function settingsView(){if(role==='Super Admin')return heading('Platform settings','Aggregate demo platform. Store permissions are configured by the Admin.')+'<section class="card"><h2>JioFlow platform</h2><p>One demonstration store. No customer details or store activity logs are shown here.</p></section>';return heading('Make it your workspace.','Configure delivery charges, team access and follow-up options.')+`<div class="settings-grid"><section class="card"><h2>Workspace settings</h2><form onsubmit="saveSettings(event)"><div class="form-grid">${field('Store name','storeName',db.settings.storeName,'text','required')}${field('Inside Dhaka charge (sample default)','inside',db.settings.inside,'number','min="0" required')}${field('Outside Dhaka charge (sample default)','outside',db.settings.outside,'number','min="0" required')}${selectField('Return follow-up assignment','returnPolicy',['same','unassigned'],db.settings.returnPolicy)}</div><button class="primary section-gap">Save settings</button></form></section><section class="card"><h2>Custom follow-up statuses</h2><p class="small muted">Add options as your workflow grows.</p>${db.settings.statuses.map(x=>`<div class="setting-tags">${badge(x)}</div>`).join('')}<button onclick="addOption('statuses')">${ico('plus')} Add status</button><h2 class="section-gap">Unassignment tags</h2>${db.settings.tags.map(x=>`<span class="badge">${esc(x)}</span>`).join(' ')}<p><button onclick="addOption('tags')">${ico('plus')} Add tag</button></p></section><section class="card"><h2>Demo data</h2><p>Export a backup before resetting this browser's demo.</p><button onclick="download('jioflow-backup.json',JSON.stringify(db,null,2),'application/json')">Download backup</button><button class="ghost" onclick="resetDemo()">Reset demo</button><p class="small muted">No production subscription limits. Browser demo imports are intentionally small; large imports need a server and database.</p></section><section class="card"><h2>Recent activity</h2>${db.activity.slice(0,12).map(x=>`<div class="setting-tags"><div>${esc(x.text)}<br><small class="muted">${esc(x.by)} · ${date(x.at)}</small></div></div>`).join('')||empty('Your activity will appear here.')}</section></div>`}
function saveSettings(e){e.preventDefault();const f=new FormData(e.target);Object.assign(db.settings,{storeName:f.get('storeName').trim(),inside:Number(f.get('inside')),outside:Number(f.get('outside')),returnPolicy:f.get('returnPolicy'),managerPermissions:Object.fromEntries(f.getAll('perm').map(x=>[x,true]))});db.agents.filter(a=>a.role==='Manager').forEach(a=>Object.assign(a.permissions,db.settings.managerPermissions));log('Workspace settings updated');render();toast('Settings saved.')}
function addOption(type){modal(type==='tags'?'Add unassignment tag':'Add follow-up status','Your new option will appear in the relevant forms.',`<form onsubmit="event.preventDefault();saveOption('${type}',this.elements.label.value)">${field('Option name','label','','text','required maxlength="60"')}${modalFooter('Add option')}</form>`)}
function saveOption(type,value){value=value.trim();if(!value)return;if(db.settings[type].some(x=>x.toLowerCase()===value.toLowerCase()))return toast('This option already exists.');db.settings[type].push(value);log('Added '+type+': '+value);closeModal();render()}
async function resetDemo(){if(!(await askConfirm('Reset demo data','Reset all changes in this browser and restore sample data?')))return;db=seed();agentId=db.agents[0].id;save();nav('dashboard');toast('Sample demo restored.')}
function superView(){return heading('A clear view of your platform.','Aggregate store activity. Customer records are hidden in this view.')+`<div class="stats">${stat('Stores',db.stores.length,'stores','Demo workspaces','featured')}${stat('Active stores',db.stores.filter(s=>s.active).length,'check','Current store status')}${stat('Agents',db.agents.length,'customers','Aggregate count')}${stat('Orders',db.orders.length,'orders','Aggregate count')}</div>${storesView(true)}`}
function storesView(embedded=false){return(embedded?'':heading('Stores','Platform overview with aggregate metrics only.'))+`<section class="card"><h2>Workspace directory</h2><div class="table-wrap"><table><thead><tr><th>Store</th><th>Status</th><th>Agents</th><th>Orders</th></tr></thead><tbody>${db.stores.map(s=>`<tr><td><strong>${esc(s.name)}</strong></td><td>${badge(s.active?'Active':'Inactive')}</td><td>${db.agents.length}</td><td>${db.orders.length}</td></tr>`).join('')}</tbody></table></div><p class="small muted">This demo contains one store. Production tenant isolation requires database access policies.</p></section>`}
function profileView(){const a=currentAgent();return heading('Your profile','Demo identity and account details.')+`<section class="card"><h2>${esc(a.name)}</h2><form onsubmit="event.preventDefault();currentAgent().name=this.elements.fullName.value.trim();log('Profile updated');render();toast('Profile saved')">${field('Full name','fullName',a.name,'text','required')}<p>${esc(a.email)}</p><button class="primary">Save profile</button></form><div class="notice section-gap">Password changes and secure login become available with production authentication.</div></section>`}
function showGuide(){modal('Welcome to JioFlow','A working CRM demo for your team.',`<p>Start with Follow-ups, assign customers to agents, record calls and schedule callbacks. Create an order with one or several products, then confirm and simulate courier booking.</p><p>Use Switch account to enter each separate demo identity. Owner can configure individual user permissions in Users.</p><p>Products can be added manually. CSV Import updates matched order IDs and keeps one customer profile per phone.</p><div class="notice">All customer names, phone numbers and courier tracking codes in the initial demo are samples. This is browser-local software: account access is a preview, not secure authentication. Courier requests are simulated.</div><p>Production requires Supabase authentication, database policies, server-side courier APIs and background import jobs.</p><div class="modal-footer"><button class="primary" onclick="closeModal()">Let's explore</button></div>`)}
// Dashboard and management views: feature parity with supplied reference screens.
let dashboardStatus='',productStatus='All',productCategory='',productFeatured='All',userStatus='All',productSort='name',productRows=10,userRows=10;
const lifecycleStatuses=['Processing','No Response','Not Interested','Problem Solve','Confirm','Refuse','Busy','Interested','Irregular','Don’t Call Again','Order Recently','For Relative','Schedule','FL - 1 Month Later','FL - 2 Month Later','FL - 3 Month Later'];
for(const s of lifecycleStatuses)if(!db.settings.statuses.includes(s))db.settings.statuses.push(s);
const confirmedStatus=s=>['Confirmed','Confirm',db.settings.confirmStatus].filter(Boolean).includes(s);
const pendingStatus=s=>['Pending','Processing'].includes(s);
const financialAccess=()=>typeof accessPolicy==='function'?(role!=='Agent'&&accessPolicy('profit')):role==='Admin'||role==='Manager'&&permitted('profit');
const liveOrders=()=>visibleOrders().filter(o=>o.status!=='Imported');
const ratio=(n,d)=>d?(n/d*100).toFixed(1)+'%':'0%';
let rangeOffset=0,customStart='',customEnd='',rowsPerPage=10;
function rangeBounds(){const shift=6*3600000,day=86400000,today=Math.floor((Date.now()+shift)/day)*day-shift;let start,end;if(range==='all')return {start:-Infinity,end:Infinity};if(range==='custom'){start=customStart?new Date(customStart+'T00:00:00+06:00').getTime():today;end=customEnd?new Date(customEnd+'T00:00:00+06:00').getTime()+day:today+day}else{const days=Number(range)||30;end=today+day;start=end-days*day}const span=end-start;return {start:start+rangeOffset*span,end:end+rangeOffset*span}}
function changeRange(value){range=value;rangeOffset=0;render()}
function shiftRange(direction){if(range==='all')return;rangeOffset+=direction;render()}
function rangeControls(){return `<span class="bd-clock">${new Date().toLocaleTimeString('en-BD',{hour:'numeric',minute:'2-digit',hour12:true,timeZone:'Asia/Dhaka'})} <small>BD</small></span><button class="icon" aria-label="Previous reporting period" ${range==='all'?'disabled':''} onclick="shiftRange(-1)">‹</button><select aria-label="Report date range" style="width:140px" onchange="changeRange(this.value)">${[['1','Today'],['7','Last 7 days'],['30','Last 30 days'],['custom','Custom dates'],['all','Lifetime']].map(([v,n])=>`<option value="${v}" ${range===v?'selected':''}>${n}</option>`).join('')}</select><button class="icon" aria-label="Next reporting period" ${range==='all'||rangeOffset>=0?'disabled':''} onclick="shiftRange(1)">›</button>${range==='custom'?`<input type="date" aria-label="Report start date" value="${esc(customStart)}" onchange="setCustomRange('start',this.value)"><input type="date" aria-label="Report end date" value="${esc(customEnd)}" onchange="setCustomRange('end',this.value)">`:''}${rangeOffset?`<small class="muted">${date(new Date(rangeBounds().start))} – ${date(new Date(rangeBounds().end-1))}</small>`:''}`}
function setCustomRange(key,value){const start=key==='start'?value:customStart,end=key==='end'?value:customEnd;if(start&&end&&end<start)return toast('End date must be on or after start date.');customStart=start;customEnd=end;rangeOffset=0;render()}

function metricSet(os,cs){const confirmed=os.filter(o=>confirmedStatus(o.status));const attempted=cs.filter(c=>c.call);return {total:os.length,confirmed:confirmed.length,revenue:confirmed.reduce((s,o)=>s+orderTotal(o),0),purchase:attempted.length?new Set(confirmed.map(o=>o.customer)).size/attempted.length*100:0,assigned:cs.filter(c=>c.agent).length,pending:cs.filter(c=>c.agent&&pendingStatus(c.status)).length,completed:cs.filter(c=>c.call&&!pendingStatus(c.status)).length,notConnected:cs.filter(c=>c.call==='Not Connected').length,connected:cs.filter(c=>c.call==='Connected').length,positive:cs.filter(c=>c.response==='Positive').length,intermediate:cs.filter(c=>c.response==='Intermediate').length,negative:cs.filter(c=>c.response==='Negative').length,attempted:attempted.length}}
function orderProfit(o){if(o.items.some(x=>(x.cost??product(x.product)?.cost)==null))return null;const f=o.finance||{};return orderTotal(o)-o.items.reduce((s,x)=>s+x.qty*(x.cost??product(x.product)?.cost),0)-Number(f.courierCost??o.delivery)-Number(f.codFee||0)-Number(f.packaging||0)-Number(f.returnFee||0)-Number(f.otherCost||0)}
function metricCard(label,value,foot,action='',cls=''){return `<button class="card metric-tile ${cls}" ${action?`onclick="${action}"`:''}><span class="label">${label}</span><strong>${value}</strong><small>${foot}</small>${action?'<span class="metric-arrow">↗</span>':''}</button>`}
function dashboardCustomers(status='',call='',response=''){nav('customers');dashboardStatus=status;window.callFilter=call;window.responseFilter=response;subtab=status||'All';render()}
function dashboardOrders(status){nav('orders');subtab=status||'All';render()}
function dashboardView(){if(role==='Super Admin')return superView();const os=visibleOrders().filter(inRange),cs=visibleCustomers(),m=metricSet(os,cs),confirmed=os.filter(o=>confirmedStatus(o.status)),canFinance=financialAccess(),profits=confirmed.map(orderProfit),profit=profits.some(x=>x===null)?null:profits.reduce((s,x)=>s+x,0),sources=[...new Set(cs.filter(c=>c.agent).map(c=>c.source||'Other'))],statuses=[...new Set([...db.settings.statuses,...cs.map(c=>c.status)])],top=db.products.map(p=>({p,qty:confirmed.reduce((s,o)=>s+o.items.filter(x=>x.product===p.id).reduce((s,x)=>s+x.qty,0),0)})).filter(x=>x.qty).sort((a,b)=>b.qty-a.qty).slice(0,5),previous=range==='all'?null:visibleOrders().filter(o=>{const r=rangeBounds(),t=new Date(o.created).getTime();return t>=r.start-(r.end-r.start)&&t<r.start}),prev=previous?.filter(o=>confirmedStatus(o.status));const compare=(value,key)=>{if(!prev)return 'All available history';const old=key==='count'?prev.length:prev.reduce((s,o)=>s+orderTotal(o),0);return old?`${value>=old?'↑':'↓'} ${Math.abs((value-old)/old*100).toFixed(1)}% · previous ${key==='count'?old:money(old)}`:'Previous period: 0 · no percentage baseline'};return heading(role==='Agent'?'Your day, in flow.':'Every number. A clearer next step.',`Orders follow the selected period. Customer queue and response totals show the current snapshot.`,rangeSelect()+`<button class="dark" onclick="cart=[];nav('new')">${ico('plus')} New Order</button>`)+`<div class="dashboard-panels"><section class="card"><h2>Order Funnel</h2><p class="small muted">Current customer workflow</p><button class="breakdown" onclick="dashboardOrders('All')"><span>Total Orders</span><strong>${os.length}</strong><small>Selected reporting period</small></button>${[['Total customer profiles',cs.length,'All'],['Assigned',m.assigned,'Assigned'],['Attempted',m.attempted,'attempted'],['Confirmed customers',cs.filter(c=>confirmedStatus(c.status)).length,'Confirmed'],['Failed / no sale',cs.filter(c=>c.call&&!confirmedStatus(c.status)&&!pendingStatus(c.status)).length,'failed'],['Not attempted',cs.filter(c=>!c.call).length,'notattempted']].map(([label,n,key])=>`<button class="breakdown" onclick="openFunnel('${key}')"><span>${label}</span><strong>${n}</strong><div class="meter"><i style="width:${cs.length?n/cs.length*100:0}%"></i></div><small>${ratio(n,cs.length)} of profiles</small></button>`).join('')}</section><section class="card"><h2>Assigned Order Source</h2><p class="small muted">Current assignments by source</p><div class="mini-ring"><strong>${m.assigned}</strong><span>assigned customers</span></div>${sources.map((s,i)=>{const n=cs.filter(c=>c.agent&&c.source===s).length;return `<button class="breakdown" onclick="sourceQueue(${i})"><span>${esc(s)}</span><strong>${n} · ${ratio(n,m.assigned)}</strong><div class="meter"><i style="width:${m.assigned?n/m.assigned*100:0}%"></i></div></button>`}).join('')||empty('No assignments yet.')}</section><section class="card"><h2>Top Products</h2><p class="small muted">Units in confirmed orders · selected period</p>${top.map(({p,qty})=>`<button class="top-product" onclick="ordersForProduct('${p.id}')"><img src="${esc(p.image)}" alt=""><span><strong>${esc(p.name)}</strong><small>${esc(p.variant)}</small><div class="meter"><i style="width:${qty/top[0].qty*100}%"></i></div></span><b>${qty}</b></button>`).join('')||empty('No confirmed products in this period.')}</section><section class="card"><h2>Status Breakdown</h2><p class="small muted">Current follow-up statuses</p><div class="status-scroll">${statuses.map((s,i)=>{const n=cs.filter(c=>c.status===s).length;return `<button class="status-row" onclick="openStatus(${i})"><i class="status-dot" style="background:hsl(${i*37%360} 45% 55%)"></i><span>${esc(s)}</span><div class="meter"><i style="width:${cs.length?n/cs.length*100:0}%"></i></div><strong>${n}</strong></button>`}).join('')}</div></section></div><div class="stats dashboard-metrics">${metricCard('Confirmed Orders',m.confirmed,compare(m.confirmed,'count'),"dashboardOrders('Confirmed')",'featured')}${metricCard('Revenue',money(m.revenue),compare(m.revenue,'revenue'),"dashboardOrders('Confirmed')")}${canFinance?metricCard('Profit',profit===null?'Cost missing':money(profit),'Estimate after recorded costs and fees',"nav('profit')"):metricCard('Delivered',os.filter(o=>o.shipment==='Delivered').length,'Completed courier deliveries',"dashboardOrders('Delivered')")}${metricCard('Purchase Rate',ratio(new Set(confirmed.map(o=>o.customer)).size,cs.length),'Purchasing profiles in period / current profiles',"dashboardOrders('Confirmed')")}${[['Assigned',m.assigned,'Current assigned customer profiles',"dashboardCustomers('Assigned')"],['Pending Follow-up',m.pending,'Assigned profiles awaiting follow-up',"dashboardCustomers('pendingqueue')"],['Completed',m.completed,'Attempted profiles with a recorded result',"dashboardCustomers('completed')"],['Not Connected',m.notConnected,'Current call outcome',"dashboardCustomers('','Not Connected')"],['Connected',m.connected,'Current call outcome',"dashboardCustomers('','Connected')"],['Positive',m.positive,'Current customer response',"dashboardCustomers('','','Positive')"],['Intermediate',m.intermediate,'Current customer response',"dashboardCustomers('','','Intermediate')"],['Negative',m.negative,'Current customer response',"dashboardCustomers('','','Negative')"]].map(([l,n,f,a])=>metricCard(l,n,f,a)).join('')}</div>${confirmedChart(os)}<div class="dashboard-grid section-gap"><section class="card"><h2>Courier Delivery Overview</h2>${['Not Booked','Booked','In Transit','Delivered','Returned','Partial Delivery','Cancelled'].map(s=>`<button class="status-row" onclick="dashboardOrders('${s}')"><span>${s}</span><strong>${os.filter(o=>o.shipment===s).length}</strong></button>`).join('')}</section><section class="card"><div class="row between"><h2>Recent Orders</h2><button onclick="nav('orders')">View all</button></div>${orderTable(os.slice(0,5),true)}</section></div>`}
function ordersForProduct(id){const sku=product(id)?.sku||'';nav('orders');query=sku;render()}
function openStatus(i){const statuses=[...new Set([...db.settings.statuses,...visibleCustomers().map(c=>c.status)])];dashboardCustomers(statuses[i])}
function openFunnel(key){nav('customers');window.funnelFilter=['attempted','failed','notattempted'].includes(key)?key:'';subtab=['All','Assigned','Confirmed'].includes(key)?key:'All';render()}
function sourceQueue(i){const sources=[...new Set(visibleCustomers().filter(c=>c.agent).map(c=>c.source||'Other'))];const source=sources[i];nav('customers');window.customerSource=source;subtab='Assigned';render()}
function confirmedChart(os){const hourly=range==='1',count=hourly?24:range==='7'?7:30,buckets=Array.from({length:count},(_,i)=>{const d=new Date((Number.isFinite(rangeBounds().end)?Math.min(Date.now(),rangeBounds().end-1):Date.now())-(count-1-i)*(hourly?3600000:86400000));return {label:hourly?d.toLocaleTimeString('en-BD',{hour:'numeric',hour12:true,timeZone:'Asia/Dhaka'}):d.toLocaleDateString('en-GB',{day:'numeric',month:'short',timeZone:'Asia/Dhaka'}),n:os.filter(o=>confirmedStatus(o.status)&&Math.floor((new Date(o.created).getTime()+6*3600000)/(hourly?3600000:86400000))===Math.floor((d.getTime()+6*3600000)/(hourly?3600000:86400000))).length}}),max=Math.max(1,...buckets.map(x=>x.n));return `<section class="card section-gap"><div class="row between"><h2>Confirmed Orders</h2><span class="badge green">${os.filter(o=>confirmedStatus(o.status)).length} in selected period</span></div><p class="small muted">${hourly?'Hourly · Bangladesh time':'Daily · most recent '+count+' days shown'}</p><div class="chart-scroll"><div class="chart detailed-chart">${buckets.map(x=>`<div class="bar-wrap"><div class="bar highlight" title="${esc(x.label)}: ${x.n} confirmed" style="height:${Math.max(3,x.n/max*94)}%"></div><span class="bar-label">${esc(x.label)}</span></div>`).join('')}</div></div></section>`}
function teamView(){const users=db.agents.filter(a=>!a.archived&&a.role!=='Admin'&&(!query||[a.name,a.email,a.phone,a.code,a.role].join(' ').toLowerCase().includes(query.toLowerCase()))&&(userStatus==='All'||(userStatus==='Active')===a.active));return heading('Users','Manage people, permissions and work allocation.',`<button class="dark" onclick="agentForm()">${ico('plus')} Add user</button>`)+`<div class="notice">Create login accounts here. Staff use their email and password directly; no separate signup is needed.</div><div class="toolbar"><span class="badge green">${db.agents.filter(a=>!a.archived).length} users · no plan limit</span><div class="row"><input aria-label="Search users" placeholder="Search name, email, phone or code..." value="${esc(query)}" onchange="query=this.value;pageNo=1;render()"><select aria-label="User status filter" onchange="userStatus=this.value;pageNo=1;render()">${options(['All','Active','Inactive'],userStatus)}</select></div></div><div class="compact-users">${users.slice((pageNo-1)*rowsPerPage,pageNo*rowsPerPage).map(a=>`<article class="card compact-user"><div class="row between"><div class="row nowrap"><span class="avatar">${initials(a.name)}</span><div><h3>${esc(a.name)}</h3><span class="small muted">${esc(a.role||'Agent')} ${a.code?'· '+esc(a.code):''}</span></div></div>${badge(a.active?'Active':'Inactive')}</div><div class="user-contact"><span>${esc(a.email)}</span>${a.phone?`<span>${esc(a.phone)}</span>`:''}</div><div class="compact-user-stats"><span><b>${db.customers.filter(c=>c.agent===a.id).length}</b> assigned</span><span><b>${db.customers.filter(c=>c.agent===a.id&&c.permanent).length}</b> permanent</span><span>Self-pull <b>${a.permissions.pull?'On':'Off'}</b></span></div><div class="small muted">${a.pullCount} per pull · ${a.dailyLimit?a.dailyLimit+'/day':'Unlimited daily'}</div><div class="user-actions"><button onclick="agentForm('${a.id}')">${ico('edit')} Edit & permissions</button><button onclick="toggleAgent('${a.id}')">${a.active?'Deactivate':'Activate'}</button><button class="icon danger" aria-label="Archive ${esc(a.name)}" title="Archive user" onclick="archiveUser('${a.id}')">${ico('logout')}</button></div></article>`).join('')||empty('No users match your filters.')}</div>${pagination(users.length)}`}

async function archiveUser(id){const a=agent(id);if(role==='Manager'&&a.role==='Manager')return toast('Only Admin can archive a Manager.');if(db.customers.some(c=>c.agent===id))return toast('Unassign or reassign all customers, including Permanent Clients, before archiving this user.');if(!(await askConfirm('Archive user','Archive '+a.name+'? Historical order attribution will stay intact.')))return;a.archived=true;a.active=false;log('User archived: '+a.name);render()}
function productsView(){const ps=filteredProducts(),categories=[...new Set(db.products.map(p=>p.category).filter(Boolean))];return heading('Products','Manage your catalog, availability, featured products and variants.',`<button onclick="productCSVDialog()">${ico('upload')} Upload CSV</button><button class="dark" onclick="productForm()">${ico('plus')} Add product</button>`)+`<section class="card"><div class="toolbar"><div class="row"><input aria-label="Search products" placeholder="Search product, variant or SKU" value="${esc(query)}" onchange="query=this.value;pageNo=1;render()"><button onclick="filters=!filters;render()">${ico('filter')} Filters</button></div><span class="small muted">${ps.length} products</span></div>${filters?`<div class="filter-panel"><div><label>Availability</label><select aria-label="Product availability" onchange="productStatus=this.value;pageNo=1;render()">${options(['All','Active','Inactive','Archived'],productStatus)}</select></div><div><label>Category</label><select aria-label="Product category" onchange="productCategory=this.value;pageNo=1;render()"><option value="">All categories</option>${options(categories,productCategory)}</select></div><div><label>Featured</label><select aria-label="Featured filter" onchange="productFeatured=this.value;pageNo=1;render()">${options(['All','Featured','Not featured'],productFeatured)}</select></div><div><label>Sort</label><select aria-label="Product sort" onchange="productSort=this.value;render()">${options(['name','price-low','price-high'],productSort)}</select></div><button onclick="productStatus='All';productCategory='';productFeatured='All';query='';pageNo=1;render()">Clear filters</button></div>`:''}<div class="toolbar"><span id="selection-count" class="small muted">${selected.size} selected</span><div class="row"><button onclick="bulkProduct(true)">Activate selected</button><button onclick="bulkProduct(false)">Deactivate selected</button><button onclick="exportProducts()">Export CSV</button></div></div><div class="table-wrap"><table><thead><tr><th><input type="checkbox" aria-label="Select displayed products" onchange="selectProductPage(this.checked)"></th><th>Product</th><th>SKU</th><th>Cost price</th><th>Price</th><th>Updated</th><th>Active</th><th>Featured</th><th>Actions</th></tr></thead><tbody>${ps.slice((pageNo-1)*rowsPerPage,pageNo*rowsPerPage).map(p=>`<tr><td><input type="checkbox" aria-label="Select product ${esc(p.name)}" ${selected.has(p.id)?'checked':''} onchange="toggleSelected('${p.id}',this.checked)"></td><td><div class="row nowrap"><img class="table-product-img" src="${esc(p.image)}" alt=""><div><strong>${esc(p.name)}</strong><small>${esc(p.variant)} · ${esc(p.category)}</small></div></div></td><td>${esc(p.sku)}</td><td>${p.cost==null?'<span class="muted">Not set</span>':money(p.cost)}</td><td><strong>${money(p.price)}</strong></td><td>${p.updated?date(p.updated):'Initial catalog'}</td><td><button class="switch ${p.active?'on':''}" role="switch" aria-checked="${!!p.active}" aria-label="Active ${esc(p.name)}" ${p.archived?'disabled':''} onclick="toggleProduct('${p.id}','active')"><span></span></button></td><td><button class="switch ${p.featured?'on':''}" role="switch" aria-checked="${!!p.featured}" aria-label="Featured ${esc(p.name)}" onclick="toggleProduct('${p.id}','featured')"><span></span></button></td><td><div class="row nowrap"><button class="icon" aria-label="Edit ${esc(p.name)}" onclick="productForm('${p.id}')">${ico('edit')}</button><button class="ghost" onclick="archiveProduct('${p.id}')">${p.archived?'Restore':'Archive'}</button></div></td></tr>`).join('')||'<tr><td colspan="9">No matching products.</td></tr>'}</tbody></table></div>${pagination(ps.length)}</section><div class="notice section-gap">Inactive and archived products stay in historical orders but cannot be added to new orders. Cost prices remain blank until provided. Each variant uses a separate SKU; stock tracking is disabled.</div>`}
function filteredProducts(){return db.products.filter(p=>(productStatus==='Archived'?p.archived:!p.archived)&&(productStatus==='All'||productStatus==='Archived'||(productStatus==='Active')===p.active)&&(!productCategory||p.category===productCategory)&&(productFeatured==='All'||(productFeatured==='Featured')===p.featured)&&(!query||[p.name,p.sku,p.variant].join(' ').toLowerCase().includes(query.toLowerCase()))).sort((a,b)=>productSort==='price-low'?a.price-b.price:productSort==='price-high'?b.price-a.price:a.name.localeCompare(b.name))}
function toggleProduct(id,key){const p=product(id);p[key]=!p[key];p.updated=new Date().toISOString();log('Product '+key+' changed: '+p.name);render();toast(key==='active'?(p.active?'Product activated.':'Product deactivated. Historical orders are preserved.'):'Featured setting saved.')}
function selectProductPage(on){filteredProducts().slice((pageNo-1)*rowsPerPage,pageNo*rowsPerPage).forEach(p=>on?selected.add(p.id):selected.delete(p.id));render()}
function bulkProduct(on){const ps=db.products.filter(p=>selected.has(p.id)&&!p.archived);if(!ps.length)return toast('Select products first.');ps.forEach(p=>{p.active=on;p.updated=new Date().toISOString()});log(ps.length+' products '+(on?'activated':'deactivated'));selected.clear();render()}
function archiveProduct(id){const p=product(id);p.archived=!p.archived;p.active=false;p.updated=new Date().toISOString();log((p.archived?'Archived ':'Restored ')+p.name);render();toast(p.archived?'Product archived. History is preserved.':'Product restored as inactive. Activate it when ready.')}
function csvSafe(v){return '"'+String(v??'').replace(/^[=+@-]/,"'$&").replace(/"/g,'""')+'"'}
function exportProducts(){const rows=[['name','sku','variant','category','price','cost','active','featured','image'],...filteredProducts().map(p=>[p.name,p.sku,p.variant,p.category,p.price,p.cost,p.active,p.featured,p.image])];download('jioflow-products.csv','\uFEFF'+rows.map(r=>r.map(csvSafe).join(',')).join('\r\n'),'text/csv')}
function downloadProductTemplate(){download('product-template.csv','name,sku,variant,category,price,cost,active,featured,image\nExample Product,ECO-NEW,100g,Food,590,,true,false,','text/csv')}
function productCSVDialog(){modal('Upload product CSV','Match existing SKUs to update products; new SKUs add products.',`<p class="small">Required columns: <b>name, sku, price</b>. Optional: variant, category, cost, active, featured, image. Use true/false for switches. Maximum 2,000 rows / 5 MB in this demo.</p><input type="file" id="product-csv" accept=".csv,text/csv"><div class="modal-footer"><button onclick="downloadProductTemplate()">Template</button><button class="primary" onclick="importProductCSV()">Import products</button></div>`)}
async function importProductCSV(){const f=$('#product-csv').files[0];if(!f)return toast('Choose a CSV file.');if(f.size>5*1024*1024)return toast('CSV exceeds 5 MB.');let rows;try{rows=csvParse(await f.text())}catch(e){return toast('Invalid CSV: '+e.message)}if(rows.length>2001)return toast('Use up to 2,000 product rows in this demo.');const h=rows.shift()?.map(x=>x.replace(/^\uFEFF/,'').trim().toLowerCase())||[];if(!['name','sku','price'].every(x=>h.includes(x)))return toast('Required columns: name, sku, price.');let added=0,updated=0,errors=[];const changes=[];rows.forEach((row,i)=>{if(row.every(x=>!x.trim()))return;const r=Object.fromEntries(h.map((k,j)=>[k,(row[j]||'').trim()]));if(!r.name||!r.sku||r.price===''||!Number.isFinite(Number(r.price))||Number(r.price)<0||r.cost&&(!Number.isFinite(Number(r.cost))||Number(r.cost)<0)){errors.push('Row '+(i+2)+': invalid name, SKU or price');return}if(r.image&&!r.image.startsWith('assets/')&&!/^https:\/\//.test(r.image)){errors.push('Row '+(i+2)+': image must use HTTPS or assets/');return}const old=db.products.find(p=>p.sku.toLowerCase()===r.sku.toLowerCase()),v={name:r.name,sku:r.sku,price:Number(r.price),updated:new Date().toISOString()};for(const k of ['variant','category','image'])if(h.includes(k))v[k]=r[k];if(h.includes('cost'))v.cost=r.cost===''?null:Number(r.cost);for(const k of ['active','featured'])if(h.includes(k)){if(!['true','false','1','0','yes','no',''].includes(r[k].toLowerCase())){errors.push('Row '+(i+2)+': invalid '+k);return}v[k]=['true','1','yes'].includes(r[k].toLowerCase())}changes.push({old,v});});if(errors.length)return modal('Fix the CSV before importing','No product changes were saved.',`<p>${errors.slice(0,20).map(esc).join('<br>')}</p><button onclick="productCSVDialog()">Choose corrected file</button>`);changes.forEach(({old,v})=>{const match=old||db.products.find(p=>p.sku.toLowerCase()===v.sku.toLowerCase());if(match){Object.assign(match,v);updated++}else{db.products.push({id:uid(),variant:'Default',category:'',cost:null,image:'',active:true,featured:false,...v});added++}});log('Product CSV: '+added+' added, '+updated+' updated');closeModal();render();toast(added+' products added; '+updated+' updated.')}
function agentReportsView(){if(role==='Agent'||!permitted('profit')&&role==='Manager')return heading('Agent Reports','Your administrator has not enabled reporting access.');const os=liveOrders().filter(inRange);return heading('Agent Reports','Call outcomes, follow-ups, conversions and deliveries side by side.',rangeSelect())+`<section class="card"><div class="table-wrap"><table><thead><tr><th>User</th><th>Assigned</th><th>Attempted</th><th>Pending</th><th>Completed</th><th>Not connected</th><th>Connected</th><th>Positive</th><th>Intermediate</th><th>Negative</th><th>Confirmed</th><th>Revenue</th><th>Purchase rate</th><th>Delivered / Returned</th><th></th></tr></thead><tbody>${db.agents.filter(a=>!a.archived).map(a=>{const cs=db.customers.filter(c=>c.agent===a.id),as=os.filter(o=>o.agent===a.id),m=metricSet(as,cs);return `<tr><td><strong>${esc(a.name)}</strong><small>${esc(a.code||'')}</small></td><td>${m.assigned}</td><td>${m.attempted}</td><td>${m.pending}</td><td>${m.completed}</td><td>${m.notConnected}</td><td>${m.connected}</td><td>${m.positive}</td><td>${m.intermediate}</td><td>${m.negative}</td><td>${m.confirmed}</td><td>${money(m.revenue)}</td><td>${ratio(new Set(as.filter(o=>confirmedStatus(o.status)).map(o=>o.customer)).size,cs.length)}</td><td>${as.filter(o=>o.shipment==='Delivered').length} / ${as.filter(o=>o.shipment==='Returned').length}</td><td><button onclick="agentReport('${a.id}')">Details</button></td></tr>`}).join('')}</tbody></table></div><p class="small muted">Order counts use the reporting period. Assignment and latest response counts are current profile snapshots; they are not historical call-event totals.</p></section>`}
function profitView(){if(!financialAccess())return heading('Profit','Financial access is restricted to authorized users.');const os=liveOrders().filter(inRange).filter(o=>confirmedStatus(o.status)),revenue=os.reduce((s,o)=>s+orderTotal(o),0),ps=os.map(orderProfit),received=os.reduce((s,o)=>s+Number(o.finance?.settled||0),0),collectable=os.filter(o=>o.shipment==='Delivered').reduce((s,o)=>s+due(o),0);return heading('Profit & Courier Settlements','Record real costs and settlements to understand your margins.',rangeSelect())+`<div class="stats">${stat('Confirmed revenue',money(revenue),'reports','Order value including delivery','featured')}${stat('Estimated profit',ps.some(p=>p===null)?'Cost missing':money(ps.reduce((s,p)=>s+p,0)),'reports','After recorded costs and fees')}${stat('Courier received',money(received),'check','Manually recorded settlements')}${stat('Delivered COD balance',money(Math.max(0,collectable-received)),'courier','Before unrecorded courier deductions')}</div><div class="notice">A demo ledger, not a courier reconciliation. Revenue is order value; settlement is cash received. Missing product costs prevent a reliable profit estimate.</div><section class="card"><div class="table-wrap"><table><thead><tr><th>Order</th><th>Customer</th><th>Revenue</th><th>Product cost</th><th>Courier / other fees</th><th>Profit</th><th>Settlement</th><th></th></tr></thead><tbody>${os.map(o=>{const p=orderProfit(o),f=o.finance||{},cost=o.items.some(x=>(x.cost??product(x.product)?.cost)==null)?null:o.items.reduce((s,x)=>s+x.qty*(x.cost??product(x.product)?.cost),0);return `<tr><td>${esc(o.id)}</td><td>${esc(customer(o.customer)?.name)}</td><td>${money(orderTotal(o))}</td><td>${cost===null?'Not set':money(cost)}</td><td>${money(Number(f.courierCost??o.delivery)+Number(f.codFee||0)+Number(f.packaging||0)+Number(f.returnFee||0))}</td><td>${p===null?'Cost missing':money(p)}</td><td>${money(f.settled||0)}</td><td><button onclick="financeForm('${o.id}')">Record costs</button></td></tr>`}).join('')||'<tr><td colspan="8">No confirmed orders in this period.</td></tr>'}</tbody></table></div></section>`}
function financeForm(id){if(!financialAccess())return;const o=db.orders.find(o=>o.id===id),f=o.finance||{};modal('Order costs & settlement',id+' · manual demo ledger',`<form onsubmit="saveFinance(event,'${id}')"><div class="form-grid">${o.items.map((x,i)=>field((product(x.product)?.name||x.name)+' unit cost','itemcost'+i,x.cost??product(x.product)?.cost??'','number','min="0" step="0.01" required')).join('')}${field('Courier expense','courierCost',f.courierCost??o.delivery,'number','min="0" step="0.01" required')}${field('COD fee','codFee',f.codFee||0,'number','min="0" step="0.01"')}${field('Packaging expense','packaging',f.packaging||0,'number','min="0" step="0.01"')}${field('Return expense','returnFee',f.returnFee||0,'number','min="0" step="0.01"')}${field('Courier cash received','settled',f.settled||0,'number','min="0" step="0.01"')}${field('Settlement reference','reference',f.reference||'')}</div>${modalFooter('Save ledger entry')}</form>`)}
function saveFinance(e,id){e.preventDefault();if(!financialAccess())return;const o=db.orders.find(o=>o.id===id),f=new FormData(e.target);o.items.forEach((x,i)=>x.cost=Number(f.get('itemcost'+i)));o.finance=Object.fromEntries(['courierCost','codFee','packaging','returnFee','settled'].map(k=>[k,Number(f.get(k)||0)]));o.finance.reference=f.get('reference');log('Financial ledger updated '+id);closeModal();render();toast('Costs and settlement saved.')}

function setCustomerTab(i){subtab=['All','Unassigned','Assigned','Permanent','Due Today',...db.settings.statuses][i];window.callFilter='';window.responseFilter='';window.funnelFilter='';window.customerSource='';pageNo=1;selected.clear();render()}
// Separate demo identities. These are intentionally not production authentication.
if(!db.agents.some(a=>a.id==='demo-manager'))db.agents.push({id:'demo-manager',name:'Demo Agent',email:'manager@demo.jioflow.test',phone:'',code:'M-001',role:'Agent',active:true,permissions:{assign:false,booking:true,products:true,import:true,packing:true,team:false,profit:false,pull:false,price:true,discount:true,advance:true},pullCount:20,dailyLimit:0,discountLimit:0,sources:['Website','CSV Import','Facebook']});
let signedIn=false,sessionAccount=null;
function demoAccounts(){return [{id:'platform-admin',name:'Platform Admin',email:'superadmin@demo.jioflow.test',role:'Super Admin',store:'Platform'},{id:'store-owner',name:'Ecory Owner',email:'owner@demo.jioflow.test',role:'Admin',store:db.settings.storeName},...db.agents.filter(a=>!a.archived).map(a=>({...a,role:a.role||'Agent',store:db.settings.storeName}))]}
function accountGateway(){const accounts=demoAccounts();$('#app').innerHTML=`<main class="account-page"><div class="account-brand"><span class="brandmark"></span><strong>Jio<span>Flow</span></strong></div><div class="account-heading"><span class="badge green">Your workspace. Your account.</span><h1>Sign in to your workspace</h1><p>Each person has a separate account and a role that controls their workspace.</p></div><div class="notice account-demo-note"><strong>Interactive demo account access</strong><br>Choose a sample identity below. This preview does not verify passwords or protect real customer data. Secure email/password login and tenant isolation will be added with Supabase.</div><div class="account-tiles">${accounts.map((a,i)=>`<button class="account-tile" onclick="enterAccount(${i})" ${a.active===false?'disabled':''}><span class="avatar">${initials(a.name)}</span><span><strong>${esc(a.name)}</strong><small>${esc(a.email)}</small><span class="badge">${esc(a.role==='Admin'?'Admin':a.role)}</span> <small>${esc(a.store)}</small></span><span class="account-enter">${a.active===false?'Inactive':'Enter →'}</span></button>`).join('')}</div><p class="account-foot">Agents see their own customer queue. Admins manage their store. Platform admins see aggregates only.</p></main>`}
function enterAccount(i){const a=demoAccounts()[i];if(!a||a.active===false)return toast('This account is inactive.');sessionAccount={id:a.id,role:a.role,email:a.email,name:a.name};signedIn=true;role=a.role;if(!['Admin','Super Admin'].includes(role)){agentId=a.id;registerDemoSession(a)}page='dashboard';selected.clear();try{sessionStorage.setItem('jioflow.demo.session',JSON.stringify(sessionAccount))}catch{}render();toast('Signed in as '+a.name+' · demo identity')}
function signOut(){signedIn=false;sessionAccount=null;try{sessionStorage.removeItem('jioflow.demo.session')}catch{}closeModal();accountGateway()}
function restoreDemoSession(){try{const session=JSON.parse(sessionStorage.getItem('jioflow.demo.session'));const index=demoAccounts().findIndex(a=>a.id===session?.id&&a.active!==false);if(index>=0){const a=demoAccounts()[index];sessionAccount={id:a.id,role:a.role,email:a.email,name:a.name};signedIn=true;role=a.role;if(!['Admin','Super Admin'].includes(role)){agentId=a.id;registerDemoSession(a)}}}catch{}}
function askConfirm(title,message){return new Promise(resolve=>{modal(title,'Please review before continuing.',`<p>${esc(message)}</p><div class="modal-footer"><button onclick="closeModal()">Cancel</button><button class="primary" onclick="finishConfirmation(true)">Continue</button></div>`);pendingConfirmation=resolve})}
function finishConfirmation(yes){const resolve=pendingConfirmation;pendingConfirmation=null;closeModal();resolve?.(yes)}
function accountInfo(){if(!sessionAccount)return;modal('Your account','Separate demo identity · '+sessionAccount.email,`<div class="detail-kv"><div><small>Name</small><strong>${esc(sessionAccount.name)}</strong></div><div><small>Role</small><strong>${esc(role==='Admin'?'Admin':role)}</strong></div></div><p>${role==='Super Admin'?'Platform totals only. Customer data is hidden.':role==='Agent'?'Only your assigned follow-ups and orders are shown. Product costs and profit are hidden.':'Your permissions determine which store sections you can use.'}</p><div class="notice">Demo login is not secure authentication. Production sessions will be verified by Supabase.</div><div class="modal-footer"><button onclick="closeModal()">Close</button><button class="primary" onclick="signOut()">Switch account / Sign out</button></div>`)}

function importedStatusOptions(){return [...new Set(['Delivered','Partial','Preorder','Return','Cancelled','Pending',...db.orders.map(o=>o.importedStatus).filter(Boolean)])]}
function pullSourceOptions(){return [...new Set(['Website','CSV Import','Facebook','Phone','WhatsApp','Repeat Customer',...db.customers.map(c=>c.source),...db.orders.map(o=>o.source)].filter(Boolean))]}
function eligibleForPull(c,a){if(c.agent||c.permanent)return false;const statusRestricted=a.importedStatusMode==='selected',sourceRestricted=a.sourceMode!=='all',statuses=a.importedStatuses||[],sources=a.sources||[];if(!statusRestricted&&(!sourceRestricted||sources.includes(c.source)))return true;return db.orders.some(o=>o.customer===c.id&&(!statusRestricted||statuses.includes(o.importedStatus))&&(!sourceRestricted||sources.includes(o.source)))}
function agentForm(id){if(role==='Manager')return toast('Only Admin can edit Manager permissions.');const a=agent(id)||{permissions:{pull:true,price:true,discount:true,advance:true,booking:true},sources:['Website','CSV Import','Facebook'],importedStatuses:[]};const statuses=importedStatusOptions(),sources=pullSourceOptions();modal(id?'Edit user & permissions':'Add user','Personal details, processing view, self-pull rules and account sessions.',`<form onsubmit="saveAgent(event,'${id||''}')"><div class="form-grid">${field('Full name','name',a.name,'text','required')}${field('Email','email',a.email,'email','required')}${field('Phone','phone',a.phone||'','tel')}${field('User code','code',a.code||'')}${selectField('Role','userRole',['Agent','Manager','Admin'],a.role||'Agent')}</div><section class="edit-section"><h3>Processing view</h3><p class="small muted">Only Admin can change this Agent's follow-up layout.</p><div class="segmented"><label><input type="radio" name="processingView" value="Table" ${a.processingView!=='Card'?'checked':''}> Table</label><label><input type="radio" name="processingView" value="Card" ${a.processingView==='Card'?'checked':''}> Card</label></div></section><section class="edit-section"><h3>Take More Orders</h3><label class="permission"><input type="checkbox" name="pull" ${a.permissions.pull?'checked':''}> Allow self-assignment</label><div class="form-grid">${field('Orders per pull','pullCount',a.pullCount??20,'number','min="1" max="1000" required')}${selectField('Daily pull policy','dailyMode',['No daily limit','Limit per day'],a.dailyLimit?'Limit per day':'No daily limit')}${field('Maximum per day (if limited)','dailyLimit',a.dailyLimit||50,'number','min="1" max="100000"')}</div><p class="small muted">At the daily limit, new pulls pause until the next Bangladesh calendar day. Each customer is assigned once, regardless of order count.</p><div class="form-grid"><div>${selectField('By imported status','importedStatusMode',['all','selected'],a.importedStatusMode||'all')}<p class="small muted">all = any imported status; selected = checked statuses only.</p><div class="checklist">${statuses.map(s=>`<label><input type="checkbox" name="importedStatuses" value="${esc(s)}" ${(a.importedStatuses||[]).includes(s)?'checked':''}><span>${esc(s)}</span><small>${new Set(db.orders.filter(o=>o.importedStatus===s).map(o=>o.customer)).size}</small></label>`).join('')}</div></div><div>${selectField('By order source','sourceMode',['all','selected'],a.sourceMode||'selected')}<p class="small muted">Counts are unique customer profiles, not package limits.</p><div class="checklist">${sources.map(s=>`<label><input type="checkbox" name="sources" value="${esc(s)}" ${(a.sources||[]).includes(s)?'checked':''}><span>${esc(s)}</span><small>${db.customers.filter(c=>c.source===s||db.orders.some(o=>o.customer===c.id&&o.source===s)).length}</small></label>`).join('')}</div></div></div></section><section class="edit-section"><h3>Sales & role permissions</h3>${field('Discount limit (0 = unlimited)','discountLimit',a.discountLimit||0,'number','min="0"')}<div class="permission-grid">${[['price','Change selling prices'],['discount','Give discounts'],['advance','Verify advance payment'],['booking','Book couriers']].map(([k,label])=>`<label class="permission"><input type="checkbox" name="${k}" ${a.permissions[k]?'checked':''}>${label}</label>`).join('')}</div><p class="small muted">Agents cannot view product costs or profit.</p></section><section class="edit-section"><h3>Password & sessions</h3><div class="field"><label>New password (optional)</label><input type="password" disabled placeholder="Available after secure Supabase authentication is connected" autocomplete="new-password"></div><p class="small muted">No passwords are collected or stored in this browser demo.</p><div class="notice">Admin approval is required for every new Agent login.</div>${id?sessionPanel(id):'<p class="small muted">Save the user to manage sessions.</p>'}</section>${modalFooter('Save user')}</form>`)}
function saveAgent(e,id){e.preventDefault();const f=new FormData(e.target),email=f.get('email').trim().toLowerCase();if(db.agents.some(a=>a.email.toLowerCase()===email&&a.id!==id))return toast('This email is already used.');if(['owner@demo.jioflow.test','superadmin@demo.jioflow.test'].includes(email))return toast('This is a reserved demo account email.');if(f.get('importedStatusMode')==='selected'&&!f.getAll('importedStatuses').length)return toast('Select at least one imported status, or choose all.');if(f.get('sourceMode')==='selected'&&!f.getAll('sources').length)return toast('Select at least one source, or choose all.');const a={name:f.get('name').trim(),email,phone:f.get('phone').trim(),code:f.get('code').trim(),role:f.get('userRole')||'Agent',processingView:f.get('processingView'),pullCount:Math.max(1,Number(f.get('pullCount'))||20),dailyLimit:f.get('dailyMode')==='Limit per day'?Number(f.get('dailyLimit'))||50:0,discountLimit:Number(f.get('discountLimit'))||0,sourceMode:f.get('sourceMode'),sources:f.getAll('sources'),importedStatusMode:f.get('importedStatusMode'),importedStatuses:f.getAll('importedStatuses'),requireApproval:true,permissions:Object.fromEntries(['pull','price','discount','advance','booking','assign','products','import','team','profit','settings'].map(k=>[k,f.has(k)]))};if(role==='Manager'&&(a.role!=='Agent'||agent(id)?.role==='Manager'))return toast('Only Admin can change Manager permissions.');if(id)Object.assign(agent(id),a);else db.agents.push({id:uid(),...a,active:true});log('User permissions saved');closeModal();render();toast('User and self-pull rules saved.')}
function pullOrders(){if(role!=='Agent'||!currentAgent()?.active||!permitted('pull'))return toast('Self-assignment permission is disabled.');const a=currentAgent(),today=new Date().toLocaleDateString('en-CA',{timeZone:'Asia/Dhaka'}),used=a.pullDate===today?a.pulledToday||0:0,n=a.dailyLimit?Math.min(a.pullCount,Math.max(0,a.dailyLimit-used)):a.pullCount;if(n<=0)return toast('Daily limit reached. More customers can be pulled tomorrow (Bangladesh time).');const cs=db.customers.filter(c=>eligibleForPull(c,a)).slice(0,n);if(!cs.length)return toast('No unassigned customers match your permitted sources and imported statuses.');cs.forEach(c=>c.agent=a.id);a.pullDate=today;a.pulledToday=used+cs.length;log(cs.length+' customer profiles self-assigned');render();toast(cs.length+' customers added to your queue.')}
function agentCustomerCards(cs){return `<div class="customer-cards">${cs.slice((pageNo-1)*rowsPerPage,pageNo*rowsPerPage).map(c=>`<article class="customer-mini"><div class="row between"><strong>${esc(c.name)}</strong>${badge(c.status)}</div><a class="customer-phone" href="tel:${esc(c.phone)}">${ico('phone')} ${esc(c.phone)}</a><p class="small muted">${esc(c.address)}</p><div class="row between"><span class="small muted">${db.orders.filter(o=>o.customer===c.id).length} orders · ${esc(c.source)}</span>${c.permanent?badge('Permanent'):''}</div>${c.callback?`<p class="small">Next call: ${esc(c.callback.replace('T',' '))}</p>`:''}<div class="row section-gap"><button onclick="showCustomer('${c.id}')">Open profile</button><button class="primary" onclick="followupForm('${c.id}')">Record follow-up</button></div></article>`).join('')}</div>`}
if(!db.sessions)db.sessions=[];
let currentDemoSessionId=null;
function demoDeviceId(){try{let id=sessionStorage.getItem('jioflow.demo.device');if(!id){id=uid();sessionStorage.setItem('jioflow.demo.device',id)}return id}catch{return 'demo-current-tab'}}
function registerDemoSession(a,resume=false){if(a.role!=='Agent')return;const device=demoDeviceId(),saved=resume?sessionStorage.getItem('jioflow.approval.session'):null;let s=saved?db.sessions.find(s=>s.id===saved&&s.user===a.id&&s.device===device):null;if(!s){db.sessions.filter(x=>x.user===a.id&&x.device===device&&x.status==='Pending').forEach(x=>x.status='Superseded');s={id:uid(),user:a.id,device,label:'Agent login request',status:'Pending',created:new Date().toISOString(),lastSeen:new Date().toISOString()};db.sessions.push(s)}s.lastSeen=new Date().toISOString();currentDemoSessionId=s.id;sessionStorage.setItem('jioflow.approval.session',s.id);save()}

function sessionPanel(id){const sessions=(db.sessions||[]).filter(s=>s.user===id);return `<h4>Login approvals & session history</h4><p class="small muted">Every new Agent login needs Admin approval. Approving one session revokes this Agent's other sessions.</p>${sessions.length?sessions.map(s=>`<div class="session-row"><div><strong>${esc(s.label)}</strong> ${badge(s.status)}<small>Requested ${date(s.created)} · Last seen ${date(s.lastSeen)}</small></div><div class="row">${s.status==='Pending'?`<button type="button" onclick="manageSession('${s.id}','approve')">Approve</button><button type="button" onclick="manageSession('${s.id}','reject')">Reject</button>`:s.status==='Approved'?`<button type="button" onclick="manageSession('${s.id}','revoke')">Revoke access</button>`:''}</div></div>`).join(''):'<div class="notice">No login requests yet.</div>'}`}
function manageSession(id,action){if(role!=='Admin')return toast('Only Admin can approve Agent logins.');const s=db.sessions.find(s=>s.id===id),user=s&&agent(s.user);if(!s||!user)return;if(action==='approve'){if(s.status!=='Pending'||!user.active||user.archived)return toast('This request cannot be approved.');db.sessions.filter(x=>x.user===s.user&&['Approved','Pending'].includes(x.status)).forEach(x=>x.status=x.id===id?'Approved':'Revoked')}else if(action==='reject'&&s.status==='Pending')s.status='Rejected';else if(action==='revoke'&&s.status==='Approved')s.status='Revoked';else return;s.reviewed=new Date().toISOString();s.reviewedBy=sessionAccount?.id||'Admin';log('Login '+action+' for '+user.name);closeModal();render();toast('Agent login request updated.')}

function waitingSession(){const session=db.sessions.find(s=>s.id===currentDemoSessionId),status=session?.status||'Pending';$('#app').innerHTML=`<main class="account-page approval-wait"><section class="approval-wait-card"><span class="auth-role-icon">${ico('clock')}</span><span class="badge orange">${esc(status)}</span><h1>${status==='Pending'?'Waiting for Admin approval':'Access not approved'}</h1><p>${esc(sessionAccount?.name)}, your login request has been sent to Admin.</p><p class="small muted">Your dashboard, customers and orders stay locked until Admin accepts this request.</p><div class="row"><button class="primary" onclick="checkLoginApproval()">Check approval</button><button onclick="signOut()">Back to Agent Login</button></div><div class="notice">Browser demo: approval works between tabs in this browser. Shared online approval across devices requires Supabase.</div></section></main>`}
function checkLoginApproval(){const latest=readStore(activeStoreId);if(latest)db=latest;render()}

function sessionAllowed(){if(role!=='Agent')return true;const s=db.sessions.find(s=>s.id===currentDemoSessionId);return !!currentAgent()?.active&&!currentAgent()?.archived&&s?.user===agentId&&s?.status==='Approved'}


'use strict';
// Local demo authentication adapter. Replace with Supabase Auth for production.
let authDirectory;try{authDirectory=JSON.parse(localStorage.getItem('jioflow.auth.v1'))||{accounts:[],stores:[]}}catch{authDirectory={accounts:[],stores:[]}}
let activeStoreId=null,authPage='login',authBusy=false;
function persistAuth(){localStorage.setItem('jioflow.auth.v1',JSON.stringify(authDirectory))}
function readStore(id){try{return JSON.parse(localStorage.getItem('jioflow.store.'+id))||(id==='ecory'?JSON.parse(localStorage.getItem('jioflow.demo.v1')):null)}catch{return null}}
function loadStore(id){activeStoreId=id;db=readStore(id)||seed();for(const a of db.agents){a.requireApproval=true;}if(!db.sessions)db.sessions=[];for(const status of lifecycleStatuses)if(!db.settings.statuses.includes(status))db.settings.statuses.push(status);agentId=db.agents[0]?.id||''}
function blankStore(name){const d=seed();Object.assign(d,{customers:[],orders:[],agents:[],products:[],activity:[],sessions:[],stores:[]});d.settings.storeName=name;return d}
function accountGateway(view=authPage){authPage=view==='signup'?'signup':'login';const signup=authPage==='signup';$('#app').innerHTML=`<main class="login-layout"><section class="login-story"><div class="account-brand"><span class="brandmark"></span><strong>Jio<span>Flow</span></strong></div><div><span class="badge green">Your business, in flow.</span><h1>One login.<br>Your own workspace.</h1><p>Your account opens the right panel automatically. Customers, follow-ups, orders and your team—connected in one place.</p><div class="login-points"><span>${ico('check')} One login for every account</span><span>${ico('check')} Super Admin, Owner and Agent signup</span><span>${ico('check')} Agent access requires Admin approval</span></div></div><small>JioFlow · Made for better business days.</small></section><section class="login-form-area"><div class="login-box"><div class="auth-tabs auth-role-tabs"><button class="${!signup?'active':''}" onclick="accountGateway('login')">Login</button><button class="${signup?'active':''}" onclick="accountGateway('signup')">Create Account</button></div><span class="auth-role-icon">${ico(signup?'customers':'logout')}</span><h2>${signup?'Create your account':'Welcome back.'}</h2><p class="muted small">${signup?'Choose your account type to get started.':'Enter your email and password. Your saved account determines which panel opens.'}</p><div class="auth-demo"><strong>Browser demo</strong> · Use a test password. Online, cross-device access will be connected with Supabase.</div><form onsubmit="${signup?'createLocalAccount':'loginLocalAccount'}(event)">${signup?`${field('Full name','auth-name','','text','required autocomplete="name" maxlength="100"')}${selectField('Account type','auth-type',['Super Admin','Owner','Agent'],'Owner').replace('<select ','<select onchange="updateSignupType(this.value)" ')}<div id="signup-store-field">${field('Workspace name','auth-store','Ecory','text','maxlength="100"')}</div><div id="signup-code-field" hidden>${field('Workspace code','auth-workspace','','text','autocomplete="off"')}<p class="small muted">Get this code from your Admin. Your Agent panel opens only after login approval.</p></div>`:''}${field('Email','auth-email','','email','required autocomplete="email"')}${field('Password','auth-password','','password',`required minlength="6" maxlength="128" autocomplete="${signup?'new-password':'current-password'}"`)}${signup?field('Confirm password','auth-confirm','','password','required minlength="6" maxlength="128" autocomplete="new-password"'):''}<label class="permission"><input type="checkbox" onchange="document.querySelectorAll('#auth-password,#auth-confirm').forEach(el=>el.type=this.checked?'text':'password')">Show password</label><p id="auth-error" class="auth-error" role="alert"></p><button id="auth-submit" class="dark auth-submit" type="submit">${signup?'Create account':'Login'} ${ico('arrow')}</button></form><p class="auth-help">${signup?'Already have an account? <button onclick="accountGateway(&quot;login&quot;)">Login</button>':'New here? <button onclick="accountGateway(&quot;signup&quot;)">Create Account</button>'}</p><small class="muted">Super Admin and Owner share the Admin panel. Agents use their own assigned workspace after approval.</small></div></section></main>`}
function updateSignupType(type){const agent=type==='Agent';$('#signup-store-field').hidden=agent;$('#signup-code-field').hidden=!agent;$('#auth-store').required=!agent;$('#auth-workspace').required=agent}

function adminRole(value){return ['Admin','Owner','Store Owner','Super Admin'].includes(value)}
function migrateAdminAccount(a){if(!adminRole(a.role)||a.memberId)return;a.accountType||=a.role==='Super Admin'?'Super Admin':'Owner';if(!a.storeId){let store=authDirectory.stores.find(s=>s.owner===a.id)||authDirectory.stores.find(s=>s.active)||authDirectory.stores[0];if(!store){const id='ecory',data=readStore(id)||seed();store={id,name:data.settings.storeName||'Ecory',owner:a.id,active:true};authDirectory.stores.push(store);localStorage.setItem('jioflow.store.'+id,JSON.stringify(data))}a.storeId=store.id}a.role='Admin';delete a.memberId;persistAuth()}

function authError(message){const el=$('#auth-error');if(el)el.textContent=message;else toast(message)}
function setAuthBusy(b){authBusy=b;const button=$('#auth-submit');if(button){button.disabled=b;button.textContent=b?'Please wait…':authPage==='signup'?'Create account':'Login'}}
async function passwordRecord(password,salt){if(!globalThis.crypto?.subtle)throw Error('Password login requires HTTPS. Please open the published preview.');const bytes=salt?Uint8Array.from(salt):crypto.getRandomValues(new Uint8Array(16)),key=await crypto.subtle.importKey('raw',new TextEncoder().encode(password),'PBKDF2',false,['deriveBits']),bits=await crypto.subtle.deriveBits({name:'PBKDF2',salt:bytes,iterations:210000,hash:'SHA-256'},key,256);return {salt:Array.from(bytes),hash:Array.from(new Uint8Array(bits))}}
async function passwordMatches(password,record){if(!record?.salt||!record?.hash)return false;const next=await passwordRecord(password,record.salt);return next.hash.length===record.hash.length&&next.hash.reduce((sum,b,i)=>sum|(b^record.hash[i]),0)===0}
function accountByEmail(email){return authDirectory.accounts.find(a=>a.email===email.trim().toLowerCase())}
async function createLocalAccount(e){e.preventDefault();if(authBusy)return;const f=new FormData(e.target),name=f.get('auth-name').trim(),email=f.get('auth-email').trim().toLowerCase(),password=f.get('auth-password'),type=f.get('auth-type');authError('');if(!['Super Admin','Owner','Agent','Admin','Store Owner','Invited Agent'].includes(type))return authError('Choose Super Admin, Owner or Agent.');if(password!==f.get('auth-confirm'))return authError('Passwords do not match.');if(password.length<6)return authError('Use at least 6 characters for your test password.');if(accountByEmail(email))return authError('This email already has an account. Please login.');setAuthBusy(true);try{let account;const record=await passwordRecord(password);if(['Agent','Invited Agent'].includes(type)){const code=f.get('auth-workspace').trim(),store=authDirectory.stores.find(s=>s.id.toLowerCase()===code.toLowerCase());if(!store?.active)throw Error('Enter a valid active workspace code from your Admin.');const data=readStore(store.id);if(!data)throw Error('Workspace data is unavailable.');let member=data.agents.find(a=>a.email.toLowerCase()===email);if(member&&(member.archived||!member.active))throw Error('Your Agent account is inactive. Contact Admin.');if(!member){member={id:uid(),name,email,role:'Agent',active:true,requireApproval:true,permissions:{pull:false,price:false,discount:false,advance:false,booking:false},pullCount:20,dailyLimit:0,discountLimit:0,sources:[],sourceMode:'selected',importedStatuses:[],importedStatusMode:'all',processingView:'Table'};data.agents.push(member);localStorage.setItem('jioflow.store.'+store.id,JSON.stringify(data))}account={id:uid(),memberId:member.id,storeId:store.id,name:member.name,role:'Agent',accountType:'Agent',email,password:record}}else{const storeName=f.get('auth-store').trim();if(!storeName)throw Error('Enter a store name.');const first=!authDirectory.stores.length,id=first?'ecory':'JF-'+uid().slice(0,8).toUpperCase(),data=first?(readStore(id)||seed()):blankStore(storeName);data.settings.storeName=storeName;account={id:uid(),name,email,role:'Admin',accountType:type==='Super Admin'?'Super Admin':'Owner',storeId:id,password:record};authDirectory.stores.push({id,name:storeName,owner:account.id,active:true});localStorage.setItem('jioflow.store.'+id,JSON.stringify(data))}account.created=new Date().toISOString();authDirectory.accounts.push(account);persistAuth();startAccountSession(account);toast('Account created. Your panel is ready.')}catch(error){authError(error.message)}finally{setAuthBusy(false)}}
async function loginLocalAccount(e){e.preventDefault();try{const latest=JSON.parse(localStorage.getItem('jioflow.auth.v1'));if(latest)authDirectory=latest}catch{}if(authBusy)return;const f=new FormData(e.target);authError('');setAuthBusy(true);try{const a=accountByEmail(f.get('auth-email'));if(!a||!(await passwordMatches(f.get('auth-password'),a.password)))throw Error('Email or password is incorrect.');startAccountSession(a)}catch(error){authError(error.message)}finally{setAuthBusy(false)}}
function startAccountSession(a,{resume=false}={}){migrateAdminAccount(a);currentDemoSessionId=null;const store=authDirectory.stores.find(s=>s.id===a.storeId);if(!store?.active)throw Error('This workspace is inactive.');loadStore(a.storeId);if(a.memberId){const member=agent(a.memberId);if(!member?.active||member.archived)throw Error('Your account is inactive. Contact your Admin.');role=member.role==='Manager'?'Manager':member.role==='Admin'?'Admin':'Agent';a.role=role;agentId=member.id;a.name=member.name}else role='Admin';sessionAccount={id:a.id,name:a.name,email:a.email,role,accountType:a.accountType||(role==='Agent'?'Agent':'Owner'),storeId:a.storeId,memberId:a.memberId};signedIn=true;if(role==='Agent')registerDemoSession(currentAgent(),resume);sessionStorage.setItem('jioflow.auth.session',JSON.stringify({id:a.id}));page='dashboard';selected.clear();query='';cart=[];render()}

function signOut(){if(role==='Agent'&&currentDemoSessionId){const request=db.sessions?.find(s=>s.id===currentDemoSessionId);if(request&&['Approved','Pending'].includes(request.status)){request.status='Signed out';save()}}sessionStorage.removeItem('jioflow.approval.session');signedIn=false;sessionAccount=null;currentDemoSessionId=null;sessionStorage.removeItem('jioflow.auth.session');sessionStorage.removeItem('jioflow.demo.session');closeModal();authPage='login';accountGateway()}
function restoreDemoSession(){try{const s=JSON.parse(sessionStorage.getItem('jioflow.auth.session')),a=authDirectory.accounts.find(a=>a.id===s?.id);if(a)startAccountSession(a,{resume:true})}catch{signedIn=false}}
function enterAccount(){accountGateway('login')}
function setRole(){accountGateway('login')}
function accountInfo(){modal('Your account',sessionAccount?.email||'',`<div class="detail-kv"><div><small>Account type</small><strong>${esc(sessionAccount?.accountType||(role==='Agent'?'Agent':'Owner'))}</strong></div><div><small>Name</small><strong>${esc(sessionAccount?.name)}</strong></div><div><small>Role</small><strong>${esc(role==='Admin'?'Admin':role)}</strong></div>${activeStoreId?`<div><small>Workspace code</small><strong>${esc(activeStoreId)}</strong></div>`:''}</div><div class="notice">Browser-local demo. Online authentication and server-enforced permissions require Supabase.</div><div class="modal-footer"><button onclick="closeModal()">Close</button><button class="primary" onclick="signOut()">Sign out</button></div>`)}
async function saveMemberCredential(member,password){const duplicate=accountByEmail(member.email),old=authDirectory.accounts.find(a=>a.storeId===activeStoreId&&a.memberId===member.id);if(duplicate&&duplicate.id!==old?.id)throw Error('Email belongs to another login account.');if(!old&&!password)return;const record=password?await passwordRecord(password):old.password,account=old||{id:uid(),memberId:member.id,storeId:activeStoreId};Object.assign(account,{email:member.email.toLowerCase(),name:member.name,role:member.role||'Agent',password:record});if(!old)authDirectory.accounts.push(account);persistAuth()}
const saveAgentWithoutLogin=saveAgent;
saveAgent=async function(e,id){e.preventDefault();if(memberSaving)return;const f=new FormData(e.target),password=f.get('memberPassword')||'',email=f.get('email').trim().toLowerCase(),existing=authDirectory.accounts.find(a=>a.storeId===activeStoreId&&a.memberId===id),duplicate=accountByEmail(email);if(duplicate?.id!==existing?.id&&duplicate)return toast('This email belongs to another login account.');if(password&&password.length<6)return toast('Test password must have at least 6 characters.');const before=JSON.stringify(db.agents);memberSaving=true;try{if(password)await passwordRecord(password);saveAgentWithoutLogin(e,id);const member=id?agent(id):db.agents.find(a=>a.email===email);if(member&&JSON.stringify(db.agents)!==before)await saveMemberCredential(member,password)}catch(error){toast(error.message)}finally{memberSaving=false}};
let memberSaving=false;
const originalAgentEditor=agentForm;
agentForm=function(id){originalAgentEditor(id);const input=$('#modal input[autocomplete="new-password"]');if(input){input.disabled=false;input.name='memberPassword';input.minLength=8;input.placeholder=id?'Leave blank to keep the current test password':'Set a test password or let invited staff create one';input.insertAdjacentHTML('afterend','<p class="small muted">Local demo password only. Staff can also activate their invited email through Create Account using workspace code <b>'+esc(activeStoreId||'')+'</b>.</p>');input.parentElement.nextElementSibling.textContent='Only a salted password hash is saved in this browser demo. Use test credentials.'}};
function platformStores(){return authDirectory.stores.map(s=>{const d=readStore(s.id);return {...s,users:d?.agents.filter(a=>!a.archived).length||0,orders:d?.orders.length||0}})}
function superView(){const stores=platformStores();return heading('Platform overview','Aggregate store activity. Customer details stay inside each store.')+`<div class="stats">${stat('Stores',stores.length,'stores','Independent workspaces','featured')}${stat('Active stores',stores.filter(s=>s.active).length,'check','Current status')}${stat('Users',stores.reduce((n,s)=>n+s.users,0),'customers','Aggregate only')}${stat('Orders',stores.reduce((n,s)=>n+s.orders,0),'orders','Aggregate only')}</div>${storesView(true)}`}
function storesView(embedded=false){return (embedded?'':heading('Stores','Manage store status without opening customer records.'))+`<section class="card"><h2>Store directory</h2><p class="small muted">Admins use Create Account. No package order or user limits.</p><div class="table-wrap"><table><thead><tr><th>Store</th><th>Workspace code</th><th>Status</th><th>Users</th><th>Orders</th><th></th></tr></thead><tbody>${platformStores().map((s,i)=>`<tr><td>${esc(s.name)}</td><td>${esc(s.id)}</td><td>${badge(s.active?'Active':'Inactive')}</td><td>${s.users}</td><td>${s.orders}</td><td><button onclick="toggleStoreAccount(${i})">${s.active?'Pause':'Activate'}</button></td></tr>`).join('')||'<tr><td colspan="6">No stores yet.</td></tr>'}</tbody></table></div></section>`}
function toggleStoreAccount(i){if(role!=='Admin')return;if(authDirectory.stores[i]?.id===activeStoreId)return toast('You cannot pause the workspace you are currently using.');authDirectory.stores[i].active=!authDirectory.stores[i].active;persistAuth();render()}
function loginRequestsMarkup(){const pending=(db.sessions||[]).filter(s=>s.status==='Pending'&&agent(s.user)&&!agent(s.user).archived);return `<section class="card login-requests" data-layout-title="Agent login requests"><div class="section-title"><div><h2>Agent login requests</h2><p>Approve a request to open the Agent's panel.</p></div><span class="badge orange">${pending.length} pending</span></div>${pending.map(s=>{const a=agent(s.user);return `<div class="approval-request-row"><span class="avatar">${initials(a.name)}</span><div><strong>${esc(a.name)}</strong><small>${esc(a.email)} · ${esc(a.code||'Agent')}</small><small>${esc(new Date(s.created).toLocaleString('en-GB',{timeZone:'Asia/Dhaka'}))} BD</small></div><button class="primary" onclick="manageSession('${s.id}','approve')">Approve</button><button class="ghost danger" onclick="manageSession('${s.id}','reject')">Reject</button></div>`}).join('')||'<p class="small muted">No pending requests. New Agent logins appear here.</p>'}</section>`}
function showLoginRequests(){if(role!=='Admin')return;modal('Agent login requests','Only approved Agents can open their panel.',loginRequestsMarkup())}
const teamViewWithoutApprovals=teamView;
teamView=function(){const html=teamViewWithoutApprovals();if(role!=='Admin')return html;const at=html.indexOf('<div class="notice">');return html.slice(0,at)+loginRequestsMarkup()+html.slice(at)};

'use strict';
let reportAgentId='',reportSection='customers',reportFilter='All',reportSearch='',reportPage=1,dashboardTab='Overview',profitTab='Overview';
const chartColors=['#99d13e','#294d3b','#8abca5','#c0d7a3','#a9b7c8','#d5ba91'];
function sumBy(items,fn){return items.reduce((n,x)=>n+Number(fn(x)||0),0)}
function confirmedInRange(){return liveOrders().filter(inRange).filter(o=>confirmedStatus(o.status))}
function financeTotals(os){const gross=sumBy(os,o=>sumBy(o.items,x=>x.qty*x.price)),discount=sumBy(os,o=>o.discount),delivery=sumBy(os,o=>o.delivery),missing=os.some(o=>o.items.some(x=>(x.cost??product(x.product)?.cost)==null)),cost=sumBy(os,o=>sumBy(o.items,x=>x.qty*(x.cost??product(x.product)?.cost??0))),fees=sumBy(os,o=>Number(o.finance?.courierCost??o.delivery)+Number(o.finance?.codFee||0)+Number(o.finance?.packaging||0)+Number(o.finance?.returnFee||0)+Number(o.finance?.otherCost||0)),revenue=gross-discount+delivery,profit=missing?null:revenue-cost-fees;return {gross,discount,delivery,revenue,cost:missing?null:cost,fees,profit,margin:profit===null||!revenue?null:profit/revenue*100}}
function percentage(n){return n==null?'Not available':n.toFixed(1)+'%'}
function trendData(os,profit=false){const hourly=range==='1',count=hourly?24:range==='7'?7:14,step=hourly?3600000:86400000,end=Number.isFinite(rangeBounds().end)?Math.min(Date.now(),rangeBounds().end-1):Date.now();return Array.from({length:count},(_,i)=>{const d=new Date(end-(count-1-i)*step),key=Math.floor((d.getTime()+21600000)/step),matches=os.filter(o=>Math.floor((new Date(o.created).getTime()+21600000)/step)===key),f=financeTotals(matches);return {label:hourly?d.toLocaleTimeString('en-BD',{hour:'numeric',hour12:true,timeZone:'Asia/Dhaka'}):d.toLocaleDateString('en-GB',{day:'numeric',month:'short',timeZone:'Asia/Dhaka'}),values:profit?[f.revenue,f.profit]:[matches.length]}})}
function lineVisual(data,names){const w=760,h=215,pad=30,vals=data.flatMap(x=>x.values).filter(x=>x!==null),min=Math.min(0,...vals),max=Math.max(1,...vals),y=v=>h-pad-(v-min)/(max-min)*(h-pad*2),x=i=>pad+i/Math.max(1,data.length-1)*(w-pad*2);let paths=names.map((name,s)=>{let path='',connected=false;data.forEach((d,i)=>{const v=d.values[s];if(v===null){connected=false;return}path+=(connected?' L':' M')+x(i).toFixed(2)+' '+y(v).toFixed(2);connected=true});return `<path d="${path}" fill="none" stroke="${chartColors[s]}" stroke-width="3.2" stroke-linecap="round" stroke-linejoin="round"/>${data.map((d,i)=>d.values[s]===null?'':`<circle cx="${x(i)}" cy="${y(d.values[s])}" r="3.4" fill="${chartColors[s]}"><title>${esc(name)} · ${esc(d.label)}: ${d.values[s].toLocaleString('en-BD')}</title></circle>`).join('')}`}).join('');return `<div class="visual-legend">${names.map((n,i)=>`<span><i style="background:${chartColors[i]}"></i>${esc(n)}</span>`).join('')}</div><div class="line-chart"><svg viewBox="0 0 ${w} ${h}" role="img" aria-label="${esc(names.join(' and '))} trend">${[0,.25,.5,.75,1].map(t=>`<line x1="${pad}" y1="${pad+t*(h-pad*2)}" x2="${w-pad}" y2="${pad+t*(h-pad*2)}" stroke="#e8eee5" stroke-dasharray="3 5"/>`).join('')}<line x1="${pad}" y1="${y(0)}" x2="${w-pad}" y2="${y(0)}" stroke="#d5decf"/>${paths}${data.filter((d,i)=>i===0||i===data.length-1||i%Math.ceil(data.length/6)===0).map(d=>{const i=data.indexOf(d);return `<text x="${x(i)}" y="${h-4}" text-anchor="middle" fill="#899282" font-size="10">${esc(d.label)}</text>`}).join('')}</svg></div>`}
function horizontalVisual(rows,unit='count',actions=false){const max=Math.max(1,...rows.map(r=>Math.abs(r.value||0)));return `<div class="horizontal-visual">${rows.map((r,i)=>`<${actions?'button':'div'} class="visual-bar-row" ${actions?`onclick="${r.action}"`:''}><span>${esc(r.label)}</span><div><i style="width:${Math.max(0,Math.abs(r.value||0)/max*100)}%;background:${r.value<0?'#d89180':chartColors[i%chartColors.length]}"></i></div><strong>${r.value==null?'Cost missing':unit==='money'?money(r.value):r.value}</strong></${actions?'button':'div'}>`).join('')||empty('No data in this period.')}</div>`}
function ringVisual(rows,label){const total=sumBy(rows,r=>r.value),active=rows.filter(r=>r.value>0);let from=0;const gradient=active.map((r,i)=>{const to=from+r.value/total*100,part=chartColors[i%chartColors.length]+' '+from+'% '+to+'%';from=to;return part}).join(',');return `<div class="ring-block"><div class="insight-ring" style="background:${total?'conic-gradient('+gradient+')':'#e7eee0'}"><div><strong>${total}</strong><small>${esc(label)}</small></div></div><div class="ring-legend">${active.map((r,i)=>`<div><i style="background:${chartColors[i%chartColors.length]}"></i><span>${esc(r.label)}</span><strong>${r.value}</strong><small>${ratio(r.value,total)}</small></div>`).join('')||'<p class="small muted">No data yet.</p>'}</div></div>`}
function workflowVisual(rows){return `<div class="journey">${rows.map((r,i)=>`<button class="journey-step" onclick="${r.action}"><span class="journey-number">0${i+1}</span><small>${esc(r.label)}</small><strong>${r.value}</strong><span class="journey-arrow">↗</span></button>`).join('')}</div>`}
function periodChange(current,previous){if(current==null||previous==null)return 'Comparison unavailable';if(previous===0)return current===0?'→ 0.0% · Previous: 0':'No previous data';const change=(current-previous)/Math.abs(previous)*100;return `${change>0?'↑':change<0?'↓':'→'} ${Math.abs(change).toFixed(1)}% · Previous: ${Number(previous.toFixed(1)).toLocaleString('en-BD')}`}
function previousOrders(){const b=rangeBounds();return !Number.isFinite(b.start)||!Number.isFinite(b.end)?null:visibleOrders().filter(o=>{const t=new Date(o.created).getTime();return t>=b.start-(b.end-b.start)&&t<b.start})}
function profitComparison(label){const before=previousOrders();if(!before)return 'All available history';const prev=before.filter(o=>confirmedStatus(o.status)),now=confirmedInRange(),f=financeTotals(prev),n=financeTotals(now),key={'Revenue':'revenue','Product cost':'cost','Discount given':'discount','Net profit':'profit','Profit margin':'margin'}[label];if(key)return periodChange(n[key],f[key]);if(label==='Confirmed orders')return periodChange(now.length,prev.length);if(label==='Purchase rate')return periodChange(Number(ratio(new Set(now.map(o=>o.customer)).size,visibleCustomers().length).replace('%','')),Number(ratio(new Set(prev.map(o=>o.customer)).size,visibleCustomers().length).replace('%','')));return ''}
function purchaseStats(os,cs){const connected=cs.filter(c=>c.call==='Connected'),ids=new Set(connected.map(c=>c.id)),buyers=new Set(os.filter(o=>confirmedStatus(o.status)&&ids.has(o.customer)).map(o=>o.customer));return {buyers:buyers.size,connected:connected.length,rate:connected.length?buyers.size/connected.length*100:0}}
function summaryTile(label,value,foot,action='',accent=false){const comparable=page==='profit'&&['Revenue','Product cost','Discount given','Net profit','Profit margin','Confirmed orders','Purchase rate'].includes(label),comparison=comparable?comparisonDisplay(comparisonNumbers(label)):null;return `<button class="card insight-tile ${accent?'accent-tile':''} ${label==='Net profit'?'metric-dark':''}" ${action?`onclick="${action}"`:''}><span class="tile-label">${esc(label)} ${action?ico('arrow'):''}</span><div class="metric-value-row"><strong>${value}</strong>${comparison?`<span class="change-badge change-${comparison.direction}">${esc(comparison.badge)}</span>`:''}</div>${comparison?`<small class="previous-line">Previous: <b>${esc(String(comparison.previous))}</b></small>`:''}<small class="metric-context">${esc(foot)}</small></button>`}

function dashboardView(){if(role==='Super Admin')return superView();const os=visibleOrders().filter(inRange),cs=visibleCustomers(),m=metricSet(os,cs),confirmed=os.filter(o=>confirmedStatus(o.status)),canFinance=financialAccess(),profits=confirmed.map(orderProfit),profit=profits.some(x=>x===null)?null:profits.reduce((s,x)=>s+x,0),sources=[...new Set(cs.filter(c=>c.agent).map(c=>c.source||'Other'))],statuses=[...new Set([...db.settings.statuses,...cs.map(c=>c.status)])],top=db.products.map(p=>({p,qty:confirmed.reduce((s,o)=>s+o.items.filter(x=>x.product===p.id).reduce((s,x)=>s+x.qty,0),0)})).filter(x=>x.qty).sort((a,b)=>b.qty-a.qty).slice(0,5),previous=range==='all'?null:visibleOrders().filter(o=>{const r=rangeBounds(),t=new Date(o.created).getTime();return t>=r.start-(r.end-r.start)&&t<r.start}),prev=previous?.filter(o=>confirmedStatus(o.status));const compare=(value,key)=>{if(!prev)return 'All available history';const old=key==='count'?prev.length:prev.reduce((s,o)=>s+orderTotal(o),0);return old?`${value>=old?'↑':'↓'} ${Math.abs((value-old)/old*100).toFixed(1)}% · previous ${key==='count'?old:money(old)}`:'No previous data'};return heading(role==='Agent'?'Your day, in flow.':'Every number. A clearer next step.',`Orders follow the selected period. Customer queue and response totals show the current snapshot.`,rangeSelect()+`<button class="dark" onclick="cart=[];nav('new')">${ico('plus')} New Order</button>`)+`<div class="stats dashboard-metrics" data-layout-title="Overall summary">${metricCard('Confirmed Orders',m.confirmed,compare(m.confirmed,'count'),"dashboardOrders('Confirmed')",'featured')}${metricCard('Revenue',money(m.revenue),compare(m.revenue,'revenue'),"dashboardOrders('Confirmed')")}${canFinance?metricCard('Profit',profit===null?'Cost missing':money(profit),'Estimate after recorded costs and fees',"nav('profit')",'metric-dark'):metricCard('Delivered',os.filter(o=>o.shipment==='Delivered').length,'Completed courier deliveries',"dashboardOrders('Delivered')")}${metricCard('Purchase Rate',percentage(purchaseStats(os,cs).rate),'Purchasing profiles in period / current profiles',"dashboardOrders('Confirmed')")}${[['Assigned',m.assigned,'Current assigned customer profiles',"dashboardCustomers('Assigned')"],['Pending Follow-up',m.pending,'Assigned profiles awaiting follow-up',"dashboardCustomers('pendingqueue')"],['Completed',m.completed,'Attempted profiles with a recorded result',"dashboardCustomers('completed')"],['Not Connected',m.notConnected,'Current call outcome',"dashboardCustomers('','Not Connected')"],['Connected',m.connected,'Current call outcome',"dashboardCustomers('','Connected')"],['Positive',m.positive,'Current customer response',"dashboardCustomers('','','Positive')"],['Intermediate',m.intermediate,'Current customer response',"dashboardCustomers('','','Intermediate')"],['Negative',m.negative,'Current customer response',"dashboardCustomers('','','Negative')"]].map(([l,n,f,a])=>metricCard(l,n,f,a)).join('')}</div><div class="dashboard-panels" data-layout-title="Workflow overview"><section class="card"><h2>Order Funnel</h2><p class="small muted">Current customer workflow</p><button class="breakdown" onclick="dashboardOrders('All')"><span>Total Orders</span><strong>${os.length}</strong><small>Selected reporting period</small></button>${[['Total customer profiles',cs.length,'All'],['Assigned',m.assigned,'Assigned'],['Attempted',m.attempted,'attempted'],['Confirmed customers',cs.filter(c=>confirmedStatus(c.status)).length,'Confirmed'],['Failed / no sale',cs.filter(c=>c.call&&!confirmedStatus(c.status)&&!pendingStatus(c.status)).length,'failed'],['Not attempted',cs.filter(c=>!c.call).length,'notattempted']].map(([label,n,key])=>`<button class="breakdown" onclick="openFunnel('${key}')"><span>${label}</span><strong>${n}</strong><div class="meter"><i style="width:${cs.length?n/cs.length*100:0}%;background:${key==='failed'?'#de6a5c':key==='notattempted'?'#eea24e':'#a6de5e'}"></i></div><small>${ratio(n,cs.length)} of profiles</small></button>`).join('')}</section><section class="card"><h2>Assigned Order Source</h2><p class="small muted">Current assignments by source</p><div class="mini-ring"><strong>${m.assigned}</strong><span>assigned customers</span></div>${sources.map((s,i)=>{const n=cs.filter(c=>c.agent&&c.source===s).length;return `<button class="breakdown" onclick="sourceQueue(${i})"><span>${esc(s)}</span><strong>${n} · ${ratio(n,m.assigned)}</strong><div class="meter"><i style="width:${m.assigned?n/m.assigned*100:0}%"></i></div></button>`}).join('')||empty('No assignments yet.')}</section><section class="card"><h2>Top Products</h2><p class="small muted">Units in confirmed orders · selected period</p>${top.map(({p,qty})=>`<button class="top-product" onclick="ordersForProduct('${p.id}')"><img src="${esc(p.image)}" alt=""><span><strong>${esc(p.name)}</strong><small>${esc(p.variant)}</small><div class="meter"><i style="width:${qty/top[0].qty*100}%"></i></div></span><b>${qty}</b></button>`).join('')||empty('No confirmed products in this period.')}</section><section class="card"><h2>Status Breakdown</h2><p class="small muted">Current follow-up statuses</p><div class="status-scroll">${statuses.map((s,i)=>{const n=cs.filter(c=>c.status===s).length;return `<button class="status-row" onclick="openStatus(${i})"><i class="status-dot" style="background:${esc(db.settings.statusColors?.[s]||'hsl('+i*37%360+' 45% 55%)')}"></i><span>${esc(s)}</span><div class="meter"><i style="width:${cs.length?n/cs.length*100:0}%"></i></div><strong>${n} <small>${ratio(n,cs.length)}</small></strong></button>`}).join('')}</div></section></div>${confirmedChart(os)}<div class="dashboard-grid section-gap"><section class="card"><h2>Courier Delivery Overview</h2>${['Not Booked','Booked','In Transit','Delivered','Returned','Partial Delivery','Cancelled'].map(s=>`<button class="status-row" onclick="dashboardOrders('${s}')"><span>${s}</span><strong>${os.filter(o=>o.shipment===s).length}</strong></button>`).join('')}</section><section class="card"><div class="row between"><h2>Recent Orders</h2><button onclick="nav('orders')">View all</button></div>${orderTable(os.slice(0,5),true)}</section></div>`}
function openAgentReport(id){reportAgentId=id;try{sessionStorage.setItem('jioflow.report.agent.'+(activeStoreId||'demo'),id)}catch{}reportSection='customers';reportFilter='All';reportSearch='';reportPage=1;nav('agentdetail')}
function agentReport(id){openAgentReport(id)}
function reportCustomers(id){return db.customers.filter(c=>c.agent===id)}
function reportOrders(id){return db.orders.filter(o=>o.agent===id&&inRange(o))}
function customerReportMatch(c,filter){if(filter==='All')return true;if(filter==='Assigned')return !!c.agent;if(filter==='Completed')return !!c.call&&!pendingStatus(c.status);if(filter==='Pending')return pendingStatus(c.status);if(filter==='Attempted')return !!c.call;if(filter==='Not attempted')return !c.call;if(filter==='Overdue')return !!c.callback&&new Date(c.callback)<=new Date();if(filter==='Confirmed')return confirmedStatus(c.status);if(['Connected','Not Connected'].includes(filter))return c.call===filter;if(['Positive','Intermediate','Negative'].includes(filter))return c.response===filter;return c.status===filter}
function filteredReportCustomers(id,filter=reportFilter){return reportCustomers(id).filter(c=>customerReportMatch(c,filter)).filter(c=>!reportSearch||[c.name,c.phone,c.address].join(' ').toLowerCase().includes(reportSearch.toLowerCase()))}
function filteredReportOrders(id,filter=reportFilter){return reportOrders(id).filter(o=>filter==='All'||(filter==='Confirmed'?confirmedStatus(o.status):o.status===filter||o.shipment===filter)).filter(o=>!reportSearch||[o.id,customer(o.customer)?.name,customer(o.customer)?.phone].join(' ').toLowerCase().includes(reportSearch.toLowerCase()))}
function selectReportFilter(filter,section){reportFilter=filter;reportSection=section;reportPage=1;reportSearch='';render()}
function openAgentMetric(id,filter,section='customers'){openAgentReport(id);selectReportFilter(filter,section)}
function agentReportsView(){if(role==='Agent'||role==='Manager'&&!permitted('profit'))return heading('Agent Reports','Your administrator has not enabled report access.');const users=db.agents.filter(a=>!a.archived&&(a.role||'Agent')==='Agent'),ids=new Set(users.map(a=>a.id)),cs=db.customers.filter(c=>ids.has(c.agent)),os=liveOrders().filter(inRange).filter(o=>ids.has(o.agent)),m=metricSet(os,cs),p=purchaseStats(os,cs),active=new Set((db.sessions||[]).filter(s=>s.status==='Approved'&&new Date(s.lastSeen)>new Date(Date.now()-15*60000)).map(s=>s.user));return heading('Agent Reports','Overall performance, purchase rates and the records behind every number.',rangeSelect())+`<div class="stats report-overview">${summaryTile('Total Agents',users.length,'Accounts in this workspace')}${summaryTile('Recently online',users.filter(a=>active.has(a.id)).length,'Demo sessions active within 15 minutes')}${summaryTile('Assigned',m.assigned,'Current customer assignments')}${summaryTile('Confirmed',m.confirmed,'Orders in selected period',"dashboardOrders('Confirmed')",true)}${summaryTile('Revenue',money(m.revenue),'Confirmed orders in selected period',"dashboardOrders('Confirmed')")}${summaryTile('Purchase rate',percentage(p.rate),`${p.buyers} purchasing / ${p.completed??p.connected} completed profiles`)}</div><div class="insight-grid"><section class="card" data-layout-title="Orders by Agent"><h2>Orders by Agent</h2><p class="small muted">Current assigned profiles · all Agents included</p>${ringVisual(users.map(a=>({label:a.name,value:cs.filter(c=>c.agent===a.id).length})),'assigned')}</section><section class="card purchase-panel" data-layout-title="Overall purchase rate"><span class="eyebrow">OVERALL PURCHASE RATE</span><strong class="purchase-number">${percentage(p.rate)}</strong><p>${p.buyers} purchasing customers out of ${p.connected} connected profiles.</p><div class="meter"><i style="width:${p.rate}%"></i></div><p class="small muted">Unique connected profiles with a confirmed order in the selected period / current connected profiles. One customer is counted once.</p><div class="mini-stats"><span><b>${m.completed}</b> Completed</span><span><b>${m.pending}</b> Pending</span><span><b>${cs.filter(c=>customerReportMatch(c,'Overdue')).length}</b> Overdue</span></div></section></div><div class="insight-grid"><section class="card" data-layout-title="Work by Agent"><h2>Assigned work by Agent</h2>${horizontalVisual(users.map(a=>({label:a.name,value:cs.filter(c=>c.agent===a.id).length,action:`openAgentMetric('${a.id}','Assigned')`})),'count',true)}</section><section class="card" data-layout-title="Team outcomes"><h2>Team outcomes</h2>${ringVisual([{label:'Completed',value:m.completed},{label:'Pending',value:m.pending},{label:'Other',value:Math.max(0,cs.length-m.completed-m.pending)}],'profiles')}</section></div><section class="card" data-layout-title="Agent report list"><h2>All Agents</h2><p class="small muted">Click a name for the full report, or a number for the matching records.</p><div class="table-wrap"><table><thead><tr><th>Agent / User Code</th><th>Assigned</th><th>Completed</th><th>Pending</th><th>Confirmed</th><th>Purchase rate</th><th>Connected</th><th>Overdue</th><th>Cancelled</th><th>Delivered</th><th>Returned</th><th>Revenue</th><th></th></tr></thead><tbody>${users.map(a=>{const ac=cs.filter(c=>c.agent===a.id),ao=os.filter(o=>o.agent===a.id),n=metricSet(ao,ac),r=purchaseStats(ao,ac),cell=(value,filter,section='customers')=>`<td><button class="link report-number" onclick="openAgentMetric('${a.id}','${filter}','${section}')">${value}</button></td>`;return `<tr><td><button class="person-link" onclick="openAgentReport('${a.id}')"><span class="avatar">${initials(a.name)}</span><span><strong>${esc(a.name)}</strong><small>${esc(userCode(a))}</small><small>${esc(a.email)}</small></span></button></td>${cell(n.assigned,'Assigned')}${cell(n.completed,'Completed')}${cell(n.pending,'Pending')}${cell(n.confirmed,'Confirmed','orders')}<td><strong>${percentage(r.rate)}</strong><small>${r.buyers} / ${r.connected} connected</small></td>${cell(n.connected,'Connected')}${cell(ac.filter(c=>customerReportMatch(c,'Overdue')).length,'Overdue')}${cell(ac.filter(c=>c.status==='Cancelled').length,'Cancelled')}${cell(ao.filter(o=>o.shipment==='Delivered').length,'Delivered','orders')}${cell(ao.filter(o=>o.shipment==='Returned').length,'Returned','orders')}${cell(money(n.revenue),'Confirmed','orders')}<td><button onclick="openAgentReport('${a.id}')">Full report ↗</button></td></tr>`}).join('')||'<tr><td colspan="13">No Agents yet. Add accounts in Users.</td></tr>'}</tbody></table></div></section>`}

function agentDetailView(){const a=agent(reportAgentId);if(!a||role==='Agent'&&a.id!==agentId||role==='Manager'&&!permitted('profit'))return heading('Report unavailable','Choose an authorized user from Agent Reports.');const cs=reportCustomers(a.id),os=reportOrders(a.id),m=metricSet(os.filter(o=>o.status!=='Imported'),cs),customerFilters=['All','Assigned','Attempted','Not attempted','Completed','Pending','Confirmed','Cancelled','Connected','Not Connected','Positive','Intermediate','Negative','Overdue'],orderFilters=['All','Pending','Confirmed','Cancelled','Booked','In Transit','Delivered','Returned','Partial Delivery','Imported'];const customerRows=filteredReportCustomers(a.id),orderRows=filteredReportOrders(a.id),shown=reportSection==='customers'?customerRows:orderRows,total=shown.length;return heading(esc(a.name)+' · Full report','All totals and the records behind them, in one place.',`<button onclick="nav('agentreports')">← All Agent reports</button>${rangeSelect()}`)+`<section class="person-banner" data-layout-title="User profile"><span class="avatar">${initials(a.name)}</span><div><h2>${esc(a.name)}</h2><p>${esc(a.email)} · ${esc(userCode(a))}</p><span class="badge">${esc(a.role||'Agent')}</span> ${badge(a.active?'Active':'Inactive')}</div><div class="person-banner-note">Customer counts show current assignments.<br>Order counts use the selected period.</div></section><div class="report-summary-row" data-layout-title="User summary">${[['Assigned',cs.length,'customers'],['Completed',cs.filter(c=>customerReportMatch(c,'Completed')).length,'customers'],['Pending',cs.filter(c=>customerReportMatch(c,'Pending')).length,'customers'],['Confirmed',os.filter(o=>confirmedStatus(o.status)).length,'orders'],['Cancelled',cs.filter(c=>c.status==='Cancelled').length,'customers'],['Delivered',os.filter(o=>o.shipment==='Delivered').length,'orders'],['Returned',os.filter(o=>o.shipment==='Returned').length,'orders']].map(([l,n,section])=>`<button class="card report-summary ${reportFilter===l&&reportSection===section?'selected':''}" onclick="selectReportFilter('${l}','${section}')"><small>${l}</small><strong>${n}</strong><span>${section==='customers'?'customers':'orders'} ↗</span></button>`).join('')}</div><div class="insight-grid"><section class="card" data-layout-title="User outcome chart"><h2>Customer outcomes</h2>${horizontalVisual(['Completed','Pending','Cancelled','Connected','Not Connected','Positive','Intermediate','Negative'].map(s=>({label:s,value:cs.filter(c=>customerReportMatch(c,s)).length,action:`selectReportFilter('${s}','customers')`})),'count',true)}</section><section class="card" data-layout-title="User order chart"><h2>Order & delivery progress</h2>${horizontalVisual(['Confirmed','Booked','In Transit','Delivered','Returned','Cancelled'].map(s=>({label:s,value:os.filter(o=>s==='Confirmed'?confirmedStatus(o.status):o.shipment===s||o.status===s).length,action:`selectReportFilter('${s}','orders')`})),'count',true)}<div class="notice">${money(m.revenue)} confirmed revenue · ${percentage(purchaseStats(os,cs).rate)} purchase rate · purchasing / connected profiles</div></section></div><section class="card report-records" data-layout-title="Customer & order records"><div class="section-title"><div><h2>${reportSection==='customers'?'Customer follow-up details':'Order & delivery details'}</h2><p>${total} matching ${reportSection} · ${esc(reportFilter)}</p></div><div class="tabs"><button class="${reportSection==='customers'?'active':''}" onclick="selectReportFilter('All','customers')">Customer Follow-up</button><button class="${reportSection==='orders'?'active':''}" onclick="selectReportFilter('All','orders')">Orders & Delivery</button></div></div><div class="toolbar"><select aria-label="Report status filter" onchange="selectReportFilter(this.value,reportSection)">${options(reportSection==='customers'?customerFilters:orderFilters,reportFilter)}</select><input aria-label="Search report records" placeholder="Search customer, phone or order..." value="${esc(reportSearch)}" onchange="reportSearch=this.value;reportPage=1;render()"></div>${reportSection==='customers'?reportCustomerTable(customerRows.slice((reportPage-1)*rowsPerPage,reportPage*rowsPerPage)):orderTable(orderRows.slice((reportPage-1)*rowsPerPage,reportPage*rowsPerPage))}<div class="pagination"><span>${total} records</span><div class="row"><button ${reportPage<=1?'disabled':''} onclick="reportPage--;render()">Previous</button><span>${reportPage} / ${Math.max(1,Math.ceil(total/rowsPerPage))}</span><button ${reportPage*rowsPerPage>=total?'disabled':''} onclick="reportPage++;render()">Next</button></div></div></section>`}
function reportCustomerTable(cs){return cs.length?`<div class="table-wrap"><table><thead><tr><th>Customer</th><th>Status</th><th>Call / response</th><th>Latest note / reason</th><th>Next call</th><th>Orders</th><th></th></tr></thead><tbody>${cs.map(c=>`<tr><td><button class="link" onclick="showCustomer('${c.id}')"><strong>${esc(c.name)}</strong><small>${esc(c.phone)}</small></button></td><td>${badge(c.status)}</td><td>${esc(c.call||'Not attempted')}<small>${esc(c.response||'—')}</small></td><td class="note-cell">${esc(c.notes?.[0]?.text||'No note recorded')}<small>${esc(c.tag||'')}</small></td><td>${c.callback?esc(c.callback.replace('T',' ')):'—'}</td><td>${db.orders.filter(o=>o.customer===c.id).length}</td><td><button onclick="showCustomer('${c.id}')">Full profile ${ico('arrow')}</button></td></tr>`).join('')}</tbody></table></div>`:empty('No customer records match this section.')}
function productFinanceRows(os){return db.products.map(p=>{let qty=0,revenue=0,cost=0,profit=0,missing=false;os.forEach(o=>{const items=o.items.filter(x=>x.product===p.id),gross=sumBy(o.items,x=>x.qty*x.price),g=sumBy(items,x=>x.qty*x.price);if(!items.length)return;qty+=sumBy(items,x=>x.qty);const weight=gross?g/gross:sumBy(items,x=>x.qty)/Math.max(1,sumBy(o.items,x=>x.qty)),f=financeTotals([o]);revenue+=f.revenue*weight;if(items.some(x=>(x.cost??p.cost)==null))missing=true;cost+=sumBy(items,x=>x.qty*(x.cost??p.cost??0));profit+=f.revenue*weight-sumBy(items,x=>x.qty*(x.cost??p.cost??0))-f.fees*weight});return {p,qty,revenue,cost:missing?null:cost,profit:missing?null:profit,margin:missing||!revenue?null:profit/revenue*100}}).filter(r=>r.qty).sort((a,b)=>(b.profit??-Infinity)-(a.profit??-Infinity))}
function profitView(){if(!financialAccess())return heading('Profit','Your administrator has not enabled financial access.');const os=confirmedInRange(),f=financeTotals(os),products=productFinanceRows(os),sources=[...new Set(os.map(o=>o.source||'Other'))],units=sumBy(os,o=>sumBy(o.items,x=>x.qty)),agents=new Set(os.map(o=>o.agent).filter(Boolean));return heading('Profit Management','Revenue, product costs, discounts and net profit from confirmed orders.',rangeSelect())+`<div class="stats profit-summary">${summaryTile('Revenue',money(f.revenue),'Confirmed order value',"profitDetail('all','')",true)}${summaryTile('Product cost',f.cost===null?'Cost missing':money(f.cost),'Recorded item costs',"profitDetail('all','')")}${summaryTile('Discount given',money(f.discount),'Already deducted from revenue',"profitDetail('all','')")}${summaryTile('Net profit',f.profit===null?'Cost missing':money(f.profit),'Estimate after costs and fees',"profitDetail('all','')")}${summaryTile('Profit margin',percentage(f.margin),'Net profit / confirmed revenue',"profitDetail('all','')")}${summaryTile('Confirmed orders',os.length,'Click for order details',"profitDetail('all','')")}${summaryTile('Purchase rate',ratio(new Set(os.map(o=>o.customer)).size,visibleCustomers().length),'Purchasing profiles / current profiles',"profitDetail('all','')")}</div><section class="card" data-layout-title="Revenue and profit trend"><div class="section-title"><div><h2>Revenue & profit over time</h2><p>${range==='1'?'Hourly · Bangladesh time':'Latest 14 days in selected period'}</p></div></div>${lineVisual(trendData(os,true),['Revenue','Net profit'])}${f.profit===null?'<p class="small muted">Profit points with missing item costs are omitted, not estimated as zero.</p>':''}</section><div class="insight-grid main-insights"><section class="card" data-layout-title="Profit by source"><div class="section-title"><div><h2>Profit by source</h2><p>Negative contributions stay visible</p></div></div>${horizontalVisual(sources.map(s=>({label:s,value:financeTotals(os.filter(o=>o.source===s)).profit,action:`profitDetail('source',${esc(JSON.stringify(s))})`})),'money',true)}</section><section class="card" data-layout-title="Profit snapshot"><span class="eyebrow">PROFIT SNAPSHOT</span><h2>A few numbers that matter</h2><div class="snapshot-metrics"><div><strong>${f.profit===null?'Cost missing':money(os.length?f.profit/os.length:0)}</strong><small>Average profit / order</small></div><div><strong>${units}</strong><small>Units sold</small></div><div><strong>${agents.size}</strong><small>Contributing Agents</small></div><div><strong>${money(f.fees)}</strong><small>Courier & other fees</small></div></div></section></div><section class="card" data-layout-title="Profit by product"><h2>Profit by product</h2><p class="small muted">Order discounts, delivery income and fees are allocated proportionally across items.</p><div class="table-wrap"><table><thead><tr><th>Product</th><th>Units</th><th>Revenue</th><th>Cost</th><th>Net profit</th><th>Margin</th><th></th></tr></thead><tbody>${products.map(r=>`<tr><td><div class="row nowrap"><img class="table-product-img" src="${esc(r.p.image)}" alt=""><span><strong>${esc(r.p.name)}</strong><small>${esc(r.p.sku)}</small></span></div></td><td>${r.qty}</td><td>${money(r.revenue)}</td><td>${r.cost===null?'Missing':money(r.cost)}</td><td>${r.profit===null?'Cost missing':money(r.profit)}</td><td>${percentage(r.margin)}</td><td><button onclick="profitDetail('product','${r.p.id}')">Details</button></td></tr>`).join('')||'<tr><td colspan="7">No confirmed products in this period.</td></tr>'}</tbody></table></div></section><section class="card" data-layout-title="Profit by Agent"><h2>Profit by Agent</h2><div class="table-wrap"><table><thead><tr><th>Agent</th><th>Orders</th><th>Revenue</th><th>Cost</th><th>Discount</th><th>Net profit</th><th>Margin</th><th></th></tr></thead><tbody>${[...new Set(os.map(o=>o.agent))].map(id=>{const as=os.filter(o=>o.agent===id),n=financeTotals(as);return `<tr><td><button class="link" onclick="${id?`openAgentReport('${id}')`:"profitDetail('agent','')"}">${esc(agentName(id))}</button></td><td>${as.length}</td><td>${money(n.revenue)}</td><td>${n.cost===null?'Missing':money(n.cost)}</td><td>${money(n.discount)}</td><td>${n.profit===null?'Cost missing':money(n.profit)}</td><td>${percentage(n.margin)}</td><td><button onclick="profitDetail('agent','${id}')">Orders</button></td></tr>`}).join('')||'<tr><td colspan="8">No confirmed orders yet.</td></tr>'}</tbody></table></div></section><section class="card" data-layout-title="Confirmed order profit detail"><h2>Confirmed orders · profit detail</h2>${profitOrderTable(os)}</section>`}
function profitOrderTable(os){return os.length?`<div class="table-wrap"><table><thead><tr><th>Order / Date</th><th>Customer</th><th>Agent / Source</th><th>Revenue</th><th>Discount</th><th>Delivery</th><th>Cost</th><th>Fees</th><th>Net profit</th><th>Margin</th><th></th></tr></thead><tbody>${os.map(o=>{const n=financeTotals([o]);return `<tr><td><button class="link" onclick="showOrder('${o.id}')">${esc(o.id)}<small>${date(o.created)}</small></button></td><td>${esc(customer(o.customer)?.name)}</td><td>${esc(agentName(o.agent))}<small>${esc(o.source)}</small></td><td>${money(n.revenue)}</td><td>${money(n.discount)}</td><td>${money(n.delivery)}</td><td>${n.cost===null?'Missing':money(n.cost)}</td><td>${money(n.fees)}</td><td>${n.profit===null?'Cost missing':money(n.profit)}</td><td>${percentage(n.margin)}</td><td><button onclick="financeForm('${o.id}')">Edit costs</button></td></tr>`}).join('')}</tbody></table></div>`:empty('No confirmed orders match this report.')}
function profitDetail(type,key){if(!financialAccess())return;const os=confirmedInRange().filter(o=>type==='all'||type==='agent'&&o.agent===key||type==='source'&&o.source===key||type==='product'&&o.items.some(x=>x.product===key));modal('Profit details','Selected period · '+(type==='all'?'All confirmed orders':type==='product'?product(key)?.name:type==='agent'?agentName(key):key),profitOrderTable(os))}

// Compact overviews share the same scoped records as their lists.
let followAgentFilter='',followSourceFilter='',followCallFilter='',followResponseFilter='',orderSourceFilter='',orderTagFilter='',orderCallFilter='',orderResponseFilter='';
function resetFollowFilters(){followAgentFilter=followSourceFilter=followCallFilter=followResponseFilter='';render()}
function matchesFollowupFilters(c){return (!followAgentFilter||c.agent===followAgentFilter)&&(!followSourceFilter||c.source===followSourceFilter)&&(!followCallFilter||c.call===followCallFilter)&&(!followResponseFilter||c.response===followResponseFilter)}
function selectOrderOverview(status){subtab=status;query='';pageNo=1;selected.clear();render()}
function selectFollowOverview(status){subtab=status;query='';pageNo=1;selected.clear();window.funnelFilter='';window.callFilter='';window.responseFilter='';render()}
function overviewTile(label,value,all,action,accent=false){return summaryTile(label,value,`${ratio(value,all)} of ${all} ${page==='orders'?'orders':'profiles'}`,action,accent)}
function orderOverview(){const os=visibleOrders().filter(inRange).filter(o=>(!window.orderAgentFilter||o.agent===window.orderAgentFilter)&&(!window.courierFilter||o.courier===window.courierFilter)&&orderExtraMatch(o)),n=os.length,confirmed=os.filter(o=>confirmedStatus(o.status));return `<div class="stats section-overview" data-layout-title="Order overview">${summaryTile('Total orders',n,'Selected reporting period',"selectOrderOverview('All')",true)}${overviewTile('Pending',os.filter(o=>o.status==='Pending').length,n,"selectOrderOverview('Pending')")}${overviewTile('Confirmed',confirmed.length,n,"selectOrderOverview('Confirmed')")}${overviewTile('Ready to book',os.filter(o=>confirmedStatus(o.status)&&o.shipment==='Not Booked').length,n,"selectOrderOverview('Ready to Book')")}${overviewTile('Booked',os.filter(o=>o.shipment==='Booked').length,n,"selectOrderOverview('Booked')")}${overviewTile('In transit',os.filter(o=>o.shipment==='In Transit').length,n,"selectOrderOverview('In Transit')")}${overviewTile('Delivered',os.filter(o=>o.shipment==='Delivered').length,n,"selectOrderOverview('Delivered')")}${overviewTile('Returned',os.filter(o=>o.shipment==='Returned').length,n,"selectOrderOverview('Returned')")}${overviewTile('Partial delivery',os.filter(o=>o.shipment==='Partial Delivery').length,n,"selectOrderOverview('Partial Delivery')")}${overviewTile('Cancelled',os.filter(o=>o.status==='Cancelled'||o.shipment==='Cancelled').length,n,"selectOrderOverview('Cancelled')")}${overviewTile('Imported',os.filter(o=>o.status==='Imported').length,n,"selectOrderOverview('Imported')")}${summaryTile('Confirmed revenue',money(sumBy(confirmed,orderTotal)),'Confirmed orders · selected period',"selectOrderOverview('Confirmed')")}</div><details class="card overview-charts" data-layout-title="Order charts"><summary>Order & delivery charts</summary><div class="insight-grid"><section><h2>Order outcomes</h2>${ringVisual(['Pending','Confirmed','Cancelled','Imported'].map(status=>({label:status,value:os.filter(o=>status==='Confirmed'?confirmedStatus(o.status):o.status===status).length})),'orders')}</section><section><h2>Courier progress</h2>${horizontalVisual(['Not Booked','Booked','In Transit','Delivered','Returned','Partial Delivery','Cancelled'].map(status=>({label:status,value:os.filter(o=>o.shipment===status).length,action:`selectOrderOverview('${status}')`})),'count',true)}</section></div></details>`}
function followOverview(){const cs=visibleCustomers().filter(c=>(page!=='permanent'||c.permanent)&&matchesFollowupFilters(c)),n=cs.length;return `<div class="stats section-overview" data-layout-title="Follow-up overview">${overviewTile('All customers',n,n,"selectFollowOverview('All')",true)}${overviewTile('Unassigned',cs.filter(c=>!c.agent).length,n,"selectFollowOverview('Unassigned')")}${overviewTile('Assigned',cs.filter(c=>c.agent).length,n,"selectFollowOverview('Assigned')")}${overviewTile('Completed',cs.filter(c=>customerReportMatch(c,'Completed')).length,n,"selectFollowOverview('completed')")}${overviewTile('Pending follow-up',cs.filter(c=>c.agent&&pendingStatus(c.status)).length,n,"selectFollowOverview('pendingqueue')")}${overviewTile('Permanent clients',cs.filter(c=>c.permanent).length,n,"selectFollowOverview('Permanent')")}${overviewTile('Confirmed customers',cs.filter(c=>confirmedStatus(c.status)).length,n,"selectFollowOverview('Confirmed')")}${overviewTile('Cancelled',cs.filter(c=>c.status==='Cancelled').length,n,"selectFollowOverview('Cancelled')")}${overviewTile('Connected',cs.filter(c=>c.call==='Connected').length,n,"setFollowCall('Connected')")}${overviewTile('Not connected',cs.filter(c=>c.call==='Not Connected').length,n,"setFollowCall('Not Connected')")}${overviewTile('Overdue callbacks',cs.filter(c=>customerReportMatch(c,'Overdue')).length,n,"selectFollowOverview('Due Today')")}${overviewTile('Never attempted',cs.filter(c=>!c.call).length,n,"setFollowUnattempted()")}</div><details class="card overview-charts" data-layout-title="Follow-up charts"><summary>Follow-up charts & status breakdown</summary><div class="insight-grid"><section><h2>Call progress</h2>${ringVisual([{label:'Connected',value:cs.filter(c=>c.call==='Connected').length},{label:'Not connected',value:cs.filter(c=>c.call==='Not Connected').length},{label:'Not attempted',value:cs.filter(c=>!c.call).length}],'profiles')}</section><section><h2>Latest customer statuses</h2>${horizontalVisual(db.settings.statuses.map(status=>({label:status,value:cs.filter(c=>c.status===status).length,action:`selectFollowOverview(${esc(JSON.stringify(status))})`})),'count',true)}</section></div></details>`}
function setFollowCall(call){selectFollowOverview('All');followCallFilter=call;render()}
function setFollowUnattempted(){selectFollowOverview('All');window.funnelFilter='notattempted';render()}
function followFilterBar(){return `<details class="card filter-disclosure" data-layout-title="Follow-up filters"><summary>Filter by Agent, source, call & response</summary><div class="filter-panel">${role!=='Agent'?`<label>Agent<select aria-label="Follow-up Agent" onchange="followAgentFilter=this.value;pageNo=1;render()"><option value="">All Agents</option>${db.agents.filter(a=>!a.archived).map(a=>`<option value="${a.id}" ${followAgentFilter===a.id?'selected':''}>${esc(a.name)}</option>`).join('')}</select></label>`:''}<label>Source<select aria-label="Follow-up source" onchange="followSourceFilter=this.value;pageNo=1;render()"><option value="">All sources</option>${options([...new Set(visibleCustomers().map(c=>c.source))].filter(Boolean),followSourceFilter)}</select></label><label>Call status<select aria-label="Follow-up call status" onchange="followCallFilter=this.value;pageNo=1;render()"><option value="">All call statuses</option>${options(['Connected','Not Connected'],followCallFilter)}</select></label><label>Response<select aria-label="Follow-up response" onchange="followResponseFilter=this.value;pageNo=1;render()"><option value="">All responses</option>${options(['Positive','Intermediate','Negative'],followResponseFilter)}</select></label><button onclick="resetFollowFilters()">Clear filters</button></div></details>`}
function orderExtraMatch(o){const c=customer(o.customer)||{};return (!orderSourceFilter||o.source===orderSourceFilter)&&(!orderTagFilter||c.tag===orderTagFilter)&&(!orderCallFilter||c.call===orderCallFilter)&&(!orderResponseFilter||c.response===orderResponseFilter)}
const originalFilteredOrders=filteredOrders;
filteredOrders=function(){return originalFilteredOrders().filter(inRange).filter(orderExtraMatch)};
const originalOrdersView=ordersView;
ordersView=function(){const html=originalOrdersView(),at=html.indexOf('<section class="card">');return html.slice(0,at)+orderOverview()+html.slice(at)};
const originalCustomersView=customersView;
customersView=function(){const html=originalCustomersView(),at=html.indexOf('<section class="card">');return html.slice(0,at)+followOverview()+followFilterBar()+html.slice(at)};
const originalMetricCard=metricCard;
metricCard=function(label,value,foot,action='',cls=''){if(page==='dashboard'&&typeof value==='number'&&['Assigned','Pending Follow-up','Completed','Not Connected','Connected','Positive','Intermediate','Negative'].includes(label))foot=ratio(value,visibleCustomers().length)+' of current profiles · '+foot;return originalMetricCard(label,value,foot,action,cls)};
function userCode(a){return a?.code||'JF-'+String(db.agents.findIndex(x=>x.id===a?.id)+1).padStart(4,'0')}
function workflowOptions(c){return c?.permanent?[...new Set([...db.settings.statuses,...(db.settings.permanentStatuses||[])])]:db.settings.statuses}
function editWorkflowOption(type,index){const label=db.settings[type]?.[index]||'';modal('Edit workflow option','Changes update matching customer records.',`<form onsubmit="saveWorkflowOption(event,'${type}',${index})">${field('Name','label',label,'text','required maxlength="60"')}${type==='statuses'?field('Color','color',db.settings.statusColors?.[label]||'#6e9c45','color'):''}${modalFooter('Save option')}</form>`)}
function saveWorkflowOption(e,type,index){e.preventDefault();if(role!=='Admin'&&!(role==='Manager'&&permitted('settings')))return;const f=new FormData(e.target),old=db.settings[type][index],label=String(f.get('label')).trim();if(!label||db.settings[type].some((x,i)=>i!==index&&x.toLowerCase()===label.toLowerCase()))return toast('Use a unique option name.');db.settings[type][index]=label;db.customers.forEach(c=>{const key=type==='tags'?'tag':'status';if(c[key]===old)c[key]=label});if(type==='statuses'){db.orders.forEach(o=>{if(o.status===old)o.status=label});db.settings.statusColors||={};db.settings.statusColors[label]=f.get('color');if(db.settings.confirmStatus===old)db.settings.confirmStatus=label;if(db.settings.scheduleStatus===old)db.settings.scheduleStatus=label}save();closeModal();render()}
async function removeWorkflowOption(type,index){if(role!=='Admin'&&!(role==='Manager'&&permitted('settings')))return;const label=db.settings[type][index],key=type==='tags'?'tag':'status';if(db.customers.some(c=>c[key]===label)||type==='statuses'&&(db.orders.some(o=>o.status===label)||label===(db.settings.confirmStatus||'Confirmed')||label===(db.settings.scheduleStatus||'Call Back')))return toast('This option is in use. Rename it or move its records first.');if(!await askConfirm('Remove option','Remove '+label+' from future selections?'))return;db.settings[type].splice(index,1);save();render()}
function extraWorkflowSettings(){const types=[['statuses','Order & follow-up statuses'],['permanentStatuses','Permanent client statuses'],['tags','Unassignment tags']];return `<section class="card" data-layout-title="Workflow customization"><h2>Workflow customization</h2><p class="small muted">Edit labels and colors, choose confirmation and callback defaults, and manage permanent-client statuses.</p>${types.map(([type,title])=>`<h3 class="section-gap">${title}</h3>${(db.settings[type]||[]).map((label,i)=>`<div class="option-management"><span>${esc(label)}</span><button onclick="editWorkflowOption('${type}',${i})">Edit</button><button class="ghost" onclick="removeWorkflowOption('${type}',${i})">Remove</button></div>`).join('')||'<p class="small muted">No separate statuses yet.</p>'}<button onclick="db.settings.${type}||=[];addOption('${type}')">+ Add option</button>`).join('')}<form class="section-gap" onsubmit="event.preventDefault();db.settings.confirmStatus=this.elements.confirm.value;db.settings.scheduleStatus=this.elements.schedule.value;save();render();toast('Workflow defaults saved')">${selectField('Confirmed-sale status','confirm',db.settings.statuses,db.settings.confirmStatus||'Confirmed')}${selectField('Callback status (requires a date/time)','schedule',db.settings.statuses,db.settings.scheduleStatus||'Call Back')}<button class="primary">Save workflow defaults</button></form></section>`}
let performerRanking='Confirmed orders';
function performerData(){const os=visibleOrders().filter(inRange),users=db.agents.filter(a=>!a.archived&&(a.role||'Agent')==='Agent'),confirmed=os.filter(o=>confirmedStatus(o.status)),teamRevenue=financeTotals(confirmed).revenue;return users.map(a=>{const cs=db.customers.filter(c=>c.agent===a.id),orders=os.filter(o=>o.agent===a.id),sales=orders.filter(o=>confirmedStatus(o.status)),f=financeTotals(sales),m=metricSet(orders,cs),p=purchaseStats(orders,cs),delivered=orders.filter(o=>o.shipment==='Delivered').length,returned=orders.filter(o=>o.shipment==='Returned').length;return {a,cs,orders,sales,f,m,p,delivered,returned,completion:cs.length?m.completed/cs.length*100:0,share:teamRevenue?f.revenue/teamRevenue*100:0}}).filter(r=>r.sales.length).sort((a,b)=>performerRanking==='Revenue'?b.f.revenue-a.f.revenue:performerRanking==='Net profit'?(b.f.profit??-Infinity)-(a.f.profit??-Infinity):performerRanking==='Purchase rate'?b.p.rate-a.p.rate:b.sales.length-a.sales.length||b.f.revenue-a.f.revenue).slice(0,3)}
function heroesPanel(){if(!financialAccess()&&performerRanking==='Net profit')performerRanking='Confirmed orders';const leaders=performerData();return `<section class="card performers-section" data-layout-title="Top performers"><div class="section-title"><div><span class="eyebrow">TEAM PERFORMANCE AT A GLANCE</span><h2>Top performers</h2><p>Overall summary · click a performer for the full detailed report</p></div><label class="performer-sort">Rank by<select aria-label="Rank top performers" onchange="performerRanking=this.value;render()">${options(['Confirmed orders','Revenue',...(financialAccess()?['Net profit']:[]),'Purchase rate'],performerRanking)}</select></label></div><div class="performer-grid compact-performers">${leaders.map((r,i)=>`<button class="performer-card compact-performer" onclick="openAgentReport('${r.a.id}')" aria-label="Open full report for ${esc(r.a.name)}"><div class="performer-person"><span class="rank-medal">#${i+1}</span><span class="avatar">${initials(r.a.name)}</span><div><h3>${esc(r.a.name)}</h3><small>${esc(userCode(r.a))}</small></div><span class="performer-open">↗</span></div><div class="performer-main"><div><small>Confirmed orders</small><strong>${r.sales.length}</strong></div><div><small>Revenue</small><strong>${money(r.f.revenue)}</strong></div></div>${financialAccess()?`<div class="performer-profit"><span>Net profit</span><strong>${r.f.profit===null?'Cost missing':money(r.f.profit)}</strong></div>`:''}<div class="performer-compact-footer"><span>Purchase rate <b>${percentage(r.p.rate)}</b></span><span>Team revenue contribution <b>${percentage(r.share)}</b></span></div><span class="performer-detail-link">Full details ${ico('arrow')}</span></button>`).join('')||empty('Confirmed orders will reveal your top performers.')}</div></section>`}

const originalSettingsView=settingsView;
settingsView=function(){let html=originalSettingsView();if(role==='Super Admin')return html;const start=html.indexOf('<section class="card"><h2>Custom follow-up statuses</h2>'),end=html.indexOf('<section class="card"><h2>Demo data</h2>',start);if(start>=0&&end>start)html=html.slice(0,start)+extraWorkflowSettings()+html.slice(end);else html+=extraWorkflowSettings();return html+`<section class="card section-gap" data-layout-title="Performance celebration"><h2>Team recognition</h2><p>Show the top three performers on the Dashboard for the selected reporting period.</p><label class="permission"><input type="checkbox" ${db.settings.hero?'checked':''} onchange="db.settings.hero=this.checked;save()"> Show Top Performers</label><button onclick="modal('Top performers','Preview · selected reporting period',heroesPanel())">Preview</button></section>`};
const originalDashboardOverview=dashboardView;
dashboardView=function(){const html=originalDashboardOverview(),at=html.indexOf('<div class="dashboard-panels"');const view=role==='Super Admin'?html:html.slice(0,at)+dashboardActionCards()+html.slice(at);return view+(role!=='Super Admin'&&role!=='Agent'&&db.settings.hero?heroesPanel():'')};
const scopedNavigation=nav;
nav=function(p){if(p!==page){window.orderAgentFilter='';window.courierFilter='';followAgentFilter=followSourceFilter=followCallFilter=followResponseFilter='';orderSourceFilter=orderTagFilter=orderCallFilter=orderResponseFilter=''}scopedNavigation(p)};
function dashboardActionCards(){const os=visibleOrders().filter(inRange),cs=visibleCustomers(),ready=os.filter(o=>confirmedStatus(o.status)&&o.shipment==='Not Booked').length,dueNow=cs.filter(c=>callbackDueToday(c)),delivered=os.filter(o=>o.shipment==='Delivered'),returned=os.filter(o=>o.shipment==='Returned'),resolved=delivered.length+returned.length,cod=sumBy(delivered,o=>Math.max(0,due(o)-Number(o.finance?.settled||0)));return `<div class="stats dashboard-actions" data-layout-title="Action needed">${summaryTile('Ready to Book',ready,'Confirmed orders awaiting courier booking',"dashboardOrders('Ready to Book')")}${summaryTile('Due Callbacks',dueNow.length,'Today’s callbacks and overdue calls',"dashboardCustomers('Due Today')")}${summaryTile('Delivery / Return Rate',`${ratio(delivered.length,resolved)} <span class="rate-divider">/</span> ${ratio(returned.length,resolved)}`,`${delivered.length} delivered · ${returned.length} returned · resolved shipments`,"dashboardOrders('Delivered')")}${financialAccess()?summaryTile('Courier COD Pending',money(cod),'Delivered COD minus recorded receipts · manual ledger',"openCourierBalance()") :summaryTile('Delivered Orders',delivered.length,'Orders delivered in selected period',"dashboardOrders('Delivered')")}</div>`}
function openCourierBalance(){if(!financialAccess())return;const os=visibleOrders().filter(inRange).filter(o=>o.shipment==='Delivered');modal('Courier COD Pending','Delivered COD balances, before unrecorded courier deductions. Receipts are entered manually in this demo.',profitOrderTable(os))}
function canManageAssignment(){return role==='Admin'||role==='Manager'&&permitted('assign')}
function assignmentCell(o){const c=customer(o.customer),a=agent(c?.agent||'');return `<span class="badge ${a?'assignment-active':'assignment-empty'}">${a?'Assigned':'Unassigned'}</span><small>${esc(a?.name||'Available for assignment')}</small>${a?`<small>${esc(userCode(a))}</small>`:''}${canManageAssignment()?`<button class="table-inline-action" onclick="assignFromOrder('${o.id}')">${a?'Change':'Assign'}</button>`:''}`}
function assignFromOrder(id){if(!canManageAssignment())return;const o=db.orders.find(x=>x.id===id);if(!o)return;const c=customer(o.customer);selected.clear();selected.add(c.id);assignDialog()}
function orderNoteCell(o){return `<button class="table-note" onclick="editRecordNote('order','${o.id}')"><span>${esc(o.note||'Add a note')}</span><small>${o.noteUpdated?date(o.noteUpdated):'Order note'} · ${ico('edit')}</small></button>`}
function customerNoteCell(c){const n=c.notes?.[0];return `<button class="table-note" onclick="editRecordNote('customer','${c.id}')"><span>${esc(n?.text||'Add a note')}</span><small>${n?esc(n.by)+' · '+date(n.at):'Follow-up note'} · ${ico('edit')}</small></button>`}
function canAccessRecord(type,id){return type==='order'?visibleOrders().some(o=>o.id===id):visibleCustomers().some(c=>c.id===id)}
function editRecordNote(type,id){if(!canAccessRecord(type,id))return;const item=type==='order'?db.orders.find(o=>o.id===id):customer(id);modal(type==='order'?'Order note':'Add follow-up note',type==='order'?id:item.name,`<form onsubmit="saveRecordNote(event,'${type}','${id}')"><div class="field"><label for="record-note">Note</label><textarea id="record-note" name="note" required maxlength="2000" placeholder="Write a clear note for the next person…">${esc(type==='order'?item.note||'':'')}</textarea></div>${type==='customer'?'<p class="small muted">This adds to the customer’s note history.</p>':''}${modalFooter('Save note')}</form>`)}
function saveRecordNote(e,type,id){e.preventDefault();if(!canAccessRecord(type,id))return;const f=new FormData(e.target),text=String(f.get('note')||'').trim();if(!text)return toast('Enter a note.');const at=new Date().toISOString(),by=role==='Agent'?agentName(agentId):sessionAccount?.name||role;if(type==='order'){const o=db.orders.find(o=>o.id===id);o.note=text;o.noteUpdated=at;o.events||=[];o.events.unshift({text:'Order note: '+text,by,at})}else{const c=customer(id);c.notes||=[];c.notes.unshift({text,by,at})}save();closeModal();render();toast('Note saved.')}
function captureProfileSnapshot(){if(!db?.customers)return;const group=cs=>{const m=metricSet([],cs);return {profiles:cs.length,Assigned:m.assigned,'Pending Follow-up':m.pending,Completed:m.completed,'Not Connected':m.notConnected,Connected:m.connected,Positive:m.positive,Intermediate:m.intermediate,Negative:m.negative}},values={all:group(db.customers)};for(const a of db.agents)values[a.id]=group(db.customers.filter(c=>c.agent===a.id));db.profileMetricHistory||=[];const signature=JSON.stringify(values),last=db.profileMetricHistory.at(-1);if(last?.signature!==signature){db.profileMetricHistory.push({at:new Date().toISOString(),signature,values});db.profileMetricHistory=db.profileMetricHistory.slice(-500)}}
function previousProfileValue(label){const b=rangeBounds();if(!Number.isFinite(b.start))return null;const history=(db.profileMetricHistory||[]).filter(x=>new Date(x.at).getTime()<=b.start).at(-1);return history?.values?.[role==='Agent'?agentId:'all']?.[label]??null}
function comparisonNumbers(label){const aliases={'Confirmed Orders':'Confirmed orders',Profit:'Net profit','Purchase Rate':'Purchase rate'},name=aliases[label]||label,before=previousOrders();if(!before)return {previous:null,current:null,kind:'lifetime'};const prev=before.filter(o=>confirmedStatus(o.status)),now=visibleOrders().filter(inRange).filter(o=>confirmedStatus(o.status)),old=financeTotals(prev),current=financeTotals(now),key={'Revenue':'revenue','Product cost':'cost','Discount given':'discount','Net profit':'profit','Profit margin':'margin'}[name];if(key)return {current:current[key],previous:old[key],kind:['Profit margin'].includes(name)?'rate':'money'};if(name==='Confirmed orders')return {current:now.length,previous:prev.length,kind:'count'};if(name==='Purchase rate'){const n=visibleCustomers().length;return {current:n?new Set(now.map(o=>o.customer)).size/n*100:0,previous:n?new Set(prev.map(o=>o.customer)).size/n*100:0,kind:'rate'}}return {current:metricSet([],visibleCustomers())[{'Assigned':'assigned','Pending Follow-up':'pending',Completed:'completed','Not Connected':'notConnected',Connected:'connected',Positive:'positive',Intermediate:'intermediate',Negative:'negative'}[label]]??null,previous:previousProfileValue(label),kind:'snapshot'}}
function comparisonDisplay(d){const value=d.previous,previous=d.kind==='lifetime'?'Not applicable':value==null?(d.kind==='snapshot'?'No recorded history':'Not available'):d.kind==='money'?money(value):d.kind==='rate'?percentage(value):value;let badge='—',direction='neutral';if(d.current!=null&&value!=null){if(value===0){badge=d.current===0?'→ 0.0%':'No baseline'}else{const delta=(d.current-value)/Math.abs(value)*100;badge=`${delta>0?'↑':delta<0?'↓':'→'} ${Math.abs(delta).toFixed(1)}%`;direction=delta>0?'up':delta<0?'down':'neutral'}}return {previous,badge,direction}}
metricCard=function(label,value,foot,action='',cls=''){if(page==='dashboard'){const d=comparisonNumbers(label),v=comparisonDisplay(d);return `<button class="card metric-tile ${cls}" ${action?`onclick="${action}"`:''}><span class="label">${esc(label)}</span><div class="metric-value-row"><strong>${value}</strong><span class="change-badge change-${v.direction}">${esc(v.badge)}</span></div><small class="previous-line">Previous: <b>${esc(String(v.previous))}</b></small><small class="metric-context">${esc(({'Confirmed Orders':'Orders in selected period',Revenue:'Confirmed order value'}[label]||foot).split(' · ')[0])}</small></button>`}return originalMetricCard(label,value,foot,action,cls)};
function callbackDueToday(c){const shift=21600000,day=86400000,end=Math.floor((Date.now()+shift)/day)*day-shift+day;return Boolean(c.callback)&&new Date(c.callback).getTime()<end}
openCourierBalance=function(){if(!financialAccess())return;const os=visibleOrders().filter(inRange).filter(o=>o.shipment==='Delivered');modal('Courier COD Pending','Delivered parcels · receipts are manual in this demo · balances are before unrecorded courier deductions.',`<div class="table-wrap"><table><thead><tr><th>Order</th><th>Customer</th><th>Courier</th><th>COD</th><th>Recorded receipt</th><th>Pending</th><th></th></tr></thead><tbody>${os.map(o=>`<tr><td>${esc(o.id)}</td><td>${esc(customer(o.customer)?.name)}</td><td>${esc(o.courier)}</td><td>${money(due(o))}</td><td>${money(Number(o.finance?.settled||0))}</td><td><strong>${money(Math.max(0,due(o)-Number(o.finance?.settled||0)))}</strong></td><td><button onclick="financeForm('${o.id}')">Update receipt</button></td></tr>`).join('')||'<tr><td colspan="7">No delivered orders in this period.</td></tr>'}</tbody></table></div>`)};

