function layoutSections(){if(role==='Agent')return;beginLayoutDraft();if(!$('#view').classList.contains('layout-editing'))render();modal('Arrange your page','Move, resize, rename or remove sections. Removed sections can be restored; customer and order records stay saved.',`<h3>Page sections</h3><div class="layout-sort-list">${layoutBlocks.map((item,i)=>layoutRow(item,i,'block')).join('')}</div><details class="section-gap"><summary>Individual widgets inside sections</summary><div class="layout-sort-list section-gap">${layoutItems.map((item,i)=>layoutRow(item,i,'widget')).join('')}</div></details><div class="notice section-gap">Move sections up or down, or drag the rows. Individual widgets move within their group. Remove only changes this page layout.</div><div class="modal-footer"><button onclick="closeModal()">Continue editing</button><button class="primary" onclick="savePageLayout()">Save layout</button></div>`)}
function layoutRow(item,i,type){const removed=(layoutDraft.removed||[]).includes(item.id);return `<div class="layout-sort-row" draggable="true" ondragstart="event.dataTransfer.setData('text/plain','${type}:${item.id}')" ondragover="event.preventDefault()" ondrop="dropLayoutItem(event,'${type}','${item.id}')"><span class="drag-dots" aria-hidden="true">⠿</span><label><input type="checkbox" ${!layoutDraft.hidden.includes(item.id)?'checked':''} onchange="setLayoutVisible('${item.id}',this.checked)"><span>${esc(layoutDraft.edits?.[item.id]?.title||item.title)}${removed?' · Removed':''}</span></label><button onclick="editLayoutSection('${item.id}')">Edit</button><button onclick="removeLayoutSection('${item.id}',${!removed})">${removed?'Restore':'Remove'}</button><button class="icon" aria-label="Move ${esc(item.title)} up" onclick="moveLayoutItem('${type}','${item.id}',-1)">↑</button><button class="icon" aria-label="Move ${esc(item.title)} down" onclick="moveLayoutItem('${type}','${item.id}',1)">↓</button></div>`}
function setLayoutVisible(id,on){if(role==='Agent')return;layoutDraft.hidden=layoutDraft.hidden.filter(x=>x!==id);if(!on)layoutDraft.hidden.push(id);render();layoutSections()}
function orderedLayoutItems(type,id){const items=type==='block'?layoutBlocks:layoutItems,field=type==='block'?'order':'widgetOrder',target=items.find(x=>x.id===id),siblings=type==='block'?items:items.filter(x=>x.el.parentElement===target.el.parentElement);return {field,items:siblings.slice().sort((a,b)=>{const ai=layoutDraft[field].indexOf(a.id),bi=layoutDraft[field].indexOf(b.id);return (ai<0?1000+siblings.indexOf(a):ai)-(bi<0?1000+siblings.indexOf(b):bi)})}}
function moveLayoutItem(type,id,direction){if(role==='Agent')return;const sorted=orderedLayoutItems(type,id),ids=sorted.items.map(x=>x.id),i=ids.indexOf(id),j=i+direction;if(j<0||j>=ids.length)return;[ids[i],ids[j]]=[ids[j],ids[i]];layoutDraft[sorted.field]=[...layoutDraft[sorted.field].filter(x=>!ids.includes(x)),...ids];render();layoutSections()}
