function layoutSettings(){if(role==='Agent')return;beginLayoutDraft();modal('Layout settings','Keep this page comfortable on your screen.',`<form onsubmit="event.preventDefault();layoutDraft.density=this.elements.density.value;layoutDraft.columns=this.elements.columns.value;layoutDraft.widgetPosition=this.elements.position.value;closeModal();render()">${selectField('Spacing','density',['comfortable','compact'],layoutDraft.density)}${selectField('Grid columns (desktop)','columns',['auto','1','2','3','4'],layoutDraft.columns)}${selectField('Added widgets position','position',['top','bottom'],layoutDraft.widgetPosition||'top')}${modalFooter('Apply to draft')}</form>`)}
const widgetLibrary=[{type:'orders',name:'Order total',desc:'Orders in the selected reporting period.'},{type:'revenue',name:'Confirmed revenue',desc:'Value of confirmed orders.'},{type:'pending',name:'Pending follow-ups',desc:'Assigned profiles waiting for follow-up.'},{type:'delivery',name:'Delivery progress',desc:'Booked, delivered and returned shipments.'},{type:'calls',name:'Call outcomes',desc:'Latest connected and not-connected calls.'},{type:'sources',name:'Customer sources',desc:'Current profiles by order source.'},{type:'profit',name:'Profit estimate',desc:'After recorded item costs and fees.'},{type:'note',name:'Text / team note',desc:'A useful reminder or heading for your page.'}];
