function addWidgetDialog(){if(role==='Agent')return;beginLayoutDraft();modal('Add a widget','Choose the information you want on this page.',`<div class="widget-library">${widgetLibrary.filter(w=>canUseWidget(w.type)).map(w=>`<button onclick="customWidgetForm('${w.type}')"><strong>${esc(w.name)}</strong><small>${esc(w.desc)}</small><span>+ Add</span></button>`).join('')||'<p>Platform layout supports existing aggregate sections. Store widgets are available in Admin panels.</p>'}</div>`)}
