function renderCustomWidget(w){const os=visibleOrders().filter(inRange),cs=visibleCustomers(),confirmed=os.filter(o=>confirmedStatus(o.status));let content;if(w.type==='note')content=`<p class="custom-note">${esc(w.note)}</p>`;else if(w.type==='orders')content=`<strong class="custom-value">${os.length}</strong><p class="small muted">Orders · selected period</p>`;else if(w.type==='revenue')content=`<strong class="custom-value">${money(financeTotals(confirmed).revenue)}</strong><p class="small muted">Confirmed order value</p>`;else if(w.type==='profit'){const f=financeTotals(confirmed);content=`<strong class="custom-value">${f.profit===null?'Cost missing':money(f.profit)}</strong><p class="small muted">Estimate after recorded expenses</p>`}else if(w.type==='pending')content=`<strong class="custom-value">${cs.filter(c=>c.agent&&pendingStatus(c.status)).length}</strong><p class="small muted">Current assigned profiles awaiting follow-up</p>`;else if(w.type==='delivery')content=horizontalVisual(['Booked','In Transit','Delivered','Returned'].map(s=>({label:s,value:os.filter(o=>o.shipment===s).length})));else if(w.type==='calls')content=ringVisual(['Connected','Not Connected'].map(s=>({label:s,value:cs.filter(c=>c.call===s).length})),'calls');else content=horizontalVisual([...new Set(cs.map(c=>c.source))].map(s=>({label:s,value:cs.filter(c=>c.source===s).length})));return `<section class="card custom-widget widget-${esc(w.width)}"><h2>${esc(w.title)}</h2>${content}${layoutEditing?`<div class="custom-widget-tools"><button aria-label="Move ${esc(w.title)} left" onclick="moveCustomWidget('${w.id}',-1)">←</button><button aria-label="Move ${esc(w.title)} right" onclick="moveCustomWidget('${w.id}',1)">→</button><button onclick="editCustomWidget('${w.id}')">Edit</button><button onclick="removeCustomWidget('${w.id}')">Remove</button></div>`:''}</section>`}
async function resetPageLayout(){if(role==='Agent')return;closePageMenu();if(!(await askConfirm('Reset this page layout?','Restore the default sections and remove custom widgets for this page only? Business records will not change.')))return;localStorage.removeItem(layoutKey());layoutEditing=false;layoutDraft=null;render();toast('Default page layout restored.')}
const originalRenderWithLayout=render;
