function editLayoutSection(id){if(role==='Agent')return;beginLayoutDraft();const item=[...layoutBlocks,...layoutItems].find(x=>x.id===id);if(!item)return;const edit=layoutDraft.edits?.[id]||{};modal('Edit section','Rename and size this section. Save layout to keep your changes.',`<form onsubmit="saveLayoutSection(event,'${id}')">${field('Section title','title',edit.title||item.title,'text','required maxlength="100"')}${selectField('Width in its grid','width',['auto','small','half','full'],edit.width||'auto')}${modalFooter('Apply to draft')}</form>`)}
