function removeLayoutSection(id,remove){if(role==='Agent')return;beginLayoutDraft();layoutDraft.removed=(layoutDraft.removed||[]).filter(x=>x!==id);if(remove)layoutDraft.removed.push(id);render();layoutSections()}

'use strict';
// Browser demo workspace hierarchy. Production requires database-enforced authorization.
function isOwner(){const a=authDirectory.accounts.find(x=>x.id===sessionAccount?.id);return role==='Admin'&&!!a&&!a.memberId&&['Owner','Super Admin'].includes(a?.accountType||'Owner')}
function hasOwnerAuthority(){return isOwner()||typeof isCreator==='function'&&isCreator()}
function canManageUsers(){return role==='Admin'}
function userRoles(){return isOwner()?['Agent','Manager','Admin']:['Agent','Manager']}
function ownedShops(){return authDirectory.stores.filter(s=>s.owner===sessionAccount?.id)}
const hierarchyGateway=accountGateway;
accountGateway=function(view){hierarchyGateway(view==='signup'&&!authDirectory.accounts.length?'signup':'login');const root=$('#app');if(!root)return;if(authDirectory.accounts.length){root.querySelectorAll('.auth-tabs button,.auth-help').forEach(el=>{if(el.textContent.includes('Create Account')||el.classList.contains('auth-help'))el.remove()});const help=root.querySelector('.login-box>small');if(help)help.textContent='Ask your Owner or Admin for your login email and password.'}else if(authPage==='signup'){const select=$('#auth-type');if(select){select.innerHTML='<option value="Owner">Owner</option>';updateSignupType('Owner')}}};
const hierarchySignup=createLocalAccount;
createLocalAccount=async function(e){if(authDirectory.accounts.length)return authError('Your Owner or Admin creates accounts through Add user. Please login.');return hierarchySignup(e)};
const hierarchyStart=startAccountSession;
startAccountSession=function(a,opts){hierarchyStart(a,opts);if(opts?.resume&&isOwner()){const id=sessionStorage.getItem('jioflow.owner.shop');if(ownedShops().some(s=>s.id===id&&s.active)){loadStore(id);sessionAccount.storeId=id;render()}}};
const hierarchyShell=shell;
shell=function(){let html=hierarchyShell();if(!isOwner())html=html.replace(/<button onclick="nav\('stores'\)"[^>]*>[\s\S]*?<\/button>/,'');if(role==='Manager')html=html.replace(/<button onclick="nav\('team'\)"[^>]*>[\s\S]*?<\/button>/,'');if(isOwner())html=html.replace('<div class="top-actions">',`<div class="top-actions"><select aria-label="Switch shop" onchange="switchShop(this.value)">${ownedShops().filter(s=>s.active).map(s=>`<option value="${esc(s.id)}" ${s.id===activeStoreId?'selected':''}>${esc(s.name)}</option>`).join('')}</select>`);if(isOwner())html=html.replace('<button onclick="nav(\'settings\')"',`<button onclick="nav('admins')" class="${page==='admins'?'active':''}">${ico('customers')} Admin Management</button><button onclick="nav('settings')"`);if(isOwner())html=html.replace('<small>Admin</small>','<small>Owner</small>');return html.replace('Workspaces</button>','Shops</button>')};
function switchShop(id){if(!isOwner()||!ownedShops().some(s=>s.id===id&&s.active))return toast('Only the shop Owner can switch to an owned shop.');save();loadStore(id);sessionAccount.storeId=id;sessionStorage.setItem('jioflow.owner.shop',id);selected.clear();page='dashboard';render()}
storesView=function(){if(!isOwner())return empty('Only the Owner can create and manage shops.');return heading('Your shops','Independent customers, users, products and reports for every shop.',`<button class="dark" onclick="shopForm()">${ico('plus')} Create shop</button>`)+`<div class="shop-list">${ownedShops().map(s=>`<section class="card"><div class="row between"><div><h2>${esc(s.name)}</h2><p class="small muted">Workspace code: ${esc(s.id)}</p></div>${badge(s.active?'Active':'Inactive')}</div><button onclick="switchShop('${s.id}')">${s.id===activeStoreId?'Current shop':'Open shop'}</button></section>`).join('')}</div>`};
function shopForm(){if(!isOwner())return;modal('Create shop','Only the Owner can create shops. Each shop starts with an empty workspace.',`<form onsubmit="createShop(event)">${field('Shop name','shopName','','text','required maxlength="100"')}${modalFooter('Create shop')}</form>`)}
function createShop(e){e.preventDefault();if(!isOwner())return;const name=new FormData(e.target).get('shopName').trim();if(!name)return;const id='JF-'+uid().slice(0,8).toUpperCase();authDirectory.stores.push({id,name,owner:sessionAccount.id,active:true});localStorage.setItem('jioflow.store.'+id,JSON.stringify(blankStore(name)));persistAuth();closeModal();switchShop(id);toast('Shop created. Add users and products to get started.')}
// Account form: one Add user flow creates both profile and login credentials.
const hierarchyAgentForm=agentForm;
agentForm=function(id){if(!canManageUsers())return toast('Only Owner or Admin can manage users.');const member=agent(id);if(member?.role==='Admin'&&!hasOwnerAuthority())return toast('Only Owner can edit Admin accounts.');hierarchyAgentForm(id);const roleSelect=$('#userRole');if(roleSelect)roleSelect.innerHTML=options(userRoles().filter(x=>x!=='Admin'),member?.role||'Agent');const input=$('#modal input[name="memberPassword"]');if(input){const exists=!!id&&authDirectory.accounts.some(x=>x.storeId===activeStoreId&&x.memberId===id);input.required=!exists;input.placeholder=exists?'Leave blank to keep password':'Set login password (at least 6 characters)';input.previousElementSibling.textContent=exists?'New password (optional)':'Login password';input.parentElement.nextElementSibling.textContent='Saving creates a login account. This user does not need to register again.';const hint=input.parentElement.querySelector('p');if(hint)hint.remove()}
const section=$('#modal .permission-grid');if(section){section.insertAdjacentHTML('beforeend', [['assign','Distribute customers'],['products','Manage products'],['import','Import orders'],['profit','View profit & reports'],['settings','Manage shop settings']].map(([k,l])=>`<label class="permission"><input type="checkbox" name="${k}" ${member?.permissions?.[k]?'checked':''}>${l}</label>`).join(''))}}
const hierarchySaveProfile=saveAgentWithoutLogin;
saveAgent=async function(e,id){e.preventDefault();if(memberSaving)return;if(!canManageUsers())return toast('Only Owner or Admin can create users.');const f=new FormData(e.target),type=f.get('userRole'),email=String(f.get('email')||'').trim().toLowerCase(),password=f.get('memberPassword')||'',old=id?authDirectory.accounts.find(x=>x.storeId===activeStoreId&&x.memberId===id):null,duplicate=accountByEmail(email);if(!userRoles().includes(type)||agent(id)?.role==='Admin'&&!hasOwnerAuthority())return toast('Only Owner can create or edit Admin accounts.');if(duplicate&&duplicate.id!==old?.id)return toast('This email already has a login account.');if(!old&&!password)return toast('Set a login password for this user.');if(password&&password.length<6)return toast('Use at least 6 characters.');if(f.get('sourceMode')==='selected'&&!f.getAll('sources').length)return toast('Select an order source or choose all.');if(f.get('importedStatusMode')==='selected'&&!f.getAll('importedStatuses').length)return toast('Select an imported status or choose all.');memberSaving=true;const before=JSON.stringify(db.agents),beforeAuth=JSON.stringify(authDirectory.accounts);try{const record=password?await passwordRecord(password):old.password;hierarchySaveProfile(e,id);const member=id?agent(id):db.agents.find(x=>x.email===email);if(!member||JSON.stringify(db.agents)===before&& !password)return;member.role=type;member.permissions.team=false;const account=old||{id:uid(),storeId:activeStoreId,memberId:member.id,created:new Date().toISOString()};Object.assign(account,{name:member.name,email,role:type,accountType:type,password:record});if(!old)authDirectory.accounts.push(account);persistAuth();save();render();toast('User and login account saved. They can login directly.')}catch(error){db.agents=JSON.parse(before);authDirectory.accounts=JSON.parse(beforeAuth);save();toast(error.message)}finally{memberSaving=false}};
// Settings follow the vertical reference, including account and password forms.
const hierarchySettings=settingsView;
settingsView=function(){if(role!=='Admin'&&!(role==='Manager'&&permitted('settings')))return empty('Settings access is not enabled.');return heading('Settings','Your account, password and shop preferences.')+`<div class="settings-stack"><section class="card"><h2>${ico('customers')} Account details</h2><form onsubmit="saveOwnDetails(event)"><div class="form-grid">${field('Full name','accountName',sessionAccount?.name,'text','required')}${field('Email','accountEmail',sessionAccount?.email,'email','required')}</div><p class="small muted">${isOwner()?'Owner':role} · ${esc(db.settings.storeName)}</p><button class="primary">Save account</button></form></section><section class="card"><h2>${ico('settings')} Change password</h2><form onsubmit="changeOwnPassword(event)">${field('Current password','currentPassword','','password','required autocomplete="current-password"')}<div class="form-grid">${field('New password','newPassword','','password','required minlength="6" autocomplete="new-password"')}${field('Confirm new password','confirmPassword','','password','required minlength="6" autocomplete="new-password"')}</div><button class="primary">Save password</button></form></section>${hierarchySettings().replace(/^[\s\S]*?(?=<div class="settings-grid">)/,'')}</div>`};
async function saveOwnDetails(e){e.preventDefault();const f=new FormData(e.target),email=f.get('accountEmail').trim().toLowerCase(),a=authDirectory.accounts.find(x=>x.id===sessionAccount.id),other=accountByEmail(email);if(other&&other.id!==a.id)return toast('This email is already used.');a.name=f.get('accountName').trim();a.email=email;if(a.memberId)Object.assign(agent(a.memberId),{name:a.name,email});Object.assign(sessionAccount,{name:a.name,email});persistAuth();save();render();toast('Account details saved.')}
async function changeOwnPassword(e){e.preventDefault();const f=new FormData(e.target),a=authDirectory.accounts.find(x=>x.id===sessionAccount.id);if(!await passwordMatches(f.get('currentPassword'),a.password))return toast('Current password is incorrect.');const value=f.get('newPassword');if(value!==f.get('confirmPassword'))return toast('Passwords do not match.');if(value.length<8)return toast('Use at least 6 characters.');a.password=await passwordRecord(value);persistAuth();e.target.reset();toast('Password updated.')}
// User groups belong only to this shop.
function groups(){return db.groups||=[]}
function groupForm(id){if(!canManageUsers())return;const g=groups().find(x=>x.id===id)||{name:'',members:[]};modal(id?'Edit group':'Create group','Choose the Agents who will share customer assignments.',`<form onsubmit="saveGroup(event,'${id||''}')">${field('Group name','groupName',g.name,'text','required maxlength="80"')}<div class="checklist">${db.agents.filter(a=>a.active&&!a.archived&&a.role==='Agent').map(a=>`<label class="permission"><input type="checkbox" name="members" value="${a.id}" ${g.members.includes(a.id)?'checked':''}>${esc(a.name)}</label>`).join('')}</div>${modalFooter('Save group')}</form>`)}
function saveGroup(e,id){e.preventDefault();if(!canManageUsers())return;const f=new FormData(e.target),members=f.getAll('members').filter(id=>agent(id)?.active&&agent(id)?.role==='Agent');if(!members.length)return toast('Choose at least one active Agent.');const g=groups().find(x=>x.id===id);if(g)Object.assign(g,{name:f.get('groupName').trim(),members});else groups().push({id:uid(),name:f.get('groupName').trim(),members});save();closeModal();render();toast('Group saved.')}
function deleteGroup(id){if(!canManageUsers())return;db.groups=groups().filter(g=>g.id!==id);save();render()}
const hierarchyTeam=teamView;
teamView=function(){if(!canManageUsers())return empty('Only Owner or Admin can manage users.');let html=hierarchyTeam();html+=`<section class="card section-gap"><div class="row between"><div><h2>${ico('customers')} User groups</h2><p class="small muted">Distribute selected customers equally across active Agents in a group.</p></div><button class="primary" onclick="groupForm()">${ico('plus')} Create group</button></div><div class="group-grid">${groups().map(g=>`<article class="group-item"><h3>${esc(g.name)}</h3><p class="small muted">${g.members.map(id=>esc(agentName(id))).join(', ')}</p><button onclick="groupForm('${g.id}')">Edit</button> <button onclick="deleteGroup('${g.id}')">Delete</button></article>`).join('')||empty('Create your first Agent group.')}</div></section>`;return html.replace(/(<div class="compact-user-stats">)/g,'$1')};
const hierarchyAssign=assignDialog;
assignDialog=function(){if(!permitted('assign'))return toast('Distribution permission is required.');hierarchyAssign();const form=$('#modal form');if(form)form.insertAdjacentHTML('afterbegin',`<div class="field"><label for="assignmentGroup">Distribute to a group (optional)</label><select id="assignmentGroup" name="assignmentGroup"><option value="">Choose individual Agents below</option>${groups().map(g=>`<option value="${g.id}">${esc(g.name)}</option>`).join('')}</select></div>`)};
doAssign=function(e){e.preventDefault();if(!permitted('assign'))return;const f=new FormData(e.target),group=groups().find(g=>g.id===f.get('assignmentGroup'));let ids=group?group.members:f.getAll('agents');ids=[...new Set(ids)].filter(id=>agent(id)?.active&&!agent(id)?.archived&&agent(id)?.role==='Agent');if(!ids.length)return toast('Choose a group with active Agents or select Agents.');if(!group&&f.get('mode')==='one'&&ids.length!==1)return toast('Choose one Agent or equal distribution.');const customers=[...selected].map(customer).filter(Boolean);customers.forEach((c,i)=>{c.agent=ids[i%ids.length];c.permanent=f.has('permanent')});log(customers.length+' customers distributed'+(group?' to '+group.name:''));selected.clear();closeModal();render();toast('Customers distributed equally.')};
// Concise Agent view and consistent dashboard hierarchy.
let permanentTab='New';
const hierarchyCustomers=customersView;
customersView=function(){if(page!=='permanent')return hierarchyCustomers();const cs=visibleCustomers().filter(c=>c.permanent),fresh=cs.filter(c=>!c.call&&pendingStatus(c.status)),rows=permanentTab==='New'?fresh:cs;return heading('Permanent Clients','Your assigned long-term customer relationships.')+`<section class="card"><div class="tabs"><button class="${permanentTab==='New'?'active':''}" onclick="permanentTab='New';render()">New <b>${fresh.length}</b></button><button class="${permanentTab==='All'?'active':''}" onclick="permanentTab='All';render()">All statuses <b>${cs.length}</b></button></div>${rows.length?agentCustomerCards(rows):empty('No permanent clients here. Your Admin can assign permanent clients to you.')}</section>`};
const hierarchyDashboard=dashboardView;
dashboardView=function(){let html=hierarchyDashboard();if(role!=='Agent')return html;const cs=visibleCustomers(),os=visibleOrders().filter(inRange),m=metricSet(os,cs),start=html.indexOf('<div class="stats dashboard-metrics"'),panels=html.indexOf('<div class="dashboard-panels"');if(start>=0&&panels>start)html=html.slice(0,start)+html.slice(panels);const end=html.indexOf('<div class="dashboard-grid section-gap"');if(end>=0)html=html.slice(0,end);const tiles=`<div class="stats agent-summary" data-layout-title="Your performance summary">${[['Confirmed',m.confirmed],['Completed',m.completed],['Assigned',m.assigned],['Connected',m.connected],['Not Connected',m.notConnected],['Purchase Rate',percentage(purchaseStats(os,cs).rate)],['Pending Follow-up',m.pending],['Positive',m.positive],['Intermediate',m.intermediate],['Negative',m.negative],['Not Attempted',cs.filter(c=>!c.call).length],['Sales',money(m.revenue)],['Avg Order Value',money(m.confirmed?m.revenue/m.confirmed:0)]].map(([label,n])=>metricCard(label,n,'Your assigned customers',"nav('customers')")).join('')}</div>`;const at=html.indexOf('<section class="card section-gap"><div class="row between"><h2>Confirmed Orders');const firstPanel=html.indexOf('<div class="dashboard-panels"');return firstPanel>=0?html.slice(0,firstPanel)+tiles+html.slice(firstPanel):html+tiles};
function iconForLabel(label){const l=label.toLowerCase();return /profit|revenue|value|cod|cost|discount/.test(l)?'reports':/product/.test(l)?'products':/deliver|courier|return|book/.test(l)?'courier':/call|connect/.test(l)?'phone':/rate|performance|funnel|source/.test(l)?'reports':/confirm|complete|positive/.test(l)?'check':/pending|attempt|intermediate/.test(l)?'bell':/cancel|negative|failed/.test(l)?'close':'customers'}
const hierarchyRender=render;
render=function(){if(signedIn&&page==='admins'&&!hasOwnerAuthority())page='dashboard';if(signedIn&&page==='stores'&&!hasOwnerAuthority())page='dashboard';if(signedIn&&page==='team'&&!canManageUsers())page='dashboard';if(signedIn&&sessionAccount?.memberId){const member=currentAgent();if(!member?.active||member.archived){signOut();return}}hierarchyRender();if(!signedIn||!sessionAllowed())return;const view=$('#view');if(!view)return;view.querySelectorAll('.metric-tile,.insight-tile,.stat,.overview-tile').forEach(el=>{const label=el.querySelector('.label,.tile-label,small')?.textContent||'';if(!el.querySelector('.metric-icon')){const icon=document.createElement('span');icon.className='metric-icon';icon.setAttribute('aria-hidden','true');icon.innerHTML=ico(iconForLabel(label));el.prepend(icon)}if(/^(profit|net profit)$/i.test(label.trim()))el.classList.add('profit-brand')});view.querySelectorAll('.dashboard-panels h2').forEach(el=>{if(!el.querySelector('svg'))el.insertAdjacentHTML('afterbegin',ico(iconForLabel(el.textContent))+' ')});view.querySelectorAll('.compact-user').forEach(el=>{const edit=el.querySelector('[onclick^="agentForm"]'),id=edit?.getAttribute('onclick')?.match(/'([^']+)'/)?.[1];if(!id)return;const cs=db.customers.filter(c=>c.agent===id),os=db.orders.filter(o=>o.agent===id&&inRange(o)),p=purchaseStats(os,cs),complete=cs.filter(c=>c.call&&!pendingStatus(c.status)).length;el.querySelector('.compact-user-stats')?.insertAdjacentHTML('afterend',`<div class="user-performance"><div class="row between"><span>Work completed</span><b>${ratio(complete,cs.length)}</b></div><div class="meter"><i style="width:${cs.length?Math.min(100,complete/cs.length*100):0}%"></i></div><div class="row between"><span>Confirmed ${os.filter(o=>confirmedStatus(o.status)).length}</span><span>Purchase ${percentage(p.rate)}</span></div><button onclick="openAgentReport('${id}')">View performance ${ico('arrow')}</button></div>`)});};

const hierarchyToggle=toggleAgent;
toggleAgent=function(id){if(!canManageUsers()||agent(id)?.role==='Admin'&&!hasOwnerAuthority())return toast('Only Owner can change Admin accounts.');return hierarchyToggle(id)};
const hierarchyArchive=archiveUser;
archiveUser=function(id){if(!canManageUsers()||agent(id)?.role==='Admin'&&!hasOwnerAuthority())return toast('Only Owner can archive Admin accounts.');if(agent(id)?.id===sessionAccount?.memberId)return toast('You cannot archive your own account.');return hierarchyArchive(id)};
const hierarchySaveSettings=saveSettings;
saveSettings=function(e){e.preventDefault();if(role!=='Admin'&&!(role==='Manager'&&permitted('settings')))return;hierarchySaveSettings(e);const shop=authDirectory.stores.find(s=>s.id===activeStoreId);if(shop){shop.name=db.settings.storeName;persistAuth()}};

// Semantic card colors and icons, shared by every summary surface.
Object.assign(icons,{'phone-off':'M3 3l18 18 M9 5l1-2H6v3 M5 9c2 5 5 8 10 10l2-2 4 1v3h-3C10 21 3 14 3 6','positive':'M7 10l5-7 2 1v5h5l2 2-2 9H7z M3 10h4v11H3z','negative':'M7 14l5 7 2-1v-5h5l2-2-2-9H7z M3 3h4v11H3z','intermediate':'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M8 12h8 M9 8h.01 M15 8h.01','completed':'M5 4h14v17H5z M9 2h6v4H9z M8 13l3 3 5-6','confirmed':'M12 2l8 4v6c0 5-8 10-8 10S4 17 4 12V6z M8 12l3 3 5-6','money':'M3 6h18v12H3z M12 9a3 3 0 1 0 0 6 3 3 0 0 0 0-6 M6 9h.01 M18 15h.01'});
iconForLabel=function(label){const l=label.toLowerCase();if(/not connected|no answer|not response/.test(l))return 'phone-off';if(/negative|cancel|failed/.test(l))return 'negative';if(/intermediate/.test(l))return 'intermediate';if(/positive/.test(l))return 'positive';if(/complete/.test(l))return 'completed';if(/confirm/.test(l))return 'confirmed';if(/connected|call/.test(l))return 'phone';if(/pending|attempt|due/.test(l))return 'clock';if(/profit|revenue|value|cod|cost|discount/.test(l))return 'money';if(/rate|source|funnel|performance/.test(l))return 'reports';if(/product/.test(l))return 'products';if(/courier|deliver|return|book/.test(l))return 'courier';return 'customers'};
function toneForLabel(label){const l=label.toLowerCase();if(/not connected|negative|cancel|failed|return/.test(l))return 'rose';if(/intermediate|pending|not attempt|due|no answer/.test(l))return 'amber';if(/positive|confirm|deliver/.test(l))return 'green';if(/complete/.test(l))return 'blue';if(/connected/.test(l))return 'teal';if(/purchase|rate/.test(l))return 'violet';return 'sage'}
const semanticRender=render;
render=function(){semanticRender();if(!signedIn||!sessionAllowed())return;const view=$('#view');if(!view)return;view.querySelectorAll('.metric-tile,.insight-tile,.stat,.overview-tile').forEach(el=>{const label=el.querySelector('.label,.tile-label')?.textContent?.trim()||'';el.dataset.tone=toneForLabel(label);const icon=el.querySelector('.metric-icon');if(icon)icon.innerHTML=ico(iconForLabel(label))});view.querySelectorAll('.card h2').forEach(el=>{if(!el.querySelector('svg'))el.insertAdjacentHTML('afterbegin',ico(iconForLabel(el.textContent))+' ')});view.querySelectorAll('.dashboard-metrics,.agent-summary').forEach(grid=>{const tiles=[...grid.children],confirmed=tiles.find(el=>/^(Confirmed|Confirmed Orders)$/.test(el.querySelector('.label')?.textContent?.trim()||'')),complete=tiles.find(el=>/^Completed$/.test(el.querySelector('.label')?.textContent?.trim()||''));if(confirmed&&complete)confirmed.after(complete)});};
// Admin accounts have their own Owner-only management panel.
function adminAccountsView(){if(!isOwner())return empty('Only the Owner can manage Admin accounts.');const users=db.agents.filter(a=>a.role==='Admin'&&!a.archived);return heading('Admin Management','Create and manage Admin login accounts for this shop. No account limit.',`<button class="dark" onclick="adminAccountForm()">${ico('plus')} Add Admin</button>`)+`<div class="notice">${esc(db.settings.storeName)} · Admins manage this shop. They cannot create shops or change the Owner account.</div><div class="compact-users">${users.map(a=>`<section class="card compact-user"><div class="row"><span class="avatar">${initials(a.name)}</span><div><h3>${esc(a.name)}</h3>${badge(a.active?'Active':'Inactive')}</div></div><p class="small muted">${esc(a.email)}</p><div class="user-actions"><button onclick="adminAccountForm('${a.id}')">${ico('edit')} Edit account</button><button onclick="toggleAgent('${a.id}')">${a.active?'Deactivate':'Activate'}</button></div></section>`).join('')||empty('No Admin accounts yet. Create one to delegate shop operations.')}</div>`}
function adminAccountForm(id){if(!isOwner())return;const a=agent(id)||{};if(id&&a.role!=='Admin')return;modal(id?'Edit Admin':'Create Admin','This Admin will login directly with the email and password you set.',`<form onsubmit="saveAdminAccount(event,'${id||''}')">${field('Full name','adminName',a.name||'','text','required maxlength="100"')}${field('Email','adminEmail',a.email||'','email','required')}${field(id?'New password (leave blank to keep)':'Login password','adminPassword','','password',`${id?'':'required'} minlength="6" autocomplete="new-password"`)}${modalFooter(id?'Save Admin':'Create Admin')}</form>`)}
async function saveAdminAccount(e,id){e.preventDefault();if(!hasOwnerAuthority()||memberSaving)return;const f=new FormData(e.target),name=f.get('adminName').trim(),email=f.get('adminEmail').trim().toLowerCase(),password=f.get('adminPassword')||'',old=id?authDirectory.accounts.find(x=>x.storeId===activeStoreId&&x.memberId===id):null,a=id?agent(id):null;if(id&&a?.role!=='Admin')return;if(!name||!email)return toast('Enter name and email.');if(accountByEmail(email)&&accountByEmail(email).id!==old?.id)return toast('This email already has an account.');if((!old||password)&&password.length<6)return toast('Use at least 6 characters.');memberSaving=true;try{const record=password?await passwordRecord(password):old.password,member=a||{id:uid(),active:true,permissions:{},sources:[],role:'Admin',pullCount:20};Object.assign(member,{name,email});if(!a)db.agents.push(member);const account=old||{id:uid(),memberId:member.id,storeId:activeStoreId,created:new Date().toISOString()};Object.assign(account,{name,email,password:record,role:'Admin',accountType:'Admin'});if(!old)authDirectory.accounts.push(account);persistAuth();log('Admin account saved: '+name);closeModal();render();toast('Admin account saved. Login directly with these credentials.')}catch(error){toast(error.message)}finally{memberSaving=false}}
function canConfigureShop(){return role==='Admin'||role==='Manager'&&permitted('settings')}
function moneySettingsPanel(){return `<section class="card" data-layout-title="Order money settings"><h2>Order money settings</h2><p class="small muted">Default delivery charge and shop-wide Agent discount rules.</p><form onsubmit="saveMoneySettings(event)">${field('Default delivery charge','defaultDelivery',db.settings.defaultDelivery??db.settings.outside,'number','min="0" step="0.01" required')}<p class="small muted">Pre-filled on new orders. Recorded delivery expense is included in profit calculations.</p><label class="permission"><input type="checkbox" name="limitDiscount" ${db.settings.limitAgentDiscounts?'checked':''}>Limit Agent discounts</label>${field('Maximum Agent discount (BDT)','maxDiscount',db.settings.maxAgentDiscount??0,'number','min="0" step="0.01" required')}<label class="permission"><input type="checkbox" disabled>Show profit to Agents</label><p class="small muted">Off under your current access policy. Agents see selling prices; product costs and profit stay with authorized accounts.</p><button class="primary">Save money settings</button></form></section>`}
function saveMoneySettings(e){e.preventDefault();if(!canConfigureShop())return;const f=new FormData(e.target),delivery=Number(f.get('defaultDelivery')),discount=Number(f.get('maxDiscount'));if(!Number.isFinite(delivery)||!Number.isFinite(discount)||delivery<0||discount<0)return toast('Enter valid nonnegative amounts.');Object.assign(db.settings,{defaultDelivery:delivery,limitAgentDiscounts:f.has('limitDiscount'),maxAgentDiscount:discount});log('Order money settings updated');render();toast('Money settings saved.')}
function heroSchedule(){return db.settings.heroSchedule||[{time:'18:00',day:'today'}]}
function heroSettingsPanel(){return `<section class="card" data-layout-title="Today's Hero"><h2>Today's Hero</h2><p class="small muted">Celebrate the top three Agents by confirmed orders. Each scheduled slot is shown once per Agent in this browser demo.</p><form onsubmit="saveHeroSettings(event)"><label class="permission"><input type="checkbox" name="heroEnabled" ${db.settings.hero?'checked':''}>Enabled</label><h3 class="section-gap">Show times (Bangladesh time)</h3><div id="hero-slots">${heroSchedule().map(s=>heroSlotRow(s)).join('')}</div><div class="row section-gap"><button type="button" onclick="document.getElementById('hero-slots').insertAdjacentHTML('beforeend',heroSlotRow({time:'18:00',day:'today'}))">${ico('plus')} Add another time</button><button type="button" onclick="document.getElementById('hero-slots').innerHTML=heroSlotRow({time:'18:00',day:'today'})">Use default schedule</button></div>${field('Message under the podium (optional)','heroMessage',db.settings.heroMessage||'','text','maxlength="250"')}<div class="row section-gap"><button class="primary">Save Hero settings</button><button type="button" onclick="previewHeroPopup()">Preview popup</button></div></form></section>`}
function heroSlotRow(s){return `<div class="hero-slot"><input aria-label="Hero show time" name="heroTime" type="time" value="${esc(s.time)}" required><select aria-label="Hero reporting day" name="heroDay">${options(['today','yesterday'],s.day)}</select><button type="button" aria-label="Remove show time" onclick="this.parentElement.remove()">${ico('close')}</button></div>`}
function saveHeroSettings(e){e.preventDefault();if(!canConfigureShop())return;const f=new FormData(e.target),times=f.getAll('heroTime'),days=f.getAll('heroDay');if(!times.length)return toast('Add at least one show time.');if(times.some(t=>!/^\d{2}:\d{2}$/.test(t)))return toast('Choose valid show times.');db.settings.hero=f.has('heroEnabled');db.settings.heroSchedule=times.map((time,i)=>({time,day:days[i]==='yesterday'?'yesterday':'today'}));db.settings.heroMessage=String(f.get('heroMessage')||'').trim();log('Hero schedule updated');render();toast('Hero schedule saved.')}
function heroLeaders(dayOffset=0,base=Date.now()){const day=86400000,start=Math.floor((base+21600000)/day)*day-21600000-dayOffset*day;return db.agents.filter(a=>!a.archived&&a.role==='Agent').map(a=>({name:a.name,count:db.orders.filter(o=>o.agent===a.id&&confirmedStatus(o.status)&&new Date(o.created).getTime()>=start&&new Date(o.created).getTime()<start+day).length})).filter(a=>a.count).sort((a,b)=>b.count-a.count).slice(0,3)}
function previewHeroPopup(dayOffset=0,base=Date.now()){if(role==='Agent'&&!db.settings.hero)return;const leaders=heroLeaders(dayOffset,base);modal("Today's Hero",dayOffset?"Yesterday's top three · confirmed orders":"Today's top three · confirmed orders",`<div class="hero-podium">${leaders.map((a,i)=>`<div><span class="rank-medal">#${i+1}</span><h3>${esc(a.name)}</h3><strong>${a.count}</strong><p class="small muted">confirmed orders</p></div>`).join('')||empty('No confirmed orders in this reporting day.')}</div><p class="small muted">${esc(db.settings.heroMessage||'Every conversation makes a difference. Keep going!')}</p><div class="modal-footer"><button class="primary" onclick="closeModal()">Continue</button></div>`)}
const referenceSettings=settingsView;
settingsView=function(){let html=referenceSettings();if(!canConfigureShop())return html;const at=html.indexOf('<div class="settings-grid">');if(at>=0)html=html.slice(0,at)+moneySettingsPanel()+heroSettingsPanel()+html.slice(at);return html.replace(/<section class="card section-gap" data-layout-title="Performance celebration">[\s\S]*?<\/section>/,'')};
const referenceRender=render;
render=function(){referenceRender();if(!signedIn||!sessionAllowed()||role!=='Agent'||!db.settings.hero||$('#modal')?.open)return;const day=86400000,start=Math.floor((Date.now()+21600000)/day)*day-21600000;const slots=heroSchedule().flatMap(s=>[0,1].map(back=>({s,at:start-back*day+Number(s.time.slice(0,2))*3600000+Number(s.time.slice(3))*60000}))).filter(x=>x.at<=Date.now()).sort((a,b)=>b.at-a.at);const latest=slots[0];if(!latest)return;const key='jioflow.hero.seen.'+activeStoreId+'.'+agentId+'.'+latest.at;if(localStorage.getItem(key))return;localStorage.setItem(key,'1');previewHeroPopup(latest.s.day==='yesterday'?1:0,latest.at)};

'use strict';
// Executable local prototype. Production verification and cross-device sessions require a backend.
function accountRecord(){return authDirectory.accounts.find(a=>a.id===sessionAccount?.id)}
function isCreator(){return accountRecord()?.accountType==='Creator'&&authDirectory.creatorId===sessionAccount?.id}
function creatorExists(){return !!authDirectory.creatorId&&authDirectory.accounts.some(a=>a.id===authDirectory.creatorId&&a.accountType==='Creator')}
function refreshDirectory(){try{const d=JSON.parse(localStorage.getItem('jioflow.auth.v1'));if(d)authDirectory=d}catch{}}
function creatorAudit(text){authDirectory.audit||=[];authDirectory.audit.unshift({text,by:sessionAccount?.id||'setup',at:new Date().toISOString()});authDirectory.audit=authDirectory.audit.slice(0,300);persistAuth()}
const platformGateway=accountGateway;
accountGateway=function(){refreshDirectory();authPage='login';const setup=!authDirectory.accounts.length&&!creatorExists();$('#app').innerHTML=`<main class="login-layout"><section class="login-story"><div class="account-brand"><span class="brandmark"></span><strong>Jio<span>Flow</span></strong></div><div><span class="badge green">One platform. Clear responsibilities.</span><h1>${setup?'Set up your platform.':'One login.<br>Your own workspace.'}</h1><p>Creator → Owner → Admin → Manager → Agent</p><p>Every account opens the right panel automatically.</p></div><small>JioFlow · Your business, in flow.</small></section><section class="login-form-area"><div class="login-box"><h2>${setup?'Set up the only Creator account':'Welcome back.'}</h2><p class="muted small">${setup?'One-time setup. All other accounts are created from inside the platform.':'Use the email and password provided by your Creator, Owner or Admin.'}</p><div class="auth-demo"><strong>Local prototype</strong> · Accounts exist in this browser. Email delivery and cross-device access require the planned backend. Use test credentials.</div><form onsubmit="${setup?'setupCreator':'loginLocalAccount'}(event)">${setup?field('Full name','creatorName','','text','required maxlength="100"'):''}${field('Email','auth-email','','email','required autocomplete="email"')}${field('Password','auth-password','','password','required minlength="6" autocomplete="'+(setup?'new-password':'current-password')+'"')}${setup?field('Confirm password','creatorConfirm','','password','required minlength="6" autocomplete="new-password"'):''}<p id="auth-error" class="auth-error" role="alert"></p><button id="auth-submit" class="dark auth-submit">${setup?'Create Creator account':'Login'}</button></form><p class="small muted">${setup?'After setup, this page shows Login only.':'There is no public registration.'}</p></div></section></main>`};
createLocalAccount=function(e){e?.preventDefault();authError('Public registration is closed. Creator creates Owners; Owners create their staff.')};
async function setupCreator(e){e.preventDefault();refreshDirectory();if(authBusy)return;if(creatorExists()||authDirectory.accounts.length)return authError('Creator setup is closed. Login with an existing account.');const f=new FormData(e.target),email=f.get('auth-email').trim().toLowerCase(),password=f.get('auth-password');if(password!==f.get('creatorConfirm'))return authError('Passwords do not match.');if(password.length<6)return authError('Use at least 6 characters.');authBusy=true;try{const a={id:uid(),name:f.get('creatorName').trim(),email,password:await passwordRecord(password),role:'Admin',accountType:'Creator',active:true,sessionVersion:0,created:new Date().toISOString()};authDirectory.accounts.push(a);authDirectory.creatorId=a.id;persistAuth();startAccountSession(a);creatorAudit('Creator setup completed')}catch(error){authError(error.message)}finally{authBusy=false}}
function promoteExistingCreator(){if(!isOwner()||creatorExists())return toast('Creator setup is not available.');const a=accountRecord();a.accountType='Creator';authDirectory.creatorId=a.id;sessionAccount.accountType='Creator';creatorAudit('Existing primary Owner completed Creator setup');page='creator';render()}
function ensurePlatformStore(a){if(a.storeId&&readStore(a.storeId))return;const id='platform-'+a.id;const d=blankStore('JioFlow Platform');localStorage.setItem('jioflow.store.'+id,JSON.stringify(d));a.storeId=id;authDirectory.stores.push({id,name:'JioFlow Platform',owner:a.id,active:true,platform:true});persistAuth()}
const platformStart=startAccountSession;
startAccountSession=function(a,opts={}){if(a.active===false)throw Error('Your account is inactive.');if(['Owner','Admin'].includes(a.accountType)&&a.emailActivation==='pending')throw Error('Email activation is pending. In this prototype, ask the Creator/Owner to open the clearly labelled verification preview. Production requires a real email link.');if(a.accountType==='Creator'||a.accountType==='Owner'&&!a.storeId)ensurePlatformStore(a);
const saved=opts.resume?JSON.parse(sessionStorage.getItem('jioflow.platform.session')||'null'):null;authDirectory.sessions||=[];let record=saved&&authDirectory.sessions.find(s=>s.id===saved.id&&s.account===a.id);if(opts.resume&&(!record||record.revoked||saved.version!==(a.sessionVersion||0)))throw Error('This session was signed out by a higher-level account.');if(!record){record={id:uid(),account:a.id,device:demoDeviceId(),version:a.sessionVersion||0,created:new Date().toISOString(),lastSeen:new Date().toISOString(),revoked:false};authDirectory.sessions.push(record);persistAuth()}sessionStorage.setItem('jioflow.platform.session',JSON.stringify({id:record.id,version:a.sessionVersion||0}));platformStart(a,opts);if(a.accountType==='Creator')page='creator';else if(a.accountType==='Owner'&&!ownedShops().length)page='stores';render()};
const platformSignOut=signOut;
signOut=function(){const saved=JSON.parse(sessionStorage.getItem('jioflow.platform.session')||'null'),s=authDirectory.sessions?.find(s=>s.id===saved?.id);if(s){s.revoked=true;persistAuth()}sessionStorage.removeItem('jioflow.platform.session');platformSignOut()};
demoDeviceId=function(){let id=localStorage.getItem('jioflow.browser.device');if(!id){id=uid();localStorage.setItem('jioflow.browser.device',id)}return id};
const platformApproval=manageSession;
manageSession=function(id,action){if(role!=='Admin')return toast('Only Creator, Owner or Admin can review access.');const s=db.sessions.find(s=>s.id===id);if(action==='approve'&&s){const a=agent(s.user);if(!a||a.role!=='Agent')return;const old=a.boundDevice;if(old&&old!==s.device&&!['Owner','Creator','Admin'].includes(accountRecord()?.accountType))return toast('Device replacement requires Owner/Admin approval.');a.boundDevice=s.device;a.deviceApprovedAt=new Date().toISOString();}return platformApproval(id,action)};
const platformSessionAllowed=sessionAllowed;
sessionAllowed=function(){if(!platformSessionAllowed())return false;if(role==='Agent'){const s=db.sessions.find(s=>s.id===currentDemoSessionId);if(currentAgent()?.boundDevice&&s?.device!==currentAgent().boundDevice)return false}return true};
function targetLevel(a){return a.accountType==='Creator'?4:a.accountType==='Owner'?3:a.accountType==='Admin'||a.role==='Admin'?2:a.role==='Manager'?1:0}
function canControlAccount(a){if(!a||a.id===sessionAccount?.id)return false;if(isCreator())return a.accountType!=='Creator';if(isOwner())return targetLevel(a)<3&&ownedShops().some(s=>s.id===a.storeId);return role==='Admin'&&targetLevel(a)<2&&a.storeId===activeStoreId}
function forceLogoutAccount(id){refreshDirectory();const a=authDirectory.accounts.find(x=>x.id===id);if(!canControlAccount(a))return toast('You cannot sign out this account.');a.sessionVersion=(a.sessionVersion||0)+1;(authDirectory.sessions||[]).filter(s=>s.account===id).forEach(s=>s.revoked=true);if(a.memberId){const data=readStore(a.storeId);if(data){(data.sessions||[]).filter(s=>s.user===a.memberId&&['Approved','Pending'].includes(s.status)).forEach(s=>s.status='Revoked');localStorage.setItem('jioflow.store.'+a.storeId,JSON.stringify(data));if(a.storeId===activeStoreId)db=data}}creatorAudit('Force signed out '+a.email);render();toast('All prototype sessions for this account were revoked.')}
function setPlatformAccountActive(id,on){refreshDirectory();const a=authDirectory.accounts.find(x=>x.id===id);if(!canControlAccount(a))return toast('You cannot change this account.');if(!on)forceLogoutAccount(id);const target=authDirectory.accounts.find(x=>x.id===id);target.active=on;if(a.memberId){const data=readStore(a.storeId);const m=data?.agents.find(m=>m.id===a.memberId);if(m){m.active=on;localStorage.setItem('jioflow.store.'+a.storeId,JSON.stringify(data));if(a.storeId===activeStoreId)db=data}}creatorAudit('Account '+(on?'activated: ':'deactivated: ')+a.email);render()}
function platformAccountsView(){const accounts=authDirectory.accounts.filter(a=>canControlAccount(a));return heading('Account access','Force logout follows the Creator → Owner → Admin hierarchy.')+`<section class="card"><div class="table-wrap"><table><thead><tr><th>User</th><th>Role</th><th>Shop</th><th>Email activation</th><th>Access</th></tr></thead><tbody>${accounts.map(a=>`<tr><td><strong>${esc(a.name)}</strong><br><small>${esc(a.email)}</small></td><td>${esc(a.accountType||a.role)}</td><td>${esc(authDirectory.stores.find(s=>s.id===a.storeId)?.name||'Owner portfolio')}</td><td>${a.emailActivation==='pending'?'<span class="badge orange">Pending verification</span>':a.emailActivation==='demo-confirmed'?'<span class="badge orange">Demo confirmation only</span>':'<span class="small muted">Legacy demo account</span>'}</td><td><div class="row"><button onclick="forceLogoutAccount('${a.id}')">Force logout</button><button onclick="setPlatformAccountActive('${a.id}',${a.active===false})">${a.active===false?'Activate':'Deactivate'}</button>${a.emailActivation==='pending'?`<button onclick="verificationPreview('${a.id}')">Verification preview</button>`:''}</div></td></tr>`).join('')||'<tr><td colspan="5">No subordinate accounts yet.</td></tr>'}</tbody></table></div></section>`}
function creatorView(){if(!isCreator())return empty('Creator access only.');const owners=authDirectory.accounts.filter(a=>a.accountType==='Owner');return heading('Creator panel','One Creator controls platform ownership. Owners manage their own shops.',`<button class="dark" onclick="ownerAccountForm()">${ico('plus')} Create Owner</button>`)+`<div class="stats">${summaryTile('Owners',owners.length,'Independent business owners')}${summaryTile('Shops',authDirectory.stores.filter(s=>!s.platform).length,'Separate CRM workspaces')}${summaryTile('Accounts',authDirectory.accounts.length,'No package account limit')}</div><section class="card"><h2>Owners</h2>${owners.map(a=>`<div class="option-management"><div><strong>${esc(a.name)}</strong><p class="small muted">${esc(a.email)} · ${authDirectory.stores.filter(s=>s.owner===a.id&&!s.platform).length} shops · ${a.emailActivation==='pending'?'Pending verification':a.emailActivation==='demo-confirmed'?'Demo confirmation only':'Existing demo account'}</p></div><button onclick="ownerAccountForm('${a.id}')">Edit</button>${a.emailActivation==='pending'?`<button onclick="verificationPreview('${a.id}')">Verification preview</button>`:''}<button onclick="forceLogoutAccount('${a.id}')">Force logout</button></div>`).join('')||empty('Create the first Owner. Creator can assign shops to them after activation.')}</section>`}
function ownerAccountForm(id){if(!isCreator())return;const a=id?authDirectory.accounts.find(a=>a.id===id&&a.accountType==='Owner'):null;if(id&&!a)return;modal(id?'Edit Owner':'Create Owner','Only Creator can create Owners. Email activation is required for new accounts.',`<form onsubmit="saveOwnerAccount(event,'${id||''}')">${field('Full name','ownerName',a?.name||'','text','required maxlength="100"')}${field('Email','ownerEmail',a?.email||'','email','required')}${field(id?'New password (optional)':'Initial login password','ownerPassword','','password',`${id?'':'required'} minlength="6" autocomplete="new-password"`)}<p class="notice">Email sending is not connected. New accounts stay pending; a labelled verification preview is available for demonstration only.</p>${modalFooter(id?'Save Owner':'Create Owner')}</form>`)}
async function saveOwnerAccount(e,id){e.preventDefault();if(!isCreator()||memberSaving)return;const f=new FormData(e.target),name=f.get('ownerName').trim(),email=f.get('ownerEmail').trim().toLowerCase(),password=f.get('ownerPassword')||'',old=id?authDirectory.accounts.find(a=>a.id===id&&a.accountType==='Owner'):null;if(id&&!old)return;const duplicate=accountByEmail(email);if(duplicate&&duplicate.id!==id)return toast('This email already has an account.');if(!name||!email||(!old||password)&&password.length<6)return toast('Enter a name, valid email and a password of at least 6 characters.');memberSaving=true;try{const a=old||{id:uid(),accountType:'Owner',role:'Admin',active:true,sessionVersion:0,created:new Date().toISOString()};if(password)a.password=await passwordRecord(password);if(!old||a.email!==email)a.emailActivation='pending';Object.assign(a,{name,email});if(!old)authDirectory.accounts.push(a);creatorAudit('Owner account saved: '+email);closeModal();render();toast('Owner saved. Email activation is pending.')}catch(error){toast(error.message)}finally{memberSaving=false}}
function verificationPreview(id){const a=authDirectory.accounts.find(x=>x.id===id);if(!canControlAccount(a)||a.emailActivation!=='pending')return;modal('Email verification preview','DEMO ONLY — no email has been sent and ownership of this mailbox has not been verified.',`<p>Account: <strong>${esc(a.email)}</strong></p><p class="small muted">In production, a single-use, expiring verification link will be emailed to this address. Here you may simulate confirmation to review the panel flow. This does not mark a real email as verified.</p><div class="modal-footer"><button onclick="closeModal()">Cancel</button><button class="primary" onclick="simulateEmailConfirmation('${id}')">Simulate confirmation (demo)</button></div>`)}
function simulateEmailConfirmation(id){const a=authDirectory.accounts.find(x=>x.id===id);if(!canControlAccount(a)||a.emailActivation!=='pending')return;a.emailActivation='demo-confirmed';a.emailVerified=false;creatorAudit('Simulated email confirmation: '+a.email);closeModal();render();toast('Demo confirmation recorded. Real email verification is still not connected.')}
const creatorShell=shell;
shell=function(){let html=creatorShell();if(isCreator()){html=html.replace(/<nav class="nav">[\s\S]*?<\/nav>/,`<nav class="nav"><button onclick="nav('creator')" class="${page==='creator'?'active':''}">${ico('dashboard')} Creator panel</button><button onclick="nav('access')" class="${page==='access'?'active':''}">${ico('customers')} Account access</button><button onclick="nav('stores')" class="${page==='stores'?'active':''}">${ico('stores')} All shops</button><button onclick="nav('team')">${ico('customers')} Shop users</button><button onclick="nav('admins')">${ico('customers')} Shop Admins</button><button onclick="nav('settings')">${ico('settings')} Key settings</button></nav>`);html=html.replace('<small>Admin</small>','<small>Creator</small>');const shops=authDirectory.stores.filter(s=>!s.platform&&s.active);html=html.replace('<div class="top-actions">',`<div class="top-actions">${shops.length?`<select aria-label="Open shop as Creator" onchange="creatorOpenShop(this.value)"><option value="">Open shop…</option>${shops.map(s=>`<option value="${s.id}">${esc(s.name)}</option>`).join('')}</select>`:''}`)}else if(role==='Admin'){html=html.replace('<button onclick="nav(\'settings\')"',`<button onclick="nav('access')" class="${page==='access'?'active':''}">${ico('logout')} Account access</button><button onclick="nav('settings')"`)}return html};
function creatorOpenShop(id){if(!isCreator())return;const s=authDirectory.stores.find(s=>s.id===id&&!s.platform&&s.active);if(!s)return;loadStore(id);sessionAccount.storeId=id;page='dashboard';render()}
const creatorStores=storesView;
storesView=function(){if(!isCreator())return creatorStores();return heading('All shops','Creator can inspect every shop; Owners manage their portfolios.')+`<div class="shop-list">${authDirectory.stores.filter(s=>!s.platform).map(s=>`<section class="card"><h2>${esc(s.name)}</h2><p class="small muted">Owner: ${esc(authDirectory.accounts.find(a=>a.id===s.owner)?.name||'Legacy owner')}</p>${badge(s.active?'Active':'Inactive')}<button onclick="creatorOpenShop('${s.id}')">Open shop</button></section>`).join('')||empty('Creator creates and assigns shops to Owners.')}</div>`};
const creatorManageUsers=canManageUsers;
canManageUsers=function(){return isCreator()||creatorManageUsers()};
const creatorUserRoles=userRoles;
userRoles=function(){return isCreator()?['Admin','Manager','Agent']:creatorUserRoles()};
const creatorAdminView=adminAccountsView;
adminAccountsView=function(){if(!isCreator())return creatorAdminView();return heading('Shop Admins','Open a shop to manage its Admins.',`<button onclick="adminAccountForm()">Add Admin</button>`)+platformAccountsView()};
const creatorAdminForm=adminAccountForm;
adminAccountForm=function(id){if(!isCreator())return creatorAdminForm(id);const a=agent(id)||{};if(authDirectory.stores.find(s=>s.id===activeStoreId)?.platform)return toast('Open an Owner shop first.');modal(id?'Edit Admin':'Create Admin','Creator account · selected shop.',`<form onsubmit="saveAdminAccount(event,'${id||''}')">${field('Full name','adminName',a.name||'','text','required')}${field('Email','adminEmail',a.email||'','email','required')}${field(id?'New password (optional)':'Login password','adminPassword','','password',`${id?'':'required'} minlength="6"`)}${modalFooter('Save Admin')}</form>`)};
const creatorSaveAdmin=saveAdminAccount;
saveAdminAccount=async function(e,id){if(!isOwner()&&!isCreator()){e.preventDefault();return;}const f=new FormData(e.target),email=f.get('adminEmail').trim().toLowerCase(),old=accountByEmail(email);await creatorSaveAdmin(e,id);const a=accountByEmail(email);if(a&&(!old||old.email!==email)){a.emailActivation='pending';a.emailVerified=false;persistAuth();render();toast('Admin created. Email activation is pending.')}};
const creatorSettings=settingsView;
settingsView=function(){let html=creatorSettings();if(isOwner()&&!creatorExists())html+=`<section class="card section-gap"><h2>Complete platform setup</h2><p class="small muted">This browser has existing Owner data and no Creator. Convert your current primary account to the only Creator, preserving existing shops and data.</p><button class="primary" onclick="promoteExistingCreator()">Make this primary account the Creator</button></section>`;if(isCreator()||isOwner())html+=`<section class="card section-gap"><h2>Key access settings</h2><p class="small muted">Owner management: Creator only. Shop creation: Creator only. Admin management: Creator or the assigned Owner. Owners cannot control Creator or another Owner. Admins cannot control Owners.</p><p class="notice">Real email verification, cross-device revocation and device attestation require a server. Prototype verification is clearly labelled and never marks an email as truly verified.</p></section>`;else html=html.replace(/<section class="card"><h2>Demo data<\/h2>[\s\S]*?<\/section>/,'');return html};
const creatorReset=resetDemo;
resetDemo=function(){if(!isCreator()&&!isOwner())return toast('Only Creator or the shop Owner can reset shop data.');return creatorReset()};
const creatorToggleStore=toggleStoreAccount;
toggleStoreAccount=function(i){if(!isCreator()&&!isOwner())return toast('Shop security settings are restricted.');const s=authDirectory.stores[i];if(!s||!isCreator()&&s.owner!==sessionAccount.id)return;return creatorToggleStore(i)};
const platformRender=render;
render=function(){if(signedIn){const a=accountRecord(),saved=JSON.parse(sessionStorage.getItem('jioflow.platform.session')||'null'),s=authDirectory.sessions?.find(x=>x.id===saved?.id);if(a&&(a.active===false||saved&&(!s||s.revoked||saved.version!==(a.sessionVersion||0)))){signOut();toast('Your session has been signed out. Please contact your account administrator.');return}if(['creator'].includes(page)&&!isCreator())page='dashboard';if(page==='access'&&role!=='Admin')page='dashboard';if(isCreator()&&typeof creatorSelectedShop!=='undefined'&&creatorSelectedShop!=='all'&&page==='dashboard'&&authDirectory.stores.find(s=>s.id===activeStoreId)?.platform)page='creator'}platformRender()};
if(!globalThis.__JIOFLOW_TEST__)window.addEventListener('storage',e=>{if(e.key==='jioflow.auth.v1'){refreshDirectory();if(signedIn)render()}});
// Restrained original palette: black profit, brand green confirmed, ash elsewhere.
const neutralCardsRender=render;
render=function(){neutralCardsRender();if(!signedIn||!sessionAllowed())return;$('#view')?.querySelectorAll('.metric-tile,.insight-tile,.stat,.overview-tile').forEach(el=>{const label=el.querySelector('.label,.tile-label')?.textContent?.trim().toLowerCase()||'';el.dataset.tone='neutral';el.classList.toggle('brand-confirmed',/^confirmed( orders)?$/.test(label))})};

ownedShops=function(){return authDirectory.stores.filter(s=>s.owner===sessionAccount?.id&&!s.platform)};
function profileAccessLabels(){if(isCreator())return ['Creator panel','Owners','All shops','Account access','Key settings'];if(isOwner())return ['Dashboard','Shops','Admin Management','Users','Orders','Products','Profit','Settings','Account access'];if(role==='Admin')return ['Dashboard','Orders','Products','Users','Profit','Settings','Staff access'];if(role==='Agent')return ['My Dashboard','Processing','Permanent Clients','My Profile'];return ['Dashboard',...Object.entries({assign:'Customer distribution',booking:'Orders & couriers',products:'Products',import:'Order Import',profit:'Profit & reports',settings:'Settings'}).filter(([k])=>permitted(k)).map(([,v])=>v),'My Profile']}
profileView=function(){const a=accountRecord();if(!a)return empty('Login to view your profile.');return heading('My Profile','Update your own details and password. Access is controlled by your account administrator.')+`<form class="settings-stack profile-stack" onsubmit="saveMyProfile(event)"><section class="card"><h2>${ico('customers')} Account Details</h2><div class="form-grid">${field('Full name','profileName',a.name,'text','required maxlength="100"')}${field('Email','profileEmail',a.email,'email','readonly autocomplete="email"')}</div><p class="small muted">Role: ${esc(a.accountType||a.role)} · ${esc(db.settings.storeName)}</p><p class="small muted">${a.emailActivation==='pending'?'Email activation pending':a.emailActivation==='demo-confirmed'?'Demo email confirmation only — real verification is not connected.':'Email changes require the verification service.'}</p></section><section class="card"><h2>${ico('settings')} Change Password</h2><p class="small muted">Leave blank to keep your current password.</p>${field('Current password','profileCurrent','','password','autocomplete="current-password"')}<div class="form-grid">${field('New password','profileNew','','password','minlength="6" autocomplete="new-password"')}${field('Confirm new password','profileConfirm','','password','minlength="6" autocomplete="new-password"')}</div><label class="permission"><input type="checkbox" onchange="document.querySelectorAll('#profileCurrent,#profileNew,#profileConfirm').forEach(el=>el.type=this.checked?'text':'password')">Show passwords</label></section><div><button class="primary">Save Changes</button></div><section class="card"><h3>Your Access</h3><div class="tags">${profileAccessLabels().map(label=>`<span class="badge green">${esc(label)}</span>`).join('')}</div><p class="small muted">These permissions cannot be changed from your profile. Contact your account administrator for access changes.</p></section></form>`};
async function saveMyProfile(e){e.preventDefault();const a=accountRecord();if(!a)return;const f=new FormData(e.target),name=f.get('profileName').trim(),password=f.get('profileNew')||'',confirm=f.get('profileConfirm')||'';if(!name)return toast('Enter your full name.');if(password||confirm){if(password.length<6)return toast('Use at least 6 characters.');if(password!==confirm)return toast('Passwords do not match.');if(!await passwordMatches(f.get('profileCurrent'),a.password))return toast('Current password is incorrect.');a.password=await passwordRecord(password)}a.name=name;sessionAccount.name=name;if(a.memberId){const member=agent(a.memberId);if(member)member.name=name;save()}persistAuth();render();toast('Profile saved.')}
accountInfo=function(){const existing=document.getElementById('account-dropdown');if(existing){existing.remove();return}const a=accountRecord();const box=document.createElement('div');box.id='account-dropdown';box.className='account-dropdown';box.innerHTML=`<strong>${esc(a?.name||sessionAccount?.name)}</strong><small>${esc(a?.email||'')}</small><hr><button onclick="document.getElementById('account-dropdown')?.remove();nav('profile')">${ico('customers')} My Profile</button><button class="danger" onclick="signOut()">${ico('logout')} Sign out</button>`;$('.top-actions')?.append(box)};
const profileDetailsSave=saveOwnDetails;
saveOwnDetails=function(e){const f=new FormData(e.target);if(f.get('accountEmail').trim().toLowerCase()!==accountRecord()?.email){e.preventDefault();return toast('Email changes require the verified-email backend. Your existing email is preserved.')}return profileDetailsSave(e)};
// Only the platform Creator provisions shops; each shop is assigned to one Owner.
shopForm=function(){if(!isCreator())return toast('Only Creator can create shops.');const owners=authDirectory.accounts.filter(a=>a.accountType==='Owner'&&a.active!==false);if(!owners.length)return toast('Create an Owner account first.');modal('Create shop','Assign this independent CRM workspace to its Owner.',`<form onsubmit="createShop(event)">${field('Shop name','shopName','','text','required maxlength="100"')}<div class="field"><label for="shopOwner">Shop Owner</label><select name="shopOwner" id="shopOwner" required>${owners.map(a=>`<option value="${a.id}">${esc(a.name)} · ${esc(a.email)}</option>`).join('')}</select></div>${modalFooter('Create shop')}</form>`)};
createShop=function(e){e.preventDefault();if(!isCreator())return toast('Only Creator can create shops.');const f=new FormData(e.target),name=String(f.get('shopName')||'').trim(),owner=authDirectory.accounts.find(a=>a.id===f.get('shopOwner')&&a.accountType==='Owner'&&a.active!==false);if(!name||!owner)return toast('Enter a shop name and choose an active Owner.');const id='JF-'+uid().slice(0,8).toUpperCase();authDirectory.stores.push({id,name,owner:owner.id,active:true});localStorage.setItem('jioflow.store.'+id,JSON.stringify(blankStore(name)));creatorAudit('Shop created: '+name+' for '+owner.email);closeModal();creatorOpenShop(id);toast('Shop created and assigned to its Owner.')};
const provisionedStores=storesView;
storesView=function(){if(isCreator()){let html=provisionedStores();return html.replace('Owners manage their portfolios.','Owners manage their assigned portfolios.').replace('<div class="shop-list">',`<button class="dark section-gap" onclick="shopForm()">${ico('plus')} Create shop</button><div class="shop-list section-gap">`)}if(!isOwner())return empty('Only Creator and Owner can view shop portfolios.');return heading('Your shops','Your Creator assigns shops to you. Each shop has its own users, customers, orders and reports.')+`<div class="shop-list">${ownedShops().map(s=>`<section class="card"><h2>${esc(s.name)}</h2>${badge(s.active?'Active':'Inactive')}<button onclick="switchShop('${s.id}')">${s.id===activeStoreId?'Current shop':'Open shop'}</button></section>`).join('')||empty('No shop assigned yet. Ask your Creator to create and assign a shop.')}</div>`};
function enhancePasswordFields(){document.querySelectorAll('input[type="password"]').forEach(input=>{if(input.dataset.visibilityReady)return;input.dataset.visibilityReady='true';const row=document.createElement('div');row.className='password-control';input.parentNode.insertBefore(row,input);row.append(input);const button=document.createElement('button');button.type='button';button.className='password-visibility';button.textContent='Show';button.setAttribute('aria-label','Show password');button.setAttribute('aria-pressed','false');if(input.id)button.setAttribute('aria-controls',input.id);button.addEventListener('click',()=>{const show=input.type==='password';input.type=show?'text':'password';button.textContent=show?'Hide':'Show';button.setAttribute('aria-label',show?'Hide password':'Show password');button.setAttribute('aria-pressed',String(show))});row.append(button)})}
if(!globalThis.__JIOFLOW_TEST__){new MutationObserver(enhancePasswordFields).observe(document.body,{childList:true,subtree:true});enhancePasswordFields()}
function ownAgentShipments(){return visibleOrders().filter(o=>o.tracking&&o.agent===agentId&&(o.enteredBy?o.enteredBy===sessionAccount?.id:o.entryAgent?o.entryAgent===agentId:o.status!=='Imported'&&o.source!=='CSV Import')&&(!o.bookedBy||o.bookedBy===sessionAccount?.id))}
const allCourierView=courierView;
courierView=function(){if(role!=='Agent')return allCourierView();const orders=ownAgentShipments();return heading('Courier Tracking','Only your own entered and booked orders appear here.',`<button onclick="nav('new')">${ico('plus')} New Order</button>`)+`<div class="notice">Courier APIs are not connected. This prototype displays recorded demo tracking and shipment statuses.</div><div class="stats">${['Booked','In Transit','Delivered','Returned'].map(status=>summaryTile(status,orders.filter(o=>o.shipment===status).length,'Your courier shipments')).join('')}</div><section class="card"><h2>${ico('courier')} My shipments</h2><div class="table-wrap"><table><thead><tr><th>Order / tracking</th><th>Customer</th><th>Products</th><th>Courier</th><th>Delivery status</th><th></th></tr></thead><tbody>${orders.map(o=>`<tr><td><strong>${esc(o.id)}</strong><br><small>${esc(o.tracking)}</small></td><td>${esc(customer(o.customer)?.name)}<br><small>${esc(customer(o.customer)?.phone)}</small></td><td>${o.items.map(x=>esc(product(x.product)?.name||x.name)+' × '+x.qty).join('<br>')}</td><td>${esc(o.courier)}</td><td>${badge(o.shipment)}</td><td><button onclick="showOrder('${o.id}')">View timeline</button></td></tr>`).join('')||'<tr><td colspan="6">No courier bookings entered by you yet.</td></tr>'}</tbody></table></div></section>`};
const agentProfileLabels=profileAccessLabels;
profileAccessLabels=function(){return role==='Agent'?['My Dashboard','Processing','All Orders','New Order','Courier Tracking','Permanent Clients','My Profile']:agentProfileLabels()};

'use strict';
let creatorSelectedShop=localStorage.getItem('jioflow.creator.selectedShop')||'',shopsExpanded=false,platformDetail='orders',platformPeopleType='Owner',chartSource='All';
function businessStores(){return authDirectory.stores.filter(s=>!s.platform)}
function ownerBusiness(){const a=accountRecord();return businessStores().find(s=>s.owner===a?.id&&(s.id===a.businessId||s.id===a.storeId))||businessStores().find(s=>s.owner===a?.id)}
ownedShops=function(){const shop=ownerBusiness();return shop?[shop]:[]};
function chooseBusiness(id){if(!isCreator())return toast('Only Creator can switch businesses.');if(id!=='all'&&!businessStores().some(s=>s.id===id&&s.active))return;const previousPage=page;creatorSelectedShop=id;localStorage.setItem('jioflow.creator.selectedShop',id);if(id!=='all'){loadStore(id);sessionAccount.storeId=id;}selected.clear();cart=[];chartSource='All';query='';subtab='All';tagFilter='';pageNo=1;window.callFilter='';window.responseFilter='';window.funnelFilter='';window.customerSource='';reportAgentId='';reportPage=1;reportSearch='';page=previousPage==='agentdetail'?'agentreports':previousPage;closeModal();render()}

creatorOpenShop=chooseBusiness;
switchShop=function(){toast('Your account is restricted to its assigned business.')};
function toggleShopNavigation(){shopsExpanded=!shopsExpanded;if(!creatorSelectedShop)page='stores';render()}
const refinedStart=startAccountSession;
startAccountSession=function(a,opts){refinedStart(a,opts);if(isCreator()){const shop=businessStores().find(s=>s.id===creatorSelectedShop&&s.active);if(shop){loadStore(shop.id);sessionAccount.storeId=shop.id}}else if(isOwner()){const shop=ownerBusiness();if(shop){loadStore(shop.id);sessionAccount.storeId=shop.id;page='dashboard'}else page='dashboard'}render()};
const refinedShell=shell;
shell=function(){let html=refinedShell();if(isCreator()){const shop=creatorSelectedShop==='all'?{name:'All Shops'}:businessStores().find(s=>s.id===creatorSelectedShop);const local=[['dashboard','Dashboard'],['customers','Follow-ups'],['orders','All Orders'],['new','New Order'],['import','Order Import'],['products','Products'],['courier','Couriers'],['profit','Profit'],['agentreports','Agent Reports'],['team','Users & groups'],['admins','Shop Admins'],['settings','Workspace Settings']];const item=(id,title)=>`<button onclick="nav('${id}')" class="${page===id?'active':''}">${ico(id==='team'||id.startsWith('platform')?'customers':id==='settings'?'settings':id)}${title}</button>`;html=html.replace(/<nav class="nav">[\s\S]*?<\/nav>/,`<nav class="nav">${item('creator','Dashboard')}${item('owners','Owners')}${item('platformadmins','Admins')}${item('platformagents','Agents')}<button onclick="toggleShopNavigation()" class="${page==='stores'?'active':''}">${ico('stores')} Shops ${ico('down')}</button><div class="shop-subnav ${shopsExpanded?'expanded':''}">${shop?`<div class="selected-shop-label">${esc(shop.name)}</div>${local.map(([id,title])=>item(id,title)).join('')}`:'<p class="small muted">Select a shop to open its workspace.</p>'}<button onclick="nav('stores')">${ico('stores')} Manage shops</button></div>${item('platformsettings','Platform settings')}${item('access','Account access')}</nav>`);html=html.replace(/<select aria-label="Open shop as Creator"[\s\S]*?<\/select>/,`<select aria-label="Select business" onchange="chooseBusiness(this.value)"><option value="all" ${creatorSelectedShop==='all'?'selected':''}>All Shops</option><option value="">Select business…</option>${businessStores().filter(s=>s.active).map(s=>`<option value="${s.id}" ${s.id===creatorSelectedShop?'selected':''}>${esc(s.name)}</option>`).join('')}</select>`);html=html.replace('<div class="searchbox">',`<div class="business-context"><small>${shop?'Current business':'Platform overview'}</small><strong>${esc(shop?.name||'All businesses')}</strong></div><div class="searchbox">`)}else if(isOwner()){html=html.replace(/<button onclick="nav\('stores'\)"[^>]*>[\s\S]*?<\/button>/g,'').replace(/<select aria-label="Switch shop"[\s\S]*?<\/select>/,'');html=html.replace('<div class="searchbox">',`<div class="business-context"><small>Your business</small><strong>${esc(ownerBusiness()?.name||'Awaiting assignment')}</strong></div><div class="searchbox">`)}return html.replace('<div class="brand">','<a class="brand brand-home" href="#'+(isCreator()?'creator':'dashboard')+'" aria-label="JioFlow home">').replace('</em></span></div><div class="eyebrow">','</em></span></a><div class="eyebrow">')};
const refinedShopCreate=createShop;
createShop=function(e){if(!isCreator()){e.preventDefault();return toast('Only Creator can create shops.')}const f=new FormData(e.target),owner=f.get('shopOwner');if(businessStores().some(s=>s.owner===owner)){e.preventDefault();return toast('This Owner already has a business. Create a separate Owner for another business.')}return refinedShopCreate(e)};
const refinedShopForm=shopForm;
shopForm=function(){if(!isCreator())return;const available=authDirectory.accounts.filter(a=>a.accountType==='Owner'&&a.active!==false&&!businessStores().some(s=>s.owner===a.id));if(!available.length)return toast('Create an Owner without a business first.');refinedShopForm();const select=$('#shopOwner');if(select)select.innerHTML=available.map(a=>`<option value="${a.id}">${esc(a.name)} · ${esc(a.email)}</option>`).join('')};
storesView=function(){if(!isCreator())return empty('Only Creator can access Shops.');return heading('Shops','Each Owner accesses one assigned business. Creator can open every workspace.',`<button class="dark" onclick="shopForm()">${ico('plus')} Create shop</button>`)+`<div class="shop-list">${businessStores().map(s=>{const data=s.id===activeStoreId?db:readStore(s.id),orders=data?.orders||[];return `<section class="card shop-card"><div class="row between"><div><h2>${s.logo?`<img class="shop-logo" src="${esc(s.logo)}" alt="Business logo">`:ico('stores')}${esc(s.name)}</h2><p class="small muted">${esc(authDirectory.accounts.find(a=>a.id===s.owner)?.name||'Owner')}</p></div>${badge(s.active?'Active':'Inactive')}</div><div class="compact-user-stats"><span>${orders.length} orders</span><span>${data?.agents.filter(a=>!a.archived).length||0} users</span></div><button class="primary" onclick="chooseBusiness('${s.id}')">Open workspace ${ico('arrow')}</button></section>`}).join('')||empty('Create a shop and assign its Owner.')}</div>`};
function platformShopRows(){return businessStores().map(s=>{const data=s.id===activeStoreId?db:readStore(s.id);return {s,data:data||blankStore(s.name)}})}
function platformMetrics(){const rows=platformShopRows(),orders=rows.flatMap(r=>r.data.orders.filter(inRange).map(o=>({...o,nativeStatus:o.status,status:['Confirmed','Confirm',r.data.settings.confirmStatus].filter(Boolean).includes(o.status)?'Confirmed':o.status,shopId:r.s.id}))),confirmed=orders.filter(o=>confirmedStatus(o.status)),cs=rows.flatMap(r=>r.data.customers),completed=cs.filter(c=>c.call&&!pendingStatus(c.status)).length,revenue=sumBy(confirmed,orderTotal);let profit=0,missing=false;for(const {data} of rows){for(const o of data.orders.filter(inRange).filter(o=>['Confirmed','Confirm',data.settings.confirmStatus].filter(Boolean).includes(o.status))){const gross=sumBy(o.items,x=>x.qty*x.price),costs=o.items.map(x=>x.cost??data.products.find(p=>p.id===x.product)?.cost);if(costs.some(x=>x==null))missing=true;profit+=gross-Number(o.discount||0)+Number(o.delivery||0)-sumBy(o.items,(x)=>x.qty*(x.cost??data.products.find(p=>p.id===x.product)?.cost??0))-Number(o.finance?.courierCost??o.delivery)-Number(o.finance?.codFee||0)-Number(o.finance?.packaging||0)-Number(o.finance?.returnFee||0)}}return {rows,orders,confirmed,completed,customers:cs.length,revenue,profit:missing?null:profit}}
creatorView=function(){if(!isCreator())return empty('Creator access only.');const m=platformMetrics(),owners=authDirectory.accounts.filter(a=>a.accountType==='Owner'),admins=authDirectory.accounts.filter(a=>a.accountType==='Admin'),agents=authDirectory.accounts.filter(a=>a.role==='Agent');return heading('Platform Dashboard','A complete overview across all businesses. Select a box to open its details.',rangeSelect())+`<div class="stats platform-summary">${summaryTile('Shops',m.rows.length,'Independent businesses',"nav('stores')")}${summaryTile('Owners',owners.length,'Business owners',"nav('owners')")}${summaryTile('Admins',admins.length,'Shop administrators',"nav('platformadmins')")}${summaryTile('Agents',agents.length,'Sales team accounts',"nav('platformagents')")}${summaryTile('Confirmed orders',m.confirmed.length,'Selected reporting period',"openPlatformDetail('confirmed')")}${summaryTile('Completed',m.completed,'Current completed profiles',"openPlatformDetail('completed')")}${summaryTile('Revenue',money(m.revenue),'Confirmed sales across all shops',"openPlatformDetail('revenue')")}${summaryTile('Net profit',m.profit===null?'Cost missing':money(m.profit),'Recorded costs and fees',"openPlatformDetail('profit')")}${summaryTile('All orders',m.orders.length,'Selected reporting period',"openPlatformDetail('orders')")}${summaryTile('Delivered',m.orders.filter(o=>o.shipment==='Delivered').length,'Completed courier deliveries',"openPlatformDetail('delivered')")}${summaryTile('Returned',m.orders.filter(o=>o.shipment==='Returned').length,'Returned courier parcels',"openPlatformDetail('returned')")}${summaryTile('Customers',m.customers,'Current profiles in all businesses',"openPlatformDetail('customers')")}</div><div class="insight-grid"><section class="card"><h2>Business overview</h2>${horizontalVisual(m.rows.map(r=>({label:r.s.name,value:r.data.orders.filter(inRange).length,action:`chooseBusiness('${r.s.id}')`})),'count',true)}</section><section class="card"><h2>Account distribution</h2>${ringVisual([{label:'Owners',value:owners.length},{label:'Admins',value:admins.length},{label:'Agents',value:agents.length}],'accounts')}</section></div>${confirmedChart(m.orders)}`};
function openPlatformDetail(type){if(!isCreator())return;platformDetail=type;nav('platformdetail')}
function platformDetailView(){if(!isCreator())return empty('Creator access only.');const m=platformMetrics();return heading('Business details · '+platformDetail,'Open any business for the complete workspace.',`<button onclick="nav('creator')">Back to dashboard</button>`)+`<section class="card"><div class="table-wrap"><table><thead><tr><th>Business</th><th>Orders</th><th>Confirmed</th><th>Completed profiles</th><th>Revenue</th><th></th></tr></thead><tbody>${m.rows.map(({s,data})=>{const os=data.orders.filter(inRange),confirmed=os.filter(o=>confirmedStatus(o.status));return `<tr><td>${esc(s.name)}</td><td>${os.length}</td><td>${confirmed.length}</td><td>${data.customers.filter(c=>c.call&&!pendingStatus(c.status)).length}</td><td>${money(sumBy(confirmed,orderTotal))}</td><td><button onclick="chooseBusiness('${s.id}')">View business</button></td></tr>`}).join('')||'<tr><td colspan="6">No shops yet.</td></tr>'}</tbody></table></div></section>`}
function platformDirectoryView(type){if(!isCreator())return empty('Creator access only.');const accounts=authDirectory.accounts.filter(a=>(type==='Agent'?['Agent','Manager'].includes(a.role):a.accountType===type)&&accountMatchesSelectedShop(a));return heading(type==='Owner'?'Owners':type==='Admin'?'Admins':'Agents & Managers',creatorSelectedShop&&creatorSelectedShop!=='all'?'Accounts in '+(businessStores().find(s=>s.id===creatorSelectedShop)?.name||'selected shop')+'.':'Accounts across all businesses.',type==='Owner'?'<button class="dark" onclick="ownerAccountForm()">'+ico('plus')+' Create Owner</button>':'<button onclick="platformStaffCreate()">'+ico('plus')+' Add '+type+'</button>')+`<section class="card"><div class="table-wrap"><table><thead><tr><th>Account</th><th>Role / business</th><th>Phone</th><th>Activation</th><th>Actions</th></tr></thead><tbody>${accounts.map(a=>`<tr><td><div class="row">${accountAvatar(a)}<div><strong>${esc(a.name)}</strong><small class="account-email">${esc(a.email)}</small></div></div></td><td>${esc(a.accountType||a.role)}<br><small>${esc(businessStores().find(s=>s.id===a.storeId||s.owner===a.id)?.name||'Not assigned')}</small></td><td>${esc(a.phone||'—')}</td><td>${esc(a.emailActivation==='pending'?'Pending verification':a.emailActivation==='demo-confirmed'?'Demo confirmation':a.active===false?'Inactive':'Active')}</td><td><div class="row"><button onclick="accountEditor('${a.id}')">Edit</button><button onclick="forceLogoutAccount('${a.id}')">Logout</button><button onclick="recoveryForAccount('${a.id}')">Reset email</button>${a.emailActivation==='pending'?`<button onclick="verificationPreview('${a.id}')">Verify preview</button>`:''}</div></td></tr>`).join('')||'<tr><td colspan="5">No accounts in this section.</td></tr>'}</tbody></table></div></section>`}
function platformStaffCreate(){if(!isCreator())return;if(!creatorSelectedShop)return toast('Select the business from the top bar first.');if(page==='platformadmins')adminAccountForm();else agentForm()}
function platformSettingsView(){if(!isCreator())return empty('Creator access only.');return heading('Platform settings','Creator ownership, access rules and recovery status.')+`<section class="card"><h2>Creator account</h2><p>${esc(accountRecord()?.email)}</p><button onclick="nav('profile')">Edit my profile</button></section><section class="card section-gap"><h2>Access policy</h2><p class="small muted">Creator creates Owners and shops. Owners access one assigned business. Admins manage staff in their shop. Agent approval binds one browser installation at a time.</p><p class="notice">Email verification, email password recovery and cross-device session enforcement require the backend connection. This browser prototype cannot send email.</p></section>`}
function accountAvatar(a){return a?.image?`<img class="avatar account-image" src="${esc(a.image)}" alt="${esc(a.name)}">`:`<span class="avatar">${initials(a?.name)}</span>`}
function imageUploadField(label,name,existing=''){return `<div class="field image-field"><label for="${name}">${label}</label><div class="image-picker">${existing?`<img src="${esc(existing)}" alt="Current image" class="image-preview">`:ico('customers')}<input id="${name}" name="${name}" type="file" accept="image/png,image/jpeg,image/webp" onchange="previewPickedImage(this)"></div><small class="muted">PNG, JPG or WebP · up to 1 MB · optional</small><label class="permission"><input type="checkbox" name="${name}Remove">Remove current image</label></div>`}
function previewPickedImage(input){const file=input.files?.[0];if(!file)return;if(file.size>1048576||!['image/png','image/jpeg','image/webp'].includes(file.type)){input.value='';return toast('Choose a PNG, JPG or WebP image up to 1 MB.')}const reader=new FileReader();reader.onload=()=>{let img=input.parentElement.querySelector('img');if(!img){img=document.createElement('img');img.className='image-preview';input.parentElement.prepend(img)}img.src=reader.result;img.alt='Selected image preview'};reader.readAsDataURL(file)}
async function selectedImage(form,name,existing=''){if(form.has(name+'Remove'))return '';const file=form.get(name);if(!file||typeof file==='string'||!file.size)return existing;if(file.size>1048576||!['image/png','image/jpeg','image/webp'].includes(file.type))throw Error('Choose a PNG, JPG or WebP image up to 1 MB.');return await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('Image could not be read.'));reader.readAsDataURL(file)})}
let accountEditing=false;
function accountEditor(id){const a=authDirectory.accounts.find(x=>x.id===id);if(!a||!canControlAccount(a))return toast('This account is outside your permissions.');modal('Edit '+(a.accountType||a.role),'Update contact details and login information. Role and business ownership stay protected.',`<form onsubmit="saveManagedAccount(event,'${id}')"><div class="form-grid">${field('Full name','managedName',a.name,'text','required maxlength="100"')}${field('Email','managedEmail',a.email,'email','required')}${field('Phone','managedPhone',a.phone||'','tel','maxlength="25"')}${field('Job title (optional)','managedTitle',a.title||'','text','maxlength="80"')}${field('Address (optional)','managedAddress',a.address||'','text','maxlength="200"')}${field('User code (optional)','managedCode',a.code||'','text','maxlength="30"')}</div>${imageUploadField('Profile image','managedImage',a.image||'')}${field('New password (optional)','managedPassword','','password','minlength="6" autocomplete="new-password"')}<p class="small muted">Leave password blank to keep it. Changing an Owner/Admin email resets email activation. Recovery emails require the backend connection.</p>${modalFooter('Save account')}</form>`)}
async function saveManagedAccount(e,id){e.preventDefault();if(accountEditing)return;let a=authDirectory.accounts.find(x=>x.id===id);if(!canControlAccount(a))return;const f=new FormData(e.target),email=f.get('managedEmail').trim().toLowerCase(),password=f.get('managedPassword')||'',duplicate=accountByEmail(email);if(duplicate&&duplicate.id!==id)return toast('Email already belongs to another account.');if(password&&password.length<6)return toast('Use at least 6 characters.');accountEditing=true;try{const image=await selectedImage(f,'managedImage',a.image||''),record=password?await passwordRecord(password):a.password,changed=email!==a.email;Object.assign(a,{name:f.get('managedName').trim(),email,phone:f.get('managedPhone').trim(),title:f.get('managedTitle').trim(),address:f.get('managedAddress').trim(),code:f.get('managedCode').trim(),image,password:record});if(changed&&['Admin','Owner'].includes(a.accountType)){a.emailActivation='pending';a.emailVerified=false}if(a.memberId){const data=readStore(a.storeId),m=data?.agents.find(x=>x.id===a.memberId);if(m){Object.assign(m,{name:a.name,email:a.email,phone:a.phone,code:a.code,image:a.image});localStorage.setItem('jioflow.store.'+a.storeId,JSON.stringify(data));if(a.storeId===activeStoreId)db=data}}persistAuth();if(password||changed)forceLogoutAccount(id);creatorAudit('Account details updated: '+email);closeModal();render();toast('Account updated.')}catch(error){toast(error.message)}finally{accountEditing=false}}
function recoveryForAccount(id){const a=authDirectory.accounts.find(x=>x.id===id);if(!canControlAccount(a))return;passwordRecoveryDialog(a.email)}
function passwordRecoveryDialog(email=''){modal('Forgot password','Password recovery is by email.',`<form onsubmit="requestRecovery(event)">${field('Account email','recoveryEmail',email,'email','required')}<p class="notice">Email delivery is not connected in this browser prototype. Submitting records a local recovery request; no email is sent and no password is changed.</p>${modalFooter('Request recovery email')}</form>`)}
function requestRecovery(e){e.preventDefault();const email=new FormData(e.target).get('recoveryEmail').trim().toLowerCase();authDirectory.recoveryRequests||=[];authDirectory.recoveryRequests.push({email,at:new Date().toISOString(),status:'Backend not connected'});persistAuth();closeModal();toast('Recovery request recorded locally. No email was sent; backend connection is required.')}
const recoveryGateway=accountGateway;
accountGateway=function(){recoveryGateway();const form=$('.login-box form');if(form&&authDirectory.accounts.length)form.insertAdjacentHTML('afterend','<button class="forgot-password" type="button" onclick="passwordRecoveryDialog()">Forgot password?</button>')};
const richerProfile=profileView;
profileView=function(){const html=richerProfile(),a=accountRecord();return html.replace('<p class="small muted">Role:',`<div class="form-grid">${field('Phone','profilePhone',a?.phone||'','tel','maxlength="25"')}${field('Job title (optional)','profileTitle',a?.title||'','text','maxlength="80"')}${field('Address (optional)','profileAddress',a?.address||'','text','maxlength="200"')}</div>${imageUploadField('Profile image','profileImage',a?.image||'')}<p class="small muted">Role:`)};
const richerSaveProfile=saveMyProfile;
saveMyProfile=async function(e){e.preventDefault();const a=accountRecord();if(!a)return;const f=new FormData(e.target),password=f.get('profileNew')||'',confirm=f.get('profileConfirm')||'';if(password||confirm){if(password.length<6||password!==confirm)return toast('Enter matching passwords of at least 6 characters.');if(!await passwordMatches(f.get('profileCurrent'),a.password))return toast('Current password is incorrect.')}try{const image=await selectedImage(f,'profileImage',a.image||'');Object.assign(a,{phone:String(f.get('profilePhone')||'').trim(),title:String(f.get('profileTitle')||'').trim(),address:String(f.get('profileAddress')||'').trim(),image});persistAuth();if(a.memberId){const member=agent(a.memberId);if(member){Object.assign(member,{phone:a.phone,image:a.image});save()}}await richerSaveProfile(e)}catch(error){toast(error.message)}};
function shopDetailsFields(shop={}){return `<div class="form-grid">${field('Business name','businessName',shop.name||'','text','required maxlength="100"')}${field('Business email','businessEmail',shop.email||'','email','required')}${field('Contact number','businessPhone',shop.phone||'','tel','required maxlength="25"')}${field('Address (optional)','businessAddress',shop.address||'','text','maxlength="200"')}${field('Website (optional)','businessWebsite',shop.website||'','url','placeholder="https://example.com"')}</div>${imageUploadField('Business logo','businessLogo',shop.logo||'')}`}
shopForm=function(){if(!isCreator())return;const owners=authDirectory.accounts.filter(a=>a.accountType==='Owner'&&a.active!==false&&!businessStores().some(s=>s.owner===a.id));modal('Create shop','Business details and assigned Owner. Optional fields can be added later.',`<form onsubmit="createShop(event)">${shopDetailsFields()}<div class="field"><label for="shopOwner">Business Owner</label><select id="shopOwner" name="shopOwner"><option value="">Assign Owner later</option>${owners.map(a=>`<option value="${a.id}">${esc(a.name)} · ${esc(a.email)}</option>`).join('')}</select></div>${modalFooter('Create shop')}</form>`)};
createShop=async function(e){e.preventDefault();if(!isCreator()||accountEditing)return;const f=new FormData(e.target),owner=authDirectory.accounts.find(a=>a.id===f.get('shopOwner')&&a.accountType==='Owner'&&a.active!==false),name=String(f.get('businessName')||'').trim();if(!name||!f.get('businessEmail')||!f.get('businessPhone'))return toast('Enter business name, email, number and Owner.');if(owner&&businessStores().some(s=>s.owner===owner.id))return toast('This Owner already has an assigned business.');accountEditing=true;try{const logo=await selectedImage(f,'businessLogo'),id='JF-'+uid().slice(0,8).toUpperCase(),s={id,name,email:f.get('businessEmail').trim(),phone:f.get('businessPhone').trim(),address:String(f.get('businessAddress')||'').trim(),website:String(f.get('businessWebsite')||'').trim(),logo,owner:owner?.id||'',active:true};const data=blankStore(name);Object.assign(data.settings,{businessEmail:s.email,businessPhone:s.phone,businessAddress:s.address,businessWebsite:s.website,logo});localStorage.setItem('jioflow.store.'+id,JSON.stringify(data));authDirectory.stores.push(s);if(owner){owner.businessId=id;owner.storeId=id;}creatorAudit('Shop created: '+name);closeModal();chooseBusiness(id);toast('Shop created and assigned.')}catch(error){toast(error.message)}finally{accountEditing=false}};
function workspaceIdentityPanel(){const shop=businessStores().find(s=>s.id===activeStoreId);if(!shop)return '';return `<section class="card"><h2>Business identity</h2><p class="small muted">These details apply only to ${esc(shop.name)}.</p><form onsubmit="saveBusinessIdentity(event)">${shopDetailsFields(shop)}<button class="primary">Save business details</button></form></section>`}
async function saveBusinessIdentity(e){e.preventDefault();if(!canConfigureShop()||!isCreator()&&!isOwner()&&role!=='Admin')return;const shop=businessStores().find(s=>s.id===activeStoreId);if(!shop||isOwner()&&shop.owner!==sessionAccount.id)return;const f=new FormData(e.target);try{const logo=await selectedImage(f,'businessLogo',shop.logo||'');Object.assign(shop,{name:f.get('businessName').trim(),email:f.get('businessEmail').trim(),phone:f.get('businessPhone').trim(),address:String(f.get('businessAddress')||'').trim(),website:String(f.get('businessWebsite')||'').trim(),logo});Object.assign(db.settings,{storeName:shop.name,businessEmail:shop.email,businessPhone:shop.phone,businessAddress:shop.address,businessWebsite:shop.website,logo});persistAuth();save();render();toast('This business profile was saved.')}catch(error){toast(error.message)}}
const perBusinessSettings=settingsView;
settingsView=function(){const html=perBusinessSettings();if(!canConfigureShop())return html;const at=html.indexOf('<div class="settings-stack">');return at<0?html:html.slice(0,at+28)+workspaceIdentityPanel()+html.slice(at+28)};
function completedProfileSet(cs){return cs.filter(c=>c.call&&!pendingStatus(c.status))}
purchaseStats=function(os,cs){const completed=completedProfileSet(cs),ids=new Set(completed.map(c=>c.id)),buyers=new Set(os.filter(o=>confirmedStatus(o.status)&&ids.has(o.customer)).map(o=>o.customer));return {buyers:buyers.size,completed:completed.length,connected:completed.length,rate:completed.length?buyers.size/completed.length*100:0}};
const completedMetrics=metricSet;
metricSet=function(os,cs){return {...completedMetrics(os,cs),purchase:purchaseStats(os,cs).rate}};
const oldComparisonNumbers=comparisonNumbers;
comparisonNumbers=function(label){const normalized={Sales:'Revenue',Confirmed:'Confirmed Orders','Purchase Rate':'Purchase Rate'}[label]||label;if(normalized!=='Purchase Rate')return oldComparisonNumbers(normalized);const cs=visibleCustomers(),now=visibleOrders().filter(inRange),before=previousOrders(),p=purchaseStats(now,cs),previousCompleted=previousProfileValue('Completed');return {current:p.rate,previous:before&&previousCompleted!=null?(previousCompleted?purchaseStats(before,cs).buyers/previousCompleted*100:0):null,kind:before?'rate':'lifetime'}};
function metricComparisonText(label,d){const v=comparisonDisplay(d),badWhenHigher=/negative|not connected|pending|returned|cancel|not attempted|intermediate/i.test(label),better=v.direction==='up'?!badWhenHigher:v.direction==='down'?badWhenHigher:null;if(v.badge==='No baseline')return {...v,badge:'New',meaning:'Up from zero',quality:badWhenHigher?'worse':'better'};return {...v,meaning:better===null?'No change':better?'Better':'Lower performance',quality:better===null?'neutral':better?'better':'worse'}}
const refinedMetricCard=metricCard;
metricCard=function(label,value,foot,action='',cls=''){if(page!=='dashboard')return refinedMetricCard(label,value,foot,action,cls);const d=comparisonNumbers(label),v=metricComparisonText(label,d),hasBaseline=d.previous!=null&&d.current!=null&&d.kind!=='lifetime';return `<button class="card metric-tile ${cls}" ${action?`onclick="${action}"`:''}><span class="label">${esc(label)}</span><div class="metric-balanced"><strong>${value}</strong><div class="metric-indicators"><span class="metric-icon">${ico(iconForLabel(label))}</span><span class="change-badge quality-${v.quality}">${esc(v.badge)}</span></div></div><small class="previous-line">Previous: <b>${esc(String(v.previous))}</b>${hasBaseline?` <span class="comparison-meaning quality-${v.quality}">${esc(v.meaning)}</span>`:''}</small><small class="metric-context">${esc(label==='Purchase Rate'?'Purchasing completed customers / completed profiles':foot)}</small></button>`};
function canonicalOrderSource(source){const s=String(source||'').toLowerCase();if(/web|website/.test(s))return 'Website';if(/facebook|messenger|\bfb\b/.test(s))return 'Facebook';if(/whatsapp/.test(s))return 'WhatsApp';return 'Other'}
function sourceChartData(os){const confirmed=os.filter(o=>confirmedStatus(o.status));return ['Website','Facebook','WhatsApp','Other'].map(label=>({label,count:confirmed.filter(o=>canonicalOrderSource(o.source)===label).length}))}
confirmedChart=function(os){const sources=sourceChartData(os),selected=chartSource==='All'?os:os.filter(o=>canonicalOrderSource(o.source)===chartSource),confirmed=selected.filter(o=>confirmedStatus(o.status)),colors={Website:'#a2c66f',Facebook:'#81988b',WhatsApp:'#bdd2a8',Other:'#ced4cc'},hourly=range==='1',count=hourly?24:range==='7'?7:30,step=hourly?3600000:86400000,end=Number.isFinite(rangeBounds().end)?Math.min(Date.now(),rangeBounds().end-1):Date.now(),data=Array.from({length:count},(_,i)=>{const at=end-(count-1-i)*step,key=Math.floor((at+21600000)/step),dayOrders=confirmed.filter(o=>Math.floor((new Date(o.created).getTime()+21600000)/step)===key);return {label:hourly?new Date(at).toLocaleTimeString('en-GB',{hour:'numeric',hour12:true,timeZone:'Asia/Dhaka'}):new Date(at).toLocaleDateString('en-GB',{day:'numeric',month:'short',timeZone:'Asia/Dhaka'}),counts:sources.map(s=>({label:s.label,n:dayOrders.filter(o=>canonicalOrderSource(o.source)===s.label).length})),total:dayOrders.length}}),max=Math.max(1,...data.map(x=>x.total));return `<section class="card section-gap source-confirmed-chart"><div class="row between"><h2>Confirmed Orders</h2><span class="badge green">${confirmed.length} in selected period</span></div><p class="small muted">${hourly?'Hourly':'Daily'} · Bangladesh time · latest ${count} ${hourly?'hours':'days'} · source breakdown</p><div class="source-chart-summary"><button class="${chartSource==='All'?'active':''}" onclick="chartSource='All';render()"><span>All sources</span><strong>${os.filter(o=>confirmedStatus(o.status)).length}</strong></button>${sources.map(s=>`<button class="${chartSource===s.label?'active':''}" onclick="chartSource='${s.label}';render()"><span><i style="background:${colors[s.label]}"></i>${s.label}</span><strong>${s.count}</strong><small>${ratio(s.count,os.filter(o=>confirmedStatus(o.status)).length)}</small></button>`).join('')}</div><div class="chart-scroll"><div class="source-bars">${data.map(x=>`<div class="source-bar-column"><span class="source-bar-count">${x.total||''}</span><div class="source-bar-stack" style="height:${Math.max(2,x.total/max*128)}px" title="${esc(x.label)}: ${x.total}">${x.counts.filter(s=>s.n).map(s=>`<i style="height:${s.n/x.total*100}%;background:${colors[s.label]}" title="${esc(s.label)}: ${s.n}"></i>`).join('')}</div><small>${esc(x.label)}</small></div>`).join('')}</div></div></section>`};
const workspaceDashboard=dashboardView;
dashboardView=function(){if(isOwner()&&!ownerBusiness())return heading('Your business','Your Creator will create and assign your business.')+empty('No business has been assigned to this Owner yet.');return workspaceDashboard()};
const finalRefinementRender=render;
render=function(){if(signedIn){if(isOwner()){const shop=ownerBusiness();if(shop&&activeStoreId!==shop.id){loadStore(shop.id);sessionAccount.storeId=shop.id}if(page==='stores')page='dashboard'}if(['owners','platformadmins','platformagents','platformsettings','platformdetail'].includes(page)&&!isCreator())page='dashboard';if(isCreator()&&creatorSelectedShop!=='all'&&['dashboard','customers','orders','new','products','courier','profit','agentreports','settings','team','admins','import'].includes(page)&&!businessStores().some(s=>s.id===activeStoreId)){page='creator'}}finalRefinementRender();if(!signedIn||!sessionAllowed())return;const shop=businessStores().find(s=>s.id===activeStoreId);if(shop?.logo){const workspace=$('.workspace .avatar');if(workspace)workspace.outerHTML=`<img class="avatar business-logo" src="${esc(shop.logo)}" alt="${esc(shop.name)} logo">`}const account=accountRecord(),pill=$('.account-pill');if(pill&&account?.image){const svg=pill.querySelector('svg');if(svg)svg.outerHTML=`<img class="avatar account-image" src="${esc(account.image)}" alt="Your profile">`}$('#view')?.querySelectorAll('.metric-tile,.insight-tile,.stat,.overview-tile').forEach(el=>{const text=el.querySelector('.label,.tile-label')?.textContent?.trim().toLowerCase()||'';if(/^profit|^net profit/.test(text)&&financialAccess()||isCreator()&&text==='net profit')el.classList.add('profit-brand');el.classList.toggle('brand-confirmed',/^confirmed( orders)?$/.test(text));el.dataset.tone='neutral'});};
function extraAccountFields(a={}){return `<div class="form-grid">${field('Phone (optional)','extraPhone',a.phone||'','tel','maxlength="25"')}${field('Job title (optional)','extraTitle',a.title||'','text','maxlength="80"')}</div>${imageUploadField('Profile image','extraImage',a.image||'')}`}
