const completeOwnerSave=saveOwnerAccount;
saveOwnerAccount=async function(e,id){if(!isCreator()){e.preventDefault();return}const f=new FormData(e.target),email=f.get('ownerEmail').trim().toLowerCase(),before=accountByEmail(email);try{const image=await selectedImage(f,'extraImage',before?.image||'');await completeOwnerSave(e,id);const a=accountByEmail(email);if(a?.accountType==='Owner'&&(!before||before.id===id)){Object.assign(a,{phone:String(f.get('extraPhone')||'').trim(),title:String(f.get('extraTitle')||'').trim(),image});persistAuth();render()}}catch(error){toast(error.message)}};
