const editableAccessView=platformAccountsView;
platformAccountsView=function(){let html=editableAccessView();for(const a of authDirectory.accounts.filter(a=>canControlAccount(a))){html=html.replace(`<button onclick="forceLogoutAccount('${a.id}')">Force logout</button>`,`<button onclick="accountEditor('${a.id}')">Edit</button><button onclick="recoveryForAccount('${a.id}')">Reset email</button><button onclick="forceLogoutAccount('${a.id}')">Force logout</button>`)}return html};
function platformDetailMetric(data,type){const orders=data.orders.filter(inRange),confirmed=orders.filter(o=>['Confirmed','Confirm',data.settings.confirmStatus].filter(Boolean).includes(o.status));if(type==='confirmed')return confirmed.length;if(type==='completed')return completedProfileSet(data.customers).length;if(type==='customers')return data.customers.length;if(type==='revenue')return money(sumBy(confirmed,orderTotal));if(type==='delivered'||type==='returned')return orders.filter(o=>o.shipment===(type==='delivered'?'Delivered':'Returned')).length;if(type==='profit'){let total=0;for(const o of confirmed){const costs=o.items.map(x=>x.cost??data.products.find(p=>p.id===x.product)?.cost);if(costs.some(x=>x==null))return 'Cost missing';total+=orderTotal(o)-sumBy(o.items,x=>x.qty*(x.cost??data.products.find(p=>p.id===x.product)?.cost??0))-Number(o.finance?.courierCost??o.delivery)-Number(o.finance?.codFee||0)-Number(o.finance?.packaging||0)-Number(o.finance?.returnFee||0)}return money(total)}return orders.length}
platformDetailView=function(){if(!isCreator())return empty('Creator access only.');return heading('Business details · '+platformDetail,'Selected reporting period. Open a business for its individual records.',`<button onclick="nav('creator')">Back to dashboard</button>`)+`<section class="card"><div class="table-wrap"><table><thead><tr><th>Business</th><th>${esc(platformDetail)}</th><th></th></tr></thead><tbody>${platformShopRows().map(({s,data})=>`<tr><td>${esc(s.name)}</td><td><strong>${esc(platformDetailMetric(data,platformDetail))}</strong></td><td><button onclick="openBusinessMetric('${s.id}','${platformDetail}')">View matching records</button></td></tr>`).join('')||'<tr><td colspan="3">No shops yet.</td></tr>'}</tbody></table></div></section>`};
function openBusinessMetric(id,type){if(!isCreator())return;chooseBusiness(id);if(['confirmed','delivered','returned'].includes(type))dashboardOrders({confirmed:'Confirmed',delivered:'Delivered',returned:'Returned'}[type]);else if(type==='profit')nav('profit');else if(type==='customers'||type==='completed'){nav('customers');if(type==='completed')selectFollowOverview('completed')}else nav('orders')}
const ownerEmptyGuardRender=render;
render=function(){if(signedIn&&isOwner()&&!ownerBusiness()&&!['dashboard','profile','access'].includes(page))page='dashboard';ownerEmptyGuardRender()};
function platformSummaryComparison(label){const current=platformMetrics(),bounds=rangeBounds();if(!Number.isFinite(bounds.start)||!Number.isFinite(bounds.end))return {current:null,previous:null,kind:'lifetime'};const old=platformShopRows().flatMap(({s,data})=>data.orders.filter(o=>{const at=new Date(o.created).getTime();return at>=bounds.start-(bounds.end-bounds.start)&&at<bounds.start}).map(o=>({...o,shopId:s.id,status:['Confirmed','Confirm',data.settings.confirmStatus].filter(Boolean).includes(o.status)?'Confirmed':o.status}))),oldConfirmed=old.filter(o=>o.status==='Confirmed'),key=label.toLowerCase();if(key==='confirmed orders')return {current:current.confirmed.length,previous:oldConfirmed.length,kind:'count'};if(key==='all orders')return {current:current.orders.length,previous:old.length,kind:'count'};if(key==='revenue')return {current:current.revenue,previous:sumBy(oldConfirmed,orderTotal),kind:'money'};if(['delivered','returned'].includes(key)){const status=key==='delivered'?'Delivered':'Returned';return {current:current.orders.filter(o=>o.shipment===status).length,previous:old.filter(o=>o.shipment===status).length,kind:'count'}}return {current:null,previous:null,kind:'snapshot'}}
const balancedSummaryRender=render;
render=function(){balancedSummaryRender();if(!signedIn||!sessionAllowed())return;$('#view')?.querySelectorAll('.insight-tile,.overview-tile').forEach(el=>{const row=el.querySelector('.metric-value-row');if(!row||el.querySelector('.metric-indicators'))return;const label=el.querySelector('.tile-label,.label')?.textContent?.replace('↗','').trim()||'',icon=el.querySelector('.metric-icon'),badge=el.querySelector('.change-badge'),indicators=document.createElement('div');indicators.className='metric-indicators';row.classList.add('metric-balanced');if(icon)indicators.append(icon);if(page==='creator'){const d=platformSummaryComparison(label),v=metricComparisonText(label,d),change=badge||document.createElement('span');change.className='change-badge quality-'+v.quality;change.textContent=v.badge;indicators.append(change);const previous=document.createElement('small');previous.className='previous-line';previous.innerHTML='Previous: <b>'+esc(String(v.previous))+'</b>'+(d.previous!=null&&d.current!=null?` <span class="comparison-meaning quality-${v.quality}">${esc(v.meaning)}</span>`:'');row.after(previous)}else if(badge)indicators.append(badge);else{const hint=el.querySelector('.metric-context,small')?.textContent||'',match=hint.match(/\d+(?:\.\d+)?%/),change=document.createElement('span');change.className='change-badge';change.textContent=match?match[0]:'—';change.title=match?'Share of current total':'No comparison baseline';indicators.append(change)}row.append(indicators)})};

