// Owner-controlled Admin permissions. These controls are browser-demo authorization.
const ADMIN_ACCESS=[['users','Manage Agents & groups',true],['assign','Distribute customers',true],['booking','Book / update / cancel couriers',true],['products','Edit products & prices',false],['import','Import customer and order data',true],['export','Export data & backups',false],['profit','View costs, profit & financial reports',false],['settings','Edit general workspace settings',true],['approval','Approve Agent login / device replacement',false],['logout','Force logout Agents',false],['integration','Change courier integrations / API keys',false]];
function adminAccess(key){if(hasOwnerAuthority())return true;if(role!=='Admin')return false;const a=accountRecord(),defaults=Object.fromEntries(ADMIN_ACCESS.map(([k,,v])=>[k,v]));return Boolean(a?.adminPermissions?.[key]??defaults[key])}
function accessPolicy(key){if(hasOwnerAuthority())return true;if(role==='Admin')return adminAccess(key);if(role==='Agent'&&['profit','settings','products','export','integration','users'].includes(key))return false;return Boolean(currentAgent()?.active&&currentAgent()?.permissions?.[key])}
