const accessManagedSave=saveManagedAccount;
saveManagedAccount=async function(e,id){const a=authDirectory.accounts.find(a=>a.id===id),f=new FormData(e.target);await accessManagedSave(e,id);if(a?.accountType==='Admin'&&hasOwnerAuthority()){a.adminPermissions=Object.fromEntries(ADMIN_ACCESS.map(([k])=>[k,f.getAll('adminAccess').includes(k)]));persistAuth();render()}};
function requireAccess(key){if(hasOwnerAuthority()||role==='Admin'&&adminAccess(key))return true;toast('Your Owner has not enabled this permission.');return false}
// Guard actions as well as navigation, including calls from previously opened forms.
for(const [key,names] of Object.entries({users:['agentForm','saveAgent','toggleAgent','archiveUser','groupForm','saveGroup','deleteGroup'],assign:['assignDialog','unassignDialog','saveAssignment','saveUnassignment','assignCustomers','unassignCustomers'],products:['productForm','saveProduct','toggleProduct','bulkProduct','archiveProduct','productCSVDialog','importProductCSV'],import:['loadCSV','runImport'],settings:['saveSettings','addOption','saveOption','saveMoneySettings','saveHeroSettings','saveBusinessIdentity'],export:['exportOrders','exportProducts'],approval:['manageSession']})){for(const name of names){const original=globalThis[name];if(typeof original!=='function')continue;globalThis[name]=function(...args){if(role==='Admin'&&!requireAccess(key)){args[0]?.preventDefault?.();return}return original.apply(this,args)}}}
const accessForceLogout=forceLogoutAccount;
