// Creator overview is operational: people, customer data and agent performance.
function creatorAgentPerformance(){return platformShopRows().filter(r=>!creatorSelectedShop||creatorSelectedShop==='all'||r.s.id===creatorSelectedShop).flatMap(({s,data})=>data.agents.filter(a=>a.role==='Agent'&&!a.archived).map(a=>{const cs=data.customers.filter(c=>c.agent===a.id),completed=cs.filter(c=>c.call&&!pendingStatus(c.status)).length,os=data.orders.filter(o=>o.agent===a.id&&inRange(o)),confirmed=os.filter(o=>['Confirmed','Confirm',data.settings.confirmStatus].filter(Boolean).includes(o.status)).length;return {shop:s,agent:a,assigned:cs.length,completed,confirmed,rate:cs.length?completed/cs.length*100:0}})).sort((a,b)=>b.confirmed-a.confirmed||b.rate-a.rate).slice(0,8)}
function openCreatorAgent(shopId,id){chooseBusiness(shopId);openAgentReport(id)}
creatorView=function(){if(!isCreator())return empty('Creator access only.');const rows=platformShopRows().filter(r=>!creatorSelectedShop||creatorSelectedShop==='all'||r.s.id===creatorSelectedShop),accounts=authDirectory.accounts.filter(accountMatchesSelectedShop),customers=rows.reduce((n,r)=>n+r.data.customers.length,0),top=creatorAgentPerformance();return heading('Platform Dashboard','People, customer data and business activity across your platform.',rangeSelect())+`<div class="stats platform-summary">${summaryTile('Shops',rows.length,'Independent workspaces',"nav('stores')")}${summaryTile('Customers',customers,'Customer profiles across all shops',"openPlatformDetail('customers')")}${summaryTile('Owners',accounts.filter(a=>a.accountType==='Owner').length,'Business owners',"nav('owners')")}${summaryTile('Admins',accounts.filter(a=>a.accountType==='Admin').length,'Shop administrators',"nav('platformadmins')")}${summaryTile('Agents',accounts.filter(a=>a.role==='Agent').length,'Sales team accounts',"nav('platformagents')")}</div><div class="insight-grid"><section class="card"><h2>Business overview</h2><p class="small muted">Customer profiles per business · click to open workspace</p>${horizontalVisual(rows.map(r=>({label:r.s.name,value:r.data.customers.length,action:`chooseBusiness('${r.s.id}')`})),'count',true)}</section><section class="card"><h2>Account distribution</h2>${ringVisual([{label:'Owners',value:accounts.filter(a=>a.accountType==='Owner').length},{label:'Admins',value:accounts.filter(a=>a.accountType==='Admin').length},{label:'Agents',value:accounts.filter(a=>a.role==='Agent').length}],'accounts')}</section></div><section class="card section-gap"><h2>Top-performing Agents</h2><p class="small muted">Ranked by confirmed orders, then follow-up completion. Open an Agent for details.</p><div class="table-wrap"><table><thead><tr><th>Agent</th><th>Business</th><th>Assigned</th><th>Completed</th><th>Confirmed</th><th>Completion rate</th><th></th></tr></thead><tbody>${top.map(r=>`<tr><td><strong>${esc(r.agent.name)}</strong><br><small>${esc(r.agent.code||'')}</small></td><td>${esc(r.shop.name)}</td><td>${r.assigned}</td><td>${r.completed}</td><td>${r.confirmed}</td><td>${percentage(r.rate)}</td><td><button onclick="openCreatorAgent('${r.shop.id}','${r.agent.id}')">View performance</button></td></tr>`).join('')||'<tr><td colspan="7">No Agent activity yet.</td></tr>'}</tbody></table></div></section>`};

// All Shops keeps the current section and exposes a combined, read-only overview.
function allShopSection(section){const rows=platformShopRows(),titles={dashboard:'Dashboard',customers:'Follow-ups',permanent:'Permanent Clients',orders:'All Orders',new:'New Order',import:'Order Import',products:'Products',courier:'Couriers',profit:'Profit',agentreports:'Agent Reports',team:'Users & groups',admins:'Shop Admins',settings:'Workspace Settings'};if(section==='dashboard')return creatorView();const operational=['new','import','settings','admins'].includes(section);return heading('All Shops · '+(titles[section]||section),'All businesses in this section. Select a shop to view its records or make changes.')+`<section class="card"><div class="table-wrap"><table><thead><tr><th>Business</th><th>${section==='products'?'Products':section==='team'||section==='agentreports'?'Agents':'Customer profiles'}</th><th>${section==='orders'||section==='courier'?'Orders':'Completed follow-ups'}</th><th></th></tr></thead><tbody>${rows.map(({s,data})=>{const first=section==='products'?data.products.filter(p=>!p.archived).length:['team','agentreports'].includes(section)?data.agents.filter(a=>a.role==='Agent'&&!a.archived).length:data.customers.length,second=['orders','courier'].includes(section)?data.orders.filter(inRange).length:data.customers.filter(c=>c.call&&!pendingStatus(c.status)).length;return `<tr><td><strong>${esc(s.name)}</strong></td><td>${first}</td><td>${second}</td><td><button onclick="chooseBusiness('${s.id}')">${operational?'Select shop':'View details'}</button></td></tr>`}).join('')||'<tr><td colspan="4">No shops yet.</td></tr>'}</tbody></table></div></section>`}
for(const [section,name]of Object.entries({dashboard:'dashboardView',customers:'customersView',orders:'ordersView',new:'newOrderView',import:'importView',products:'productsView',courier:'courierView',profit:'profitView',agentreports:'agentReportsView',team:'teamView',admins:'adminAccountsView',settings:'settingsView'})){const original=globalThis[name];globalThis[name]=function(...args){if(isCreator()&&creatorSelectedShop==='all')return allShopSection(page==='permanent'?'permanent':section);return original.apply(this,args)}}
const scopedAccessView=platformAccountsView;
platformAccountsView=function(){if(role!=='Admin')return empty('Account access is restricted.');const selectedShop=isCreator()&&creatorSelectedShop!=='all'?creatorSelectedShop:!isCreator()?activeStoreId:'',accounts=authDirectory.accounts.filter(a=>!a.deletedAt&&(canControlAccount(a)||a.id===sessionAccount?.id&&['Owner','Admin'].includes(a.accountType||a.role)||a.accountType==='Owner'&&businessStores().some(s=>s.id===activeStoreId&&s.owner===a.id))&&(!selectedShop||a.storeId===selectedShop||a.businessId===selectedShop||businessStores().some(s=>s.id===selectedShop&&s.owner===a.id)));const groups=[['Owners',a=>a.accountType==='Owner'],['Admins',a=>a.accountType==='Admin'],['Agents',a=>!['Owner','Admin','Creator'].includes(a.accountType||a.role)]];return heading('Account access','Owners, Admins and Agents are grouped separately. '+(selectedShop?'Showing the selected business.':'Showing all businesses.'))+`<div class="settings-stack">${groups.map(([title,match])=>{const rows=accounts.filter(match);return `<section class="card" data-access-group="${title}"><div class="row between"><h2>${ico('customers')} ${title}</h2><span class="badge">${rows.length} accounts</span></div><div class="table-wrap"><table><thead><tr><th>Name & email</th><th>Business</th><th>Status</th><th>Actions</th></tr></thead><tbody>${rows.map(a=>`<tr><td><strong>${esc(a.name)}</strong>${a.id===sessionAccount?.id?' <span class="badge">You</span>':''}<br><small>${esc(a.email)}</small></td><td>${esc(authDirectory.stores.find(s=>s.id===(a.businessId||a.storeId)||s.owner===a.id)?.name||'Not assigned')}</td><td>${badge(a.active===false?'Inactive':a.emailActivation==='pending'?'Pending verification':'Active')}</td><td><div class="row">${a.id===sessionAccount?.id?`<button onclick="nav('profile')">My Profile</button>`:!canControlAccount(a)?'<span class="small muted">View only</span>':`<button onclick="accountEditor('${a.id}')">Edit</button><button onclick="recoveryForAccount('${a.id}')">Reset email</button>${hasOwnerAuthority()||adminAccess('logout')?`<button onclick="forceLogoutAccount('${a.id}')">Force logout</button>`:''}<button onclick="setPlatformAccountActive('${a.id}',${a.active===false})">${a.active===false?'Activate':'Deactivate'}</button>${a.emailActivation==='pending'?`<button onclick="verificationPreview('${a.id}')">Verification preview</button>`:''}`}</div></td></tr>`).join('')||'<tr><td colspan="4">No accessible accounts in this section.</td></tr>'}</tbody></table></div></section>`}).join('')}</div>`};

function accountMatchesSelectedShop(a){if(!isCreator()||!creatorSelectedShop||creatorSelectedShop==='all')return true;const shop=businessStores().find(s=>s.id===creatorSelectedShop);return a.storeId===creatorSelectedShop||a.businessId===creatorSelectedShop||shop?.owner===a.id}

// Removing accounts disables login and keeps historical attribution intact.
const removalCanControl=canControlAccount;
canControlAccount=function(a){return Boolean(a&&!a.deletedAt&&removalCanControl(a))};
const removalShopMatch=accountMatchesSelectedShop;
accountMatchesSelectedShop=function(a){return !a.deletedAt&&removalShopMatch(a)};
function canRemoveAccount(a){return Boolean(a&&!a.deletedAt&&a.id!==sessionAccount?.id&&a.accountType!=='Creator'&&canControlAccount(a))}
async function removeAccount(id){refreshDirectory();const a=authDirectory.accounts.find(a=>a.id===id);if(!canRemoveAccount(a))return toast('You cannot remove this account.');const type=a.accountType||a.role,confirmed=await askConfirm('Remove '+type+'?',`Remove ${a.name} (${a.email})? Login will be disabled and current sessions revoked. Orders and customer history will be kept.${type==='Owner'?' The shop will remain and can be assigned to another Owner.':' Assigned customers will become unassigned.'}`);if(!confirmed)return;return commitAccountRemoval(id)}
function commitAccountRemoval(id){refreshDirectory();const a=authDirectory.accounts.find(a=>a.id===id);if(!canRemoveAccount(a))return toast('You cannot remove this account.');const at=new Date().toISOString(),shopId=a.businessId||a.storeId;Object.assign(a,{active:false,deletedAt:at,deletedBy:sessionAccount.id,sessionVersion:(a.sessionVersion||0)+1});(authDirectory.sessions||[]).filter(s=>s.account===id).forEach(s=>s.revoked=true);if(a.memberId){const data=a.storeId===activeStoreId?db:readStore(a.storeId);if(data){const member=data.agents.find(m=>m.id===a.memberId);if(member)Object.assign(member,{active:false,archived:true,deletedAt:at});data.customers.filter(c=>c.agent===a.memberId).forEach(c=>{c.agent='';c.permanent=false});(data.groups||[]).forEach(g=>g.members=g.members.filter(m=>m!==a.memberId));(data.sessions||[]).filter(s=>s.user===a.memberId&&['Approved','Pending'].includes(s.status)).forEach(s=>s.status='Revoked');localStorage.setItem('jioflow.store.'+a.storeId,JSON.stringify(data));if(a.storeId===activeStoreId)db=data}}if(a.accountType==='Owner'){authDirectory.stores.filter(s=>s.owner===a.id).forEach(s=>s.owner='');a.removedFromShop=shopId;a.businessId='';a.storeId=''}persistAuth();creatorAudit('Removed '+(a.accountType||a.role)+': '+a.email);closeModal();render();toast('Account removed. Login disabled; order and customer history preserved.');return true}
function removalButtons(html){for(const a of authDirectory.accounts.filter(canRemoveAccount)){const button=`<button class="danger" onclick="removeAccount('${a.id}')">Remove</button>`,handlers=[`onclick="accountEditor('${a.id}')"`,a.memberId?`onclick="adminAccountForm('${a.memberId}')"`:'',a.memberId?`onclick="agentForm('${a.memberId}')"`:''];for(const handler of handlers){const at=handler?html.indexOf(handler):-1;if(at>=0){const end=html.indexOf('</button>',at)+9;if(end>=9)html=html.slice(0,end)+button+html.slice(end);break}}}return html}

const removalDirectory=platformDirectoryView;
