 holder.querySelectorAll('.metric-tile,.insight-tile,.stat,.overview-tile').forEach(el=>{const label=el.querySelector('.label,.tile-label')?.textContent?.trim()||'';el.dataset.tone='neutral';if(!el.querySelector('.metric-icon'))el.insertAdjacentHTML('beforeend','<span class="metric-icon">'+ico(iconForLabel(label))+'</span>');if(/^(Profit|Net profit)$/.test(label))el.classList.add('profit-brand');if(/^Confirmed( Orders)?$/.test(label))el.classList.add('brand-confirmed')});
