 const orders=visibleOrders().filter(inRange).filter(o=>type==='delivered'?o.shipment==='Delivered':confirmedStatus(o.status)).filter(o=>!['agent','source','product'].includes(type)||type==='agent'&&o.agent===key||type==='source'&&o.source===key||type==='product'&&o.items.some(x=>x.product===key));
