const originalReadActions={dashboardOrders,dashboardCustomers,openFunnel,openStatus,sourceQueue,ordersForProduct,setFollowCall,setFollowUnattempted,openAgentReport,openAgentMetric,selectReportFilter,selectOrderOverview,selectFollowOverview,resetFollowFilters,profitDetail:originalProfitDetails,openCourierBalance:()=>originalProfitDetails('delivered','')};
function parseOriginalReadAction(click){
 const m=click.match(/^([A-Za-z]+)\((.*)\)$/);if(!m||!Object.hasOwn(originalReadActions,m[1]))return null;
 const args=[];let rest=m[2].trim();while(rest){const token=rest.match(/^(?:'([^'\\]*)'|("(?:[^"\\]|\\.)*")|(-?\d+))(?:\s*,\s*|$)/);if(!token)return null;args.push(token[1]!==undefined?token[1]:token[2]?JSON.parse(token[2]):Number(token[3]));rest=rest.slice(token[0].length)}
 return {name:m[1],args};
}
function originalReadAction(action){
 if(!action||!Object.hasOwn(originalReadActions,action.name))return;
 const savedNav=nav,savedRender=render;
 try{render=()=>{};nav=p=>{page=p;subtab='All';query='';pageNo=1;selected.clear();window.callFilter='';window.responseFilter='';window.funnelFilter='';window.customerSource=''};originalReadActions[action.name](...action.args);originalScreen=page==='customers'?'followups':page}
 finally{nav=savedNav;render=savedRender}
}
